/* 自动生成，请勿手工修改。来源：DSH physics/phy-mech；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"phy-mech-1","title":"机械运动与速度","subtitle":"人教版八上 · 第 1 章 机械运动 · 8a","grade":"8a","tags":["人教版八上 · 第 1 章 机械运动"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八上 · 第 1 章 机械运动 · 8a"},{"type":"note","title":"问题切入","text":"坐在行驶的公交车里，你是运动的还是静止的？为什么同一个人的答案可以完全相反？又该怎么用一句话说清谁更快？"},{"type":"note","title":"一句话抓住关键","text":"判断运动先选参照物：位置相对参照物改变了就是运动。比较快慢统一成速度 $v=\\frac{s}{t}$；s-t 图的斜率是速度，v-t 图的高度是速度；平均速度永远等于总路程除以总时间。"},{"type":"h","text":"先看现象：同一个人，两个都对的答案"},{"type":"p","text":"坐在车里的乘客说自己是「静止」的，因为他相对座椅没有动；站在站台上的人说他「飞快地过去了」，因为他相对站牌在移动。两个说法都没错，差别只在于各自选了谁当参照物。所以物理上不允许只说「某物体是运动的」，必须补一句「以……为参照物」。"},{"type":"figure","figure":{"id":"fig-mech-motion-1","title":"同一辆车，两种说法","caption":"以座椅为参照物乘客静止，以站牌为参照物乘客在运动","view":"wide","alt":"一辆公交车向右行驶，车内坐着乘客，路边立着站牌，车前方标出速度方向的箭头","prims":[{"t":"line","x1":6,"y1":46,"x2":94,"y2":46,"width":0.8},{"t":"hatch","x":6,"y":46,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":12,"y":20,"w":48,"h":22,"rx":2,"fill":true,"tone":"main"},{"t":"circle","cx":24,"cy":43.4,"r":2.8},{"t":"circle","cx":50,"cy":43.4,"r":2.8},{"t":"text","x":26,"y":31,"text":"乘客","size":3.8},{"t":"arrow","x1":62,"y1":27,"x2":80,"y2":27,"tone":"accent","label":"v","labelDy":-3},{"t":"line","x1":88,"y1":46,"x2":88,"y2":30,"width":0.6},{"t":"rect","x":82,"y":24,"w":12,"h":6,"label":"站牌"},{"t":"text","x":50,"y":54,"text":"以座椅为参照物：静止","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":59,"text":"以站牌为参照物：运动","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"参照物一旦选定就当成不动；不能选研究对象自己作参照物，否则它永远是静止的。"},{"type":"h","text":"抓住哪个量：位置的变化，靠参照物判断"},{"type":"p","text":"把「运动」翻译成可测量的话：物体相对参照物的位置随时间改变，就是机械运动。位置没变就叫静止。判断时只看两件事——跟谁比（参照物）、位置变没变，与物体自己有没有「用力」无关。"},{"type":"figure","figure":{"id":"fig-mech-motion-2","title":"位置有没有改变，要看跟谁比","caption":"小车先后在两个时刻的位置，路边那棵树就是参照物","view":"wide","alt":"一辆小车先后经过左右两个位置，两个位置之间有一个向右的箭头，右侧路边有一棵树作为参照物","prims":[{"t":"line","x1":6,"y1":44,"x2":94,"y2":44,"width":0.8},{"t":"hatch","x":6,"y":44,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":10,"y":30,"w":16,"h":12,"dashed":true,"tone":"muted","label":"t₁"},{"t":"rect","x":54,"y":30,"w":16,"h":12,"fill":true,"tone":"accent","label":"t₂"},{"t":"arrow","x1":28,"y1":36,"x2":52,"y2":36,"tone":"accent","label":"位置改变","labelDy":-3},{"t":"line","x1":86,"y1":44,"x2":86,"y2":24,"width":0.6,"tone":"ok"},{"t":"circle","cx":86,"cy":20,"r":3.4,"tone":"ok","fill":true},{"t":"text","x":86,"y":13,"text":"树（参照物）","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":52,"text":"相对参照物位置改变 → 小车是运动的","size":3.6,"tone":"muted"}]}},{"type":"h","text":"建立关系：把「快慢」变成一个数"},{"type":"p","text":"比较快慢有两种临时办法：时间相同时比路程，路程相同时比时间。两种办法合起来，就是「单位时间内通过的路程」，也就是速度 v=(s)/(t)。注意 s 与 t 必须来自同一段运动：算哪一段速度，就用那一段的路程和那一段时间。"},{"type":"figure","figure":{"id":"fig-mech-motion-3","title":"比较快慢的两种办法","caption":"时间相同比路程：路程长的更快","view":"wide","alt":"甲、乙两辆车从同一地点同时出发，相同时间内甲通过的路程明显比乙长，说明甲运动得更快","prims":[{"t":"text","x":50,"y":8,"text":"同时出发，相同时间","size":3.8,"tone":"muted"},{"t":"line","x1":10,"y1":12,"x2":10,"y2":40,"dashed":true,"tone":"muted"},{"t":"arrow","x1":10,"y1":20,"x2":62,"y2":20,"tone":"accent"},{"t":"circle","cx":66,"cy":20,"r":3,"fill":true,"tone":"accent","label":"甲","labelDy":-6},{"t":"arrow","x1":10,"y1":36,"x2":34,"y2":36,"tone":"main"},{"t":"circle","cx":38,"cy":36,"r":3,"fill":true,"label":"乙","labelDy":-6},{"t":"line","x1":6,"y1":44,"x2":94,"y2":44,"width":0.6,"dashed":true,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"时间相同，甲的路程长 → 甲更快","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"换成路程相同，则甲用的时间短","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"速度单位由路程与时间单位共同决定：m/s 与 km/h 的换算关系是 1 m/s = 3.6 km/h。"},{"type":"h","text":"换一种表示：图像上的速度"},{"type":"p","text":"同一段匀速直线运动可以画成两种图，读法完全不同。s-t 图上是一条倾斜直线，越陡速度越大，斜率就是速度；v-t 图上是一条水平直线，高度就是速度，它与时间轴围成的面积是路程（初中只需读出高度）。图线变水平要分清含义：s-t 图水平表示静止，v-t 图水平表示匀速。"},{"type":"figure","figure":{"id":"fig-mech-motion-4","title":"s-t 图与 v-t 图","caption":"同一次匀速直线运动的两种画法","view":"square","alt":"左图是过原点的倾斜直线表示路程随时间成正比，斜率是速度；右图是与时间轴平行的水平直线，高度表示速度不变","prims":[{"t":"axis","x":10,"y":46,"w":34,"h":32,"xLabel":"t","yLabel":"s","origin":true},{"t":"curve","points":[[10,46],[44,14]],"tone":"accent"},{"t":"text","x":27,"y":6,"text":"（a）s-t 图：斜率是速度","size":3.5,"tone":"muted"},{"t":"text","x":27,"y":56,"text":"路程与时间成正比","size":3.5,"tone":"muted"},{"t":"axis","x":58,"y":46,"w":34,"h":32,"xLabel":"t","yLabel":"v","origin":true},{"t":"curve","points":[[58,26],[92,26]],"tone":"accent"},{"t":"text","x":75,"y":6,"text":"（b）v-t 图：高度是速度","size":3.5,"tone":"muted"},{"t":"text","x":75,"y":56,"text":"速度保持不变","size":3.5,"tone":"muted"}]}},{"type":"h","text":"换个情境：平均速度是总路程除以总时间"},{"type":"p","text":"真实运动很少全程匀速：上坡慢、下坡快。这时用平均速度描述整体快慢，v=s_(总)t_(总)。它绝不是把几段速度加起来除以段数——因为各段用的时间不同，速度快的段对总时间的贡献小，直接取算术平均一定偏大。"},{"type":"figure","figure":{"id":"fig-mech-motion-5","title":"平均速度不是速度的平均","caption":"前半程 20 m/s、后半程 30 m/s，全程平均速度只有 24 m/s","view":"wide","alt":"一段总长 1200 米的路程分成两段各 600 米，前段速度 20 米每秒，后段速度 30 米每秒，全程平均速度是 24 米每秒","prims":[{"t":"line","x1":10,"y1":30,"x2":90,"y2":30,"width":0.6},{"t":"line","x1":10,"y1":26,"x2":10,"y2":34,"width":0.5},{"t":"line","x1":50,"y1":26,"x2":50,"y2":34,"width":0.5},{"t":"line","x1":90,"y1":26,"x2":90,"y2":34,"width":0.5},{"t":"arrow","x1":12,"y1":30,"x2":47,"y2":30,"tone":"accent"},{"t":"arrow","x1":52,"y1":30,"x2":87,"y2":30,"tone":"main"},{"t":"text","x":28,"y":18,"text":"前 600 m：20 m/s","size":3.6,"tone":"accent"},{"t":"text","x":72,"y":18,"text":"后 600 m：30 m/s","size":3.6,"tone":"main"},{"t":"text","x":50,"y":42,"text":"总路程 1200 m，总时间 30 s + 20 s = 50 s","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"平均速度 = 1200 m ÷ 50 s = 24 m/s","size":3.8,"tone":"ok"}]}},{"type":"note","title":"","text":"平均速度必须与「哪一段路程」对应：同一段路，算全程与算半程得到的值可以不同。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["速度","v = (s)/(t)","v：米每秒（m/s）；s：米（m）；t：秒（s） · 适用于任何一段运动，匀速直线运动中 v 为定值。s 与 t 必须取自同一段运动、同一段时间；变形用法 s=vt（求路程）、t=(s)/(v)（求时间）。"],["单位换算","1\\ m/s = 3.6\\ km/h","1 m/s = 3.6 km/h；1 km/h = \\frac{1}{3.6} m/s · km/h 化成 m/s 除以 3.6，m/s 化成 km/h 乘 3.6。比较快慢、代入公式计算前必须先把单位统一成 m/s 或 km/h。"],["平均速度","v = s_(总)t_(总)","v：米每秒（m/s）；s总：米（m）；t总：秒（s） · 描述变速运动的整体快慢，只对「整段路程」有意义，不能当成各段速度的算术平均；停留时间也要计入 t 总（比如中途休息 10 min）。"]]},{"type":"h","text":"应用 · 应用一：三种出行方式，谁更快"},{"type":"note","title":"情境","text":"小明步行 1.2 km 用了 15 min；他骑自行车时的速度约 5 m/s；爸爸开车以 54 km/h 在市区行驶。比较三者的快慢。"},{"type":"note","title":"模型与思路","text":"比较快慢必须先统一单位。把三个速度都化成 m/s：路程用 m、时间用 s，或把 km/h 除以 3.6。"},{"type":"list","title":"解答步骤","items":["步行：v₁=(s)/(t)=1200\\ m900\\ s≈ 1.3\\ m/s","自行车：v₂=5\\ m/s（已经是国际单位，不用换算）","汽车：v₃=54\\ km/h=(54)/(3.6)\\ m/s=15\\ m/s","比较：1.3\\ m/s<5\\ m/s<15\\ m/s"]},{"type":"figure","figure":{"id":"fig-mech-motion-6","title":"三个速度放在同一把尺子上","caption":"箭头长度与速度成正比，单位统一后才能比","view":"wide","alt":"三条箭头的长度分别表示步行 1.3 米每秒、自行车 5 米每秒、汽车 15 米每秒，汽车箭头最长","prims":[{"t":"text","x":50,"y":8,"text":"统一单位后的速度（m/s）","size":3.8,"tone":"muted"},{"t":"text","x":4,"y":20,"text":"步行","anchor":"start","size":3.8},{"t":"arrow","x1":24,"y1":20,"x2":29.3,"y2":20,"tone":"muted"},{"t":"text","x":32,"y":20,"text":"1.3 m/s","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":4,"y":34,"text":"自行车","anchor":"start","size":3.8},{"t":"arrow","x1":24,"y1":34,"x2":44,"y2":34,"tone":"accent"},{"t":"text","x":47,"y":34,"text":"5 m/s","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":4,"y":48,"text":"汽车","anchor":"start","size":3.8},{"t":"arrow","x1":24,"y1":48,"x2":84,"y2":48,"tone":"main"},{"t":"text","x":86,"y":48,"text":"15 m/s","anchor":"start","size":3.6,"tone":"main"}]}},{"type":"note","title":"结论","text":"汽车最快，自行车次之，步行最慢；三者速度之比约为 1 : 4 : 11。"},{"type":"h","text":"应用 · 应用二：求全程平均速度"},{"type":"note","title":"情境","text":"一辆汽车在平直公路上行驶，全程 1500 m。前一半路程的速度是 15 m/s，后一半路程的速度是 25 m/s。求全程的平均速度。"},{"type":"note","title":"模型与思路","text":"平均速度的定义是总路程除以总时间。已知的是各段的路程与速度，先用 t=(s)/(v) 分别求出各段所用时间，再求总时间。"},{"type":"list","title":"解答步骤","items":["前一半路程 s₁=750\\ m，速度 v₁=15\\ m/s，时间 t₁=(750)/(15)\\ s=50\\ s","后一半路程 s₂=750\\ m，速度 v₂=25\\ m/s，时间 t₂=(750)/(25)\\ s=30\\ s","总时间 t=t₁+t₂=80\\ s，总路程 s=1500\\ m","v=(s)/(t)=(1500)/(80)\\ m/s=18.75\\ m/s"]},{"type":"note","title":"结论","text":"全程平均速度是 18.75 m/s，约合 67.5 km/h，不是 20 m/s（两段速度的算术平均）。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["把各段速度取算术平均当成平均速度，如 20 m/s 与 30 m/s 两段直接答 25 m/s。","平均速度是总路程除以总时间。路程各半时，$\\bar v=\\frac{2v_1v_2}{v_1+v_2}=24\\ \\mathrm{m/s}$，不是 25 m/s。","两段用时不同：快的那段用时短，对整体的贡献小，直接平均等于把它的权重放大了。"],["说「小明是静止的」或「小明是运动的」就结束，不写参照物。","必须写清以谁为参照物：以座椅为参照物小明静止，以地面为参照物小明运动。","运动与静止是相对的，没有参照物的运动描述是不完整的，说理题直接不得分。"],["看到 s-t 图是水平直线，就说物体在匀速运动。","s-t 图水平表示路程不再增加，物体静止；v-t 图水平才表示速度不变、匀速运动。","同一形状在不同图像里含义不同，读图第一步永远是先看清横轴、纵轴各是什么物理量。"]]},{"type":"table","title":"s-t 图像与 v-t 图像（同一段运动，两种图像的读法完全不同）","head":["比较项","s-t 图像","v-t 图像"],"rows":[["纵轴物理量","路程 s","速度 v"],["匀速直线运动","过原点的倾斜直线","平行于时间轴的水平直线"],["静止","平行于时间轴的水平直线（s 不变）","与时间轴重合（v=0）"],["如何读出速度","求图线的斜率，斜率越大越快","直接读纵坐标的数值"],["常见设问","哪条线对应哪个物体、何时相遇","速度多大、何时改变速度"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["参照物与相对运动的判断","给一段生活情境（会车、电梯、加油机、传阅卷子），要求判断以谁为参照物、谁静止谁运动，落脚点是「运动与静止的相对性」这一句话。"],["图像信息的提取与计算","给出 s-t 或 v-t 图像，要求读出速度、求出某段时间的路程，或比较两个物体的快慢；常与「图线的拐点表示状态改变」结合命题。"],["速度、路程、时间的计算","以列车过桥、汽车过隧道、跑步测速为情境，注意「完全通过」要把车长算进路程；也常在非选择题里要求统一单位后再计算。"],["估测与单位换算","选择题常考生活量级估测（步行约 1.2 m/s、自行车约 5 m/s）与 km/h 与 m/s 的换算，错在把 1 m/s 当成 3.6 km/h 的倒数。"]]},{"type":"quote","text":"【材料一】复兴号动车组列车的最高运营时速可达 350 km/h；城市地铁在市区的旅行速度（含停站）通常在 35～40 km/h。\n【材料二】小明家离学校 3.6 km，他骑自行车上学，路上共用了 12 min，途中遇到两次红灯，每次停车约 30 s。\n【材料三】描述一个物体运动时，物理上要求先说明参照物：同一辆车里的乘客，相对座椅是静止的，相对路面是运动的。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）把复兴号动车组的最高运营时速 350 km/h 换算成 m/s，结果保留一位小数。（4 分）","【设问】（2）求小明骑车上学的平均速度，分别用 m/s 和 km/h 表示（含等红灯的时间）。（6 分）","【设问】（3）小明说：「我骑车有时快有时慢，用平均速度根本说不清我的速度。」请依据材料三和速度的知识，评价他的说法并说明平均速度的意义。（4 分）"]}],"questions":[{"id":"phy-mech-1-q1","type":"choice","stem":"坐在行驶的公交车里的乘客说自己是静止的，他选择的参照物是","answer":"B","explain":"判断依据是「相对谁的位置没有改变」。乘客相对自己乘坐的公交车位置不变，所以以公交车为参照物他是静止的。A、C 两个选项里，乘客相对树木和路面的位置都在不断改变，以它们为参照物乘客是运动的；D 中迎面驶来的车与他的相对位置变化更快，只能说相对那辆车他在运动。","options":["路旁的树木","他乘坐的公交车","路面","迎面驶来的另一辆公交车"],"difficulty":1,"tags":["参照物","运动的相对性"]},{"id":"phy-mech-1-q2","type":"choice","stem":"下列四个速度中，最接近正常人步行速度的是","answer":"A","explain":"正常人步行约 1.1—1.4 m/s，A 符合量级。B 的 12 m/s 合 43.2 km/h，比世界百米冠军还快得多；C 的 1.2 km/h 合 0.33 m/s，比蜗牛快不了多少；D 的 12 km/h 合 3.3 m/s，接近慢跑甚至快跑的速度，不是步行。估测题的关键是把 m/s 换算成 km/h 再和熟悉的速度作比较。","options":["1.2 m/s","12 m/s","1.2 km/h","12 km/h"],"difficulty":1,"tags":["速度估测","单位换算"]},{"id":"phy-mech-1-q3","type":"choice","stem":"下图是甲、乙两个物体同时同地出发做直线运动的 s-t 图像，由图可知","answer":"C","explain":"s-t 图上的倾斜直线表示匀速直线运动，图线越陡表示相同时间内路程越大、速度越大，甲比乙陡，所以甲的速度大于乙，C 正确、D 错误。A 错：静止在 s-t 图上应是一条水平线，而甲的 s 在不断增加。B 错：图中没有给出乙的具体路程和对应时间，无法读出 4 m/s 这个数；即使给出数据，也要用 s 除以 t 才能算出速度。","options":["甲物体处于静止状态","乙的速度是 4 m/s","甲的速度大于乙的速度","甲、乙两物体的速度相同"],"difficulty":2,"tags":["s-t 图像","读图"],"figure":{"id":"fig-mech-motion-q3","title":"甲、乙的 s-t 图像","caption":"两条线都是过原点的倾斜直线，甲更陡","view":"square","alt":"纵轴为路程、横轴为时间的图像上，有两条从原点出发的倾斜直线，甲的直线比乙更陡","prims":[{"t":"axis","x":20,"y":84,"w":68,"h":66,"xLabel":"t/s","yLabel":"s/m","origin":true},{"t":"curve","points":[[20,84],[86,20]],"tone":"accent"},{"t":"curve","points":[[20,84],[86,46]],"tone":"main"},{"t":"text","x":62,"y":30,"text":"甲","size":4,"tone":"accent"},{"t":"text","x":80,"y":56,"text":"乙","size":4},{"t":"text","x":50,"y":96,"text":"两条线都过原点，都在做匀速直线运动","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-1-q4","type":"choice","stem":"汽车在高速公路上以 72 km/h 的速度行驶，这个速度等于","answer":"D","explain":"km/h 化成 m/s 要除以 3.6：72÷ 3.6=20，所以是 20 m/s，D 正确。A 是把数值缩小了 10 倍，既没有按 3.6 换算，数量级也不对。B 直接把单位换成 m/s、数值不变，等于把速度夸大了 3.6 倍。C 是把「除以 3.6」错做成了「乘 3.6」。","options":["7.2 m/s","72 m/s","259.2 m/s","20 m/s"],"difficulty":1,"tags":["单位换算"]},{"id":"phy-mech-1-q5","type":"fill","stem":"小明骑自行车 5 min 通过了 1800 m，他骑车的速度是＿＿m/s。","answer":"6|6.0","explain":"先把时间化成秒：5\\ min=300\\ s；再代入 v=(s)/(t)=1800\\ m300\\ s=6\\ m/s（约 21.6 km/h，与骑车速度的量级相符）。答 360 m/s 之类，都是忘了把分钟换成秒。","difficulty":1,"tags":["速度计算","单位换算"]},{"id":"phy-mech-1-q6","type":"fill","stem":"一辆汽车在平直公路上行驶，前 400 m 用了 50 s，后 400 m 用了 30 s，它在这 800 m 内的平均速度是＿＿m/s。","answer":"10|10.0","explain":"平均速度用总路程除以总时间：bar v=(400+400)/(50+30)\\ m/s=(800)/(80)\\ m/s=10\\ m/s。若分别算出两段速度 8 m/s 和 13.3 m/s 再取平均，得到 10.7 m/s，那是错的——两段用时不同，直接平均放大了快的那一段的权重。","difficulty":2,"tags":["平均速度"]},{"id":"phy-mech-1-q7","type":"short","stem":"一列长 200 m 的火车以 20 m/s 的速度匀速通过一座长 1600 m 的大桥，求火车完全通过大桥需要多少时间。","answer":"火车完全通过大桥，指的是从车头上桥到车尾离桥，机车走过的路程等于桥长加车长：$s=1600\\ \\mathrm{m}+200\\ \\mathrm{m}=1800\\ \\mathrm{m}$。由 $v=\\frac{s}{t}$ 得 $t=\\frac{s}{v}=\\frac{1800\\ \\mathrm{m}}{20\\ \\mathrm{m/s}}=90\\ \\mathrm{s}$。","explain":"这道题考的不是算除法，而是「路程从哪一段算起」。火车有长度：车头刚到桥头时车尾还在桥外，直到车尾离开桥的另一端，火车才算完全通过，所以路程必须是桥长加车长。若只算桥长，得到 80 s，那是从车头上桥到车头出桥的时间。","difficulty":2,"tags":["速度计算","过桥问题"],"rubric":["写出火车通过的路程等于桥长加车长（1800 m）","写出公式并正确变形 t = s / v","代入数据、单位统一（m 与 m/s）","计算正确得 90 s，并有结论性作答"],"steps":["明确研究对象与过程：研究火车车头（或车尾）的运动，完全通过是从车头上桥到车尾离桥。","求路程：s=s_(桥)+s_(车)=1600\\ m+200\\ m=1800\\ m。","选公式：匀速运动中 v=(s)/(t)，变形得 t=(s)/(v)。","代入数据并计算：t=1800\\ m20\\ m/s=90\\ s。","作答：火车完全通过大桥需要 90 s。"]},{"id":"phy-mech-1-q8","type":"short","stem":"某小组要测量小车沿斜面下滑的平均速度，请写出实验所需的器材、主要步骤，并说明为什么要用「金属片」挡在斜面底端。","answer":"器材：长木板（或斜面）、小车、刻度尺、停表、金属片（挡板）、木块（垫高斜面用）。步骤：① 用木块把木板一端垫高，做成一个坡度较小的斜面，用刻度尺量出小车要经过的路程 s；② 把金属片放在斜面底端，让小车从斜面顶端由静止释放，用停表测出小车从顶端运动到底端的时间 t；③ 由 $v=\\frac{s}{t}$ 算出小车在下半段（或全程）的平均速度；④ 改变路程重复测量三次，取平均值以减小误差。金属片的作用：一是让小车在固定位置停下，二是撞击时发出声音，便于计时者听声按表，减小计时误差。","explain":"实验题的踩分点在「怎么让测量更准」：坡度要小，是为了让小车下滑慢一些、时间长一些，计时误差相对更小；终点用金属片固定，是为了保证每次测量的路程完全相同；从同一位置由静止释放，是为了保证小车到达底端的速度相同、路程与时间一一对应。缺了这些交代，得到的平均速度就不可比。","difficulty":2,"tags":["实验探究","平均速度","控制变量"],"rubric":["器材齐全（斜面、小车、刻度尺、停表、金属片）","操作规范：小车从斜面顶端由静止释放，用刻度尺量路程、停表测时间","用公式 v = s / t 计算，并多次测量取平均值减小误差","说清金属片的作用：固定终点位置、用声音帮助准确计时"]},{"id":"phy-mech-1-q9","type":"short","stem":"某物体在 0—4 s 内以 2 m/s 的速度做匀速直线运动，4—6 s 内保持静止。请在下图的坐标系中画出该物体 0—6 s 的 v-t 图像。","answer":"0—4 s 内速度恒为 2 m/s，图像是一条高 2 的水平线；t=4 s 时速度变为 0，图像竖直下降到时间轴上；4—6 s 内速度保持 0，图像与时间轴重合。","explain":"v-t 图像画的是「速度随时间怎么变」，不是路程。0—4 s 速度不变，画水平线；4 s 时刻速度从 2 m/s 变成 0，图像上表现为竖直下落；4—6 s 速度一直是 0，图线就压在时间轴上。最常见的错误是把 0—4 s 画成斜线——那是 s-t 图的画法，说明还没有分清横纵轴各代表什么。","difficulty":2,"tags":["作图题","v-t 图像"],"rubric":["0—4 s 画成高度为 2 m/s 的水平线（不是倾斜线）","t=4 s 处速度由 2 m/s 变为 0（竖直下落到时间轴或直接画成两段水平线）","4—6 s 画成与时间轴重合的线段（v=0）","标出 v 的单位或刻度、图线端点位置与坐标对应正确"],"figure":{"id":"fig-mech-motion-q9-blank","title":"待画的 v-t 坐标系","caption":"纵轴为速度，横轴为时间，按刻度把数据点描出来再连线","view":"square","alt":"一个空白的速度时间坐标系，纵轴标出 1 和 2 米每秒，横轴标出 4 秒和 6 秒","prims":[{"t":"axis","x":22,"y":82,"w":66,"h":62,"xLabel":"t/s","yLabel":"v/(m·s⁻¹)","origin":true,"grid":true,"xTicks":[{"at":0.67,"label":"4"},{"at":1,"label":"6"}],"yTicks":[{"at":0.5,"label":"1"},{"at":1,"label":"2"}]}]},"answerFigure":{"id":"fig-mech-motion-q9-ans","title":"v-t 图像的标准画法","caption":"先水平后竖直下落，再到时间轴上保持水平","view":"square","alt":"速度时间图像：0 到 4 秒是一条高度为 2 米每秒的水平线，4 秒处竖直下降到时间轴，4 到 6 秒与时间轴重合","prims":[{"t":"axis","x":22,"y":82,"w":66,"h":62,"xLabel":"t/s","yLabel":"v/(m·s⁻¹)","origin":true,"xTicks":[{"at":0.67,"label":"4"},{"at":1,"label":"6"}],"yTicks":[{"at":0.5,"label":"1"},{"at":1,"label":"2"}]},{"t":"curve","points":[[22,20],[66,20],[66,82],[88,82]],"tone":"accent","width":0.9},{"t":"text","x":44,"y":14,"text":"匀速 2 m/s","size":3.4,"tone":"accent"},{"t":"text","x":78,"y":74,"text":"静止","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-1-m1-q1","type":"short","stem":"（1）把复兴号动车组的最高运营时速 350 km/h 换算成 m/s，结果保留一位小数。（4 分）","answer":"$350\\ \\mathrm{km/h}=\\frac{350}{3.6}\\ \\mathrm{m/s}\\approx 97.2\\ \\mathrm{m/s}$。","explain":"","tags":["单位换算","速度"],"rubric":["写出换算关系 1 m/s = 3.6 km/h（或用 350 ÷ 3.6）","正确算出 97.2","结果带单位 m/s","按要求保留一位小数"]},{"id":"phy-mech-1-m1-q2","type":"short","stem":"（2）求小明骑车上学的平均速度，分别用 m/s 和 km/h 表示（含等红灯的时间）。（6 分）","answer":"总路程 $s=3.6\\ \\mathrm{km}=3600\\ \\mathrm{m}$，总时间 $t=12\\ \\mathrm{min}=720\\ \\mathrm{s}$（等红灯的时间已经包含在这 12 min 内，不能另外减去）。$\\bar v=\\frac{s}{t}=\\frac{3600\\ \\mathrm{m}}{720\\ \\mathrm{s}}=5\\ \\mathrm{m/s}=18\\ \\mathrm{km/h}$。","explain":"","tags":["平均速度","单位换算"],"rubric":["把 3.6 km 化成 3600 m（单位统一）","把 12 min 化成 720 s","明确说明等红灯时间计入总时间","用总路程除以总时间求出 5 m/s","换算成 18 km/h 并带单位"]},{"id":"phy-mech-1-m1-q3","type":"short","stem":"（3）小明说：「我骑车有时快有时慢，用平均速度根本说不清我的速度。」请依据材料三和速度的知识，评价他的说法并说明平均速度的意义。（4 分）","answer":"他的说法不全面。平均速度确实不能反映某一瞬间的快慢（那要用瞬时速度），但它能描述整段路程的整体快慢，而且可以直接由总路程和总时间算出，便于比较不同出行方式的快慢。骑车时快时慢并不影响平均速度的成立，只要说明「这是全程的平均速度」即可。","explain":"","tags":["说理","平均速度"],"rubric":["指出平均速度描述的是整段路程的整体快慢","指出某一时刻的快慢需要用瞬时速度描述","说明平均速度可由总路程与总时间算出（可测量、可比较）","语言完整、结论明确（不否定平均速度的作用）"]}]},{"id":"phy-mech-2","title":"质量与密度","subtitle":"人教版八上 · 第 6 章 质量与密度 · 8a","grade":"8a","tags":["人教版八上 · 第 6 章 质量与密度"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八上 · 第 6 章 质量与密度 · 8a"},{"type":"note","title":"问题切入","text":"体积一样大的铁块、铝块、木块，为什么掂起来轻重差那么多？怎样才能用一个数把它们区分开，又该怎么把它测出来？"},{"type":"note","title":"一句话抓住关键","text":"质量是物体本身的属性，不随位置、形状、状态改变；密度 $\\rho=\\frac{m}{V}$ 是物质的特性，同种物质质量与体积成正比（m-V 图是过原点的直线），比值越大物质越「重」。"},{"type":"h","text":"先看现象：同样大的三块，轻重差很多"},{"type":"p","text":"取体积都是 20 cm³ 的铁块、铝块和木块，掂一掂就知道轻重差别很大：铁块约 158 g，铝块约 54 g，木块只有约 12 g。这说明「同样大小」并不等于「同样轻重」，物质本身还有一种性质在起作用。"},{"type":"figure","figure":{"id":"fig-mech-density-1","title":"体积相同，质量却差很多","caption":"三块体积都是 20 cm³，质量分别为 158 g、54 g、12 g","view":"wide","alt":"三个体积相同的方块并排摆放，从左到右分别是铁块、铝块和木块，标注的质量依次减小","prims":[{"t":"line","x1":8,"y1":44,"x2":92,"y2":44,"width":0.8},{"t":"hatch","x":8,"y":44,"w":84,"h":4.5,"gap":2.2},{"t":"rect","x":12,"y":24,"w":20,"h":20,"fill":true,"tone":"main","label":"铁"},{"t":"rect","x":40,"y":24,"w":20,"h":20,"fill":true,"tone":"accent","label":"铝"},{"t":"rect","x":68,"y":24,"w":20,"h":20,"fill":true,"tone":"muted","label":"木"},{"t":"text","x":50,"y":12,"text":"体积都是 20 cm³","size":3.8,"tone":"muted"},{"t":"text","x":22,"y":52,"text":"158 g","size":3.6},{"t":"text","x":50,"y":52,"text":"54 g","size":3.6,"tone":"accent"},{"t":"text","x":78,"y":52,"text":"12 g","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":59,"text":"体积相同，质量不同 → 物质本身有差别","size":3.6,"tone":"ok"}]}},{"type":"note","title":"","text":"课堂提问要止于「差别来自物质种类」，不要一上来就抛公式。"},{"type":"h","text":"抓住哪个量：质量是物体本身的属性"},{"type":"p","text":"质量表示物体所含物质的多少，单位是千克（kg），常用克（g）。它只由物体本身决定：把铁块压成铁片、宇航员从地球到月球，质量都不变（把物体用去一半则质量减半）。测质量用天平：先放水平台面、游码归零，再调平衡螺母使指针指中央；称量时左盘放物体、右盘放砝码，用镊子夹取砝码。"},{"type":"figure","figure":{"id":"fig-mech-density-2","title":"托盘天平的使用顺序","caption":"先调平再称量：放水平台面、游码归零、调平衡螺母，然后左物右码","view":"wide","alt":"一台托盘天平的示意图，横梁两端挂有托盘，指针指向中央分度盘，标出平衡螺母的位置，下方写出使用步骤","prims":[{"t":"rect","x":30,"y":48,"w":40,"h":4,"fill":true,"tone":"main"},{"t":"line","x1":50,"y1":48,"x2":50,"y2":30,"width":0.8},{"t":"line","x1":24,"y1":30,"x2":76,"y2":30,"width":1.1},{"t":"line","x1":24,"y1":30,"x2":24,"y2":34,"width":0.5},{"t":"line","x1":76,"y1":30,"x2":76,"y2":34,"width":0.5},{"t":"poly","points":[[16,38],[32,38],[30,34],[18,34]],"closed":true,"tone":"main"},{"t":"poly","points":[[68,38],[84,38],[82,34],[70,34]],"closed":true,"tone":"main"},{"t":"line","x1":50,"y1":30,"x2":50,"y2":44,"tone":"accent","width":0.6},{"t":"arc","cx":50,"cy":32,"r":12,"from":245,"to":295,"tone":"muted"},{"t":"text","x":24,"y":26,"text":"左物","size":3.6},{"t":"text","x":76,"y":26,"text":"右码","size":3.6},{"t":"text","x":14,"y":46,"text":"平衡螺母","anchor":"start","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":9,"text":"托盘天平","size":4},{"t":"text","x":50,"y":57,"text":"放水平台面 → 游码归零 → 调平衡螺母 → 左物右码","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":62,"text":"称量过程中不能再动平衡螺母","size":3.4,"tone":"danger"}]}},{"type":"note","title":"","text":"判断题常考「称量时调平衡螺母」与「用手拿砝码」，两处都是操作规范上的错。"},{"type":"h","text":"建立关系：比值 m/V 是物质的特性"},{"type":"p","text":"对同一种物质做实验：体积取 10 cm³、20 cm³、30 cm³，测出的质量分别是 27 g、54 g、81 g。把质量与体积的比值算出来，三次都是 2.7 g/cm³——它不随体积变化。这个比值就是密度 ρ=(m)/(V)：质量与体积成正比，比值反映了物质种类，所以密度是物质的特性。"},{"type":"figure","figure":{"id":"fig-mech-density-3","title":"质量—体积图像","caption":"过原点的直线，斜率就是密度，越陡密度越大","view":"square","alt":"以体积为横轴、质量为纵轴的坐标系中，两条过原点的倾斜直线，铝的直线斜率比木头的大","prims":[{"t":"axis","x":22,"y":84,"w":66,"h":64,"xLabel":"V/cm³","yLabel":"m/g","origin":true,"xTicks":[{"at":0.5,"label":"20"},{"at":1,"label":"40"}],"yTicks":[{"at":0.5,"label":"50"},{"at":1,"label":"100"}]},{"t":"curve","points":[[22,84],[88,20]],"tone":"accent"},{"t":"curve","points":[[22,84],[88,68]],"tone":"muted"},{"t":"text","x":76,"y":30,"text":"铝 2.7 g/cm³","size":3.4,"tone":"accent"},{"t":"text","x":70,"y":76,"text":"木 0.6 g/cm³","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":8,"text":"两条直线都过原点 → 质量与体积成正比","size":3.4,"tone":"ok"}]}},{"type":"h","text":"怎么量：天平配量筒，固体和液体各有先后"},{"type":"p","text":"测固体密度：先用天平测质量 m，再在量筒里装适量水读体积 V₁，把物体用细线系住完全浸没后读 V₂，物体体积 V=V₂−V₁，最后由 ρ=(m)/(V) 算出密度。顺序不能颠倒：先测体积会让物体沾水，质量偏大、密度偏大。测液体密度用「倒出法」：先测烧杯和液体的总质量 m₁，倒一部分进量筒测出体积 V，再测烧杯和剩余液体的质量 m₂，液体密度 ρ=(m₁-m₂)/(V)。"},{"type":"figure","figure":{"id":"fig-mech-density-4","title":"排水法测不规则固体的体积","caption":"水面上升的体积就等于石块的体积","view":"wide","alt":"两个量筒，甲中只有 40 毫升水，乙中放入石块后水面升到 60 毫升，说明石块体积是 20 立方厘米","prims":[{"t":"beaker","x":14,"y":20,"w":24,"h":24,"fill":0.55,"label":"甲"},{"t":"beaker","x":62,"y":20,"w":24,"h":24,"fill":0.78,"label":"乙"},{"t":"circle","cx":74,"cy":38,"r":3.2,"fill":true,"tone":"main"},{"t":"text","x":26,"y":14,"text":"V₁ = 40 mL","size":3.6,"tone":"muted"},{"t":"text","x":74,"y":14,"text":"V₂ = 60 mL","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":54,"text":"石块体积 V = V₂ − V₁ = 20 cm³","size":3.8,"tone":"ok"},{"t":"text","x":50,"y":60,"text":"读数时视线要与液面凹面的最低处相平","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"量筒读数要平视凹液面最低处：仰视读小了、俯视读大了，都会直接算错密度。"},{"type":"h","text":"换个情境：密度与社会生活"},{"type":"p","text":"同种物质在温度变化时质量不变、体积会变，所以密度会变：空气受热体积膨胀、密度变小而上浮，冷水密度大而下沉。于是房间里的空气会形成对流，暖气片要装在窗户下面、空调的冷风出口要装在房间上部。密度还用来鉴别物质（黄金掺假、牛奶掺水）、选材料（飞机用铝合金，因为同样体积更轻）。"},{"type":"figure","figure":{"id":"fig-mech-density-5","title":"暖气片为什么装在下面","caption":"热空气密度小上升，冷空气密度大下沉，房间里的空气形成对流","view":"wide","alt":"房间剖面图，暖气片靠近地面，热空气向上流动的箭头和冷空气向下流动的箭头构成对流回路","prims":[{"t":"rect","x":16,"y":14,"w":68,"h":34,"tone":"muted"},{"t":"rect","x":20,"y":40,"w":10,"h":4,"fill":true,"tone":"danger"},{"t":"arrow","x1":33,"y1":42,"x2":33,"y2":18,"tone":"danger"},{"t":"arrow","x1":45,"y1":42,"x2":45,"y2":18,"tone":"danger"},{"t":"arrow","x1":66,"y1":18,"x2":66,"y2":42,"tone":"accent"},{"t":"arrow","x1":76,"y1":18,"x2":76,"y2":42,"tone":"accent"},{"t":"text","x":39,"y":22,"text":"热空气上升","size":3.4,"tone":"danger"},{"t":"text","x":68,"y":34,"text":"冷空气下沉","size":3.4,"tone":"accent"},{"t":"text","x":26,"y":50,"text":"暖气片","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":57,"text":"温度变化 → 体积变化 → 密度变化 → 形成对流","size":3.6,"tone":"ok"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["密度","ρ = (m)/(V)","ρ：千克每立方米（kg/m³）或克每立方厘米（g/cm³）；m：kg 或 g；V：m³ 或 cm³ · 密度是物质的特性，同种物质（状态、温度一定时）ρ 是定值，与 m、V 的大小无关。计算时 m 与 V 必须取自同一物体、同一状态，单位要配套：kg 配 m³、g 配 cm³。"],["密度的变形公式","m = ρ V V = (m)/(ρ)","与密度公式一致，单位必须配套 · 已知密度求质量（如算一车沙石、一桶油的质量）用 m=ρ V；已知质量和密度求体积（如判断是否空心、算瓶子能装多少液体）用 V=(m)/(ρ)。"],["密度单位换算","1\\ g/cm³ = 1.0× 10³\\ kg/m³","1 g/cm³ = 10³ kg/m³；1 kg/m³ = 10⁻³ g/cm³ · 水的密度 1.0× 10³\\ kg/m³ 也就是 1.0 g/cm³。换算方向别搞反：g/cm³ 的数比 kg/m³ 的数小 1000 倍，2.7 g/cm³ = 2.7×10³ kg/m³。"]]},{"type":"h","text":"应用 · 应用一：判断铁球是不是空心的"},{"type":"note","title":"情境","text":"一个铁球的质量是 790 g，体积是 150 cm³。已知铁的密度是 7.9 g/cm³，判断这个铁球是实心还是空心，若是空心，空心部分的体积是多少。"},{"type":"note","title":"模型与思路","text":"三种判断思路等价：比较密度、比较体积、比较质量。这里用「比较体积」最直接：假设球是实心的，用 V=(m)/(ρ) 算出应有的体积，再与实测体积比较。"},{"type":"list","title":"解答步骤","items":["若铁球实心，其体积应为 V_(实)=(m)/(ρ)=790\\ g7.9\\ g/cm³=100\\ cm³","实测体积 V=150\\ cm³>100\\ cm³，说明球内有一部分是空的","空心部分体积 V_(空)=V-V_(实)=150\\ cm³-100\\ cm³=50\\ cm³","检验：若按密度判断，ρ=790\\ g150\\ cm³≈ 5.3\\ g/cm³<7.9\\ g/cm³，同样说明是空心的"]},{"type":"figure","figure":{"id":"fig-mech-density-6","title":"空心铁球的剖面","caption":"外形体积 150 cm³，其中铁只占 100 cm³","view":"wide","alt":"一个铁球的剖面示意图，外面一圈是铁，中间虚线圆表示空心的部分","prims":[{"t":"circle","cx":50,"cy":30,"r":18,"fill":true,"tone":"main"},{"t":"circle","cx":50,"cy":30,"r":9,"dashed":true,"tone":"danger","fill":true,"label":"空心"},{"t":"text","x":50,"y":55,"text":"外形 150 cm³，铁只有 100 cm³","size":3.6,"tone":"muted"}]}},{"type":"note","title":"结论","text":"铁球是空心的，空心部分的体积是 50 cm³。"},{"type":"h","text":"应用 · 应用二：5 L 的油为什么比 5 L 的水轻"},{"type":"note","title":"情境","text":"超市里 5 L 装的食用油，包装上标着净含量约 4.6 kg，而 5 L 的矿泉水是 5 kg。为什么同样 5 L，质量却不一样？"},{"type":"note","title":"模型与思路","text":"体积相同而质量不同，说明两种物质的密度不同。把体积化成 m³ 或 cm³，用 m=ρ V 分别计算即可。"},{"type":"list","title":"解答步骤","items":["水的密度 ρ_(水)=1.0× 10³\\ kg/m³，5 L =5× 10^(-3)\\ m³","m_(水)=ρ_(水)V=1.0× 10³\\ kg/m³× 5× 10^(-3)\\ m³=5\\ kg","食用油的密度约 ρ_(油)=0.92× 10³\\ kg/m³","m_(油)=ρ_(油)V=0.92× 10³\\ kg/m³× 5× 10^(-3)\\ m³=4.6\\ kg"]},{"type":"figure","figure":{"id":"fig-mech-density-7","title":"同体积的水和油","caption":"液面一样高，质量却不同","view":"wide","alt":"两个相同体积的容器，分别装着 5 升水和 5 升食用油，水的质量是 5 千克、油的质量约 4.6 千克","prims":[{"t":"beaker","x":18,"y":16,"w":22,"h":28,"fill":0.85,"label":"5 L 水"},{"t":"beaker","x":60,"y":16,"w":22,"h":28,"fill":0.85,"label":"5 L 油"},{"t":"text","x":29,"y":52,"text":"5 kg","size":3.8,"tone":"accent"},{"t":"text","x":71,"y":52,"text":"4.6 kg","size":3.8,"tone":"main"},{"t":"text","x":50,"y":10,"text":"ρ水 = 1.0×10³ kg/m³，ρ油 = 0.92×10³ kg/m³","size":3.4,"tone":"muted"}]}},{"type":"note","title":"结论","text":"同样 5 L，油的质量约 4.6 kg，比水轻 0.4 kg；因为油的密度比水小，这也是油会浮在水面上的原因。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为「体积越大密度越小、质量越大密度越大」，把密度当成可以由物体随意决定的值。","密度由物质种类（以及状态、温度）决定。同一块铁切成两半，质量和体积都减半，密度仍是 7.9 g/cm³。","ρ=(m)/(V) 是定义式而不是决定式：m 与 V 成正比变化，比值不变。这句话搞混，后面算压强、浮力时会一路错下去。"],["测固体密度时，先把石块放进量筒测体积，再拿出来测质量。","必须先用天平测质量，再用排水法测体积。","石块从水里拿出来会沾水，质量测出来偏大，由 ρ=(m)/(V) 算得的密度偏大。同理，测液体密度用「倒出法」，不能把量筒直接放在天平上称。"],["认为把物体从地球带到月球、或把它压扁，质量会改变。","质量不随位置、形状、状态改变；会变的是重力（月球上 g 小，重力变小）和体积（压扁、受热膨胀）。","质量与重力是两个不同的物理量，单位也不同（kg 与 N）。质量不变而体积变化时，密度会随之变化。"]]},{"type":"table","title":"质量与密度（一个是物体的属性，一个是物质的特性）","head":["比较项","质量 m","密度 ρ"],"rows":[["含义","物体所含物质的多少","单位体积某种物质的质量"],["单位","千克（kg）、克（g）","千克每立方米（kg/m³）、克每立方厘米（g/cm³）"],["由什么决定","物体本身（含物质的多少）","物质种类，以及状态与温度"],["是否随位置改变","不变（带到月球也不变）","不变（物质种类没变）"],["测量方式","用天平测","用天平和量筒测出 m、V 后计算"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["天平与量筒的读数与操作","以「测小石块（或盐水）的密度」为情境，考查实验步骤排序、天平调平、量筒读数（视线与凹液面最低处相平）、先测质量还是先测体积，以及沾水带来的误差方向。"],["密度公式的计算与鉴别物质","给质量与体积求密度并对照密度表判断物质种类，或反过来判断物体是否空心、求空心部分体积；关键是先统一单位。"],["图像法求密度","给 m-V 图像（或表格数据），要求判断哪条线对应哪种物质、比较密度大小，或从图线上取点算密度——过原点的直线说明质量与体积成正比。"],["密度与社会生活","以暖气片位置、风的形成、鉴定牛奶是否掺水、选择航空材料等情境命题，落脚点是「温度或种类变化 → 密度变化 → 现象」。"]]},{"type":"quote","text":"【材料一】某同学测量小石块的密度：用调节好的天平测出石块的质量为 54 g；量筒中原来装有 40 mL 水，把石块用细线系住完全浸没后，水面升高到 60 mL 刻度处。\n【材料二】冬天的暖气片安装在窗户下面，夏天的空调冷风出口安装在房间上部；用过的食用油倒进水里会浮在水面上。\n【材料三】同种物质在温度升高时质量不变、体积会变大。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）依据材料一，求小石块的密度，写成 g/cm³ 和 kg/m³ 两种单位。（6 分）","【设问】（2）依据材料二、三，说明暖气片为什么装在窗户下面，而空调冷风出口为什么装在房间上部。（4 分）","【设问】（3）如果这位同学先把石块放入量筒测体积，再拿出来用天平测质量，测得的密度会偏大还是偏小？说明理由。（4 分）"]}],"questions":[{"id":"phy-mech-2-q1","type":"choice","stem":"下列情况中，物体的质量发生变化的是","answer":"D","explain":"质量是物体所含物质的多少，只由物体本身决定。A 只改变形状，物质多少没变；B 只改变位置，物质的多少没变；C 中水变成水蒸气是状态变化，且容器密闭、水没有跑掉，质量不变。只有 D 中物质被用掉一半，所含物质减少，质量减半。注意 C 里密度会变（水蒸气的密度远小于水），但质量不变。","options":["把一块铁压成薄铁片","把一块铁从广州带到北京","把一杯水加热成水蒸气（装在密闭容器中）","把一根铁棒用去一半"],"difficulty":1,"tags":["质量","属性"]},{"id":"phy-mech-2-q2","type":"choice","stem":"关于托盘天平的使用，下列操作正确的是","answer":"A","explain":"正确顺序是：放水平台面 → 游码归零 → 调平衡螺母使指针指中央 → 左物右码称量，A 正确。B 错：手上的汗渍会腐蚀砝码、改变其质量，必须用镊子夹取。C 错：平衡螺母只能在称量前调节，称量过程中只能加减砝码或移动游码。D 错：天平规定左盘放物体、右盘放砝码。","options":["把天平放在水平台面上，游码移到标尺左端零刻度线后，再调节平衡螺母使指针指在分度盘中央","为了方便，可以直接用手拿取砝码","称量过程中发现指针偏左，立即调节平衡螺母使横梁平衡","称量时把被测物体放在右盘，砝码放在左盘"],"difficulty":1,"tags":["天平使用","实验操作"]},{"id":"phy-mech-2-q3","type":"choice","stem":"下图是甲、乙两种物质的质量与体积关系的图像，由图可知","answer":"C","explain":"m-V 图像上过原点的直线表示质量与体积成正比，直线的斜率就是密度：斜率越大密度越大。取同一个体积（比如 20 cm³），甲对应的质量更大，说明甲的密度大于乙，C 正确。A、B 都把斜率关系看反了。D 错：两条线都过原点，斜率可以直接比较，不缺少条件。","options":["甲的密度小于乙的密度","甲、乙的密度相同","甲的密度大于乙的密度","条件不足，无法比较"],"difficulty":2,"tags":["m-V 图像","密度比较"],"figure":{"id":"fig-mech-density-q3","title":"甲、乙两种物质的 m-V 图像","caption":"两条直线都过原点，甲的直线更陡","view":"square","alt":"以体积为横轴、质量为纵轴的图像上有两条过原点的直线，甲的直线比乙的更陡","prims":[{"t":"axis","x":22,"y":84,"w":66,"h":64,"xLabel":"V/cm³","yLabel":"m/g","origin":true,"xTicks":[{"at":1,"label":"20"}],"yTicks":[{"at":1,"label":"54"}]},{"t":"curve","points":[[22,84],[88,20]],"tone":"accent"},{"t":"curve","points":[[22,84],[88,52]],"tone":"main"},{"t":"text","x":76,"y":32,"text":"甲","size":4,"tone":"accent"},{"t":"text","x":78,"y":66,"text":"乙","size":4},{"t":"text","x":50,"y":92,"text":"取相同体积，甲的质量更大","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-2-q4","type":"choice","stem":"一瓶 500 mL 的矿泉水，瓶中水的质量最接近","answer":"B","explain":"水的密度是 1.0×10³ kg/m³，也就是 1 g/cm³；500 mL = 500 cm³，所以质量 m=ρ V=1\\ g/cm³× 500\\ cm³=500\\ g，B 正确。A 差了一个数量级；C 相当于 5 L 水的质量，是这瓶水的 10 倍；D 是 50 L 水的质量，更不符合。","options":["50 g","500 g","5 kg","50 kg"],"difficulty":1,"tags":["密度估测","单位换算"]},{"id":"phy-mech-2-q5","type":"fill","stem":"一块体积为 20 cm³ 的金属块，质量是 54 g，这块金属的密度是＿＿g/cm³。","answer":"2.7|2.70","explain":"由 ρ=(m)/(V)=54\\ g20\\ cm³=2.7\\ g/cm³（即 2.7×10³ kg/m³，与铝的密度相符）。若把 54 除以 20 算成 27，多半是把 0.1 位的小数点丢了；若答 1080，则是把除法做成了乘法。","difficulty":1,"tags":["密度计算"]},{"id":"phy-mech-2-q6","type":"fill","stem":"一个空瓶子最多能装 500 g 的水，这个瓶子的容积是＿＿cm³。（ρ水 = 1.0 g/cm³）","answer":"500|500.0","explain":"瓶子能装的水的体积就是瓶子的容积，由 V=(m)/(ρ)=500\\ g1.0\\ g/cm³=500\\ cm³，也就是 500 mL。常见错误是答 500 mL 以外的数值，或忘了水的密度取 1.0 g/cm³，把水的密度当成 1.0 kg/m³（数值差了 1000 倍）。","difficulty":1,"tags":["密度变形公式"]},{"id":"phy-mech-2-q7","type":"short","stem":"一个铁球的质量是 790 g，体积是 150 cm³，铁的密度是 7.9 g/cm³。请判断这个铁球是实心还是空心的，并求出空心部分的体积。","answer":"假设铁球是实心的，它应有的体积 $V_{实}=\\frac{m}{\\rho}=\\frac{790\\ \\mathrm{g}}{7.9\\ \\mathrm{g/cm^3}}=100\\ \\mathrm{cm^3}$。实际体积 150 cm³ 大于 100 cm³，所以铁球是空心的。空心部分的体积 $V_{空}=150\\ \\mathrm{cm^3}-100\\ \\mathrm{cm^3}=50\\ \\mathrm{cm^3}$。","explain":"判断空心有三种等价做法：算实心体积比体积、算平均密度比密度、算实心质量比质量。它们的共同依据都是「同种物质密度不变」。本题若先算平均密度 ρ=(790)/(150)≈ 5.3\\ g/cm³，与铁的 7.9 g/cm³ 相比更小，也能判断是空心的，但还要多一步才能算出空心体积；所以「比较体积」更省事。","difficulty":2,"tags":["密度计算","空心判断"],"rubric":["选择一种判断方法并说明依据（比较体积或比较密度）","正确算出实心时的体积 100 cm³","由比较结果明确判断「空心」","正确算出空心体积 50 cm³ 并有结论性作答"],"steps":["写出判断依据：同种物质实心时 m 与 V 成正比，可用「比较体积」的方法判断。","求出若为实心时的体积：V_(实)=(m)/(ρ)=790\\ g7.9\\ g/cm³=100\\ cm³。","比较：V_(实)<V_(实际)，所以铁球是空心的。","求空心部分体积：V_(空)=V_(实际)-V_(实)=150\\ cm³-100\\ cm³=50\\ cm³。","作答：铁球是空心的，空心部分体积为 50 cm³。"]},{"id":"phy-mech-2-q8","type":"short","stem":"某小组要测量小石块的密度，实验室提供了天平（含砝码）、量筒、水、细线、烧杯。请写出实验步骤，并说明为什么必须先测质量再测体积。","answer":"步骤：① 把天平放在水平台面上，游码移到标尺左端零刻度线处，调节平衡螺母使指针指在分度盘中央；② 把小石块放在左盘，用镊子在右盘加减砝码并移动游码，测出石块质量 m；③ 在量筒中倒入适量的水，读出水的体积 V₁（视线与凹液面最低处相平，水量要能浸没石块且放入后水面不超过量程）；④ 用细线系住石块，缓慢放入量筒使其完全浸没，读出水面到达的刻度 V₂；⑤ 计算石块体积 V=V₂−V₁，密度 $\\rho=\\frac{m}{V}$。必须先测质量：若先测体积，石块表面沾水会使天平测得的质量偏大，算出的密度偏大。","explain":"这道实验题的踩分点都在「顺序」和「细节」上：水量要「适量」（能浸没石块、放入后不超量程）；石块要「完全浸没」但体积读数不能包括细线的体积；读两个体积时视线都要与凹液面最低处相平。误差分析题的答法固定：先看哪个量测偏了，再代入 ρ=(m)/(V) 判断结果偏大还是偏小。","difficulty":2,"tags":["实验探究","密度测量","误差分析"],"rubric":["器材齐全并说明天平调平的规范操作（游码归零、调平衡螺母）","正确测质量：左物右码、用镊子夹取砝码","正确测体积：先读 V₁ 再读 V₂，石块完全浸没（细线系住、缓慢放入）","说明先测质量的理由：避免沾水导致质量偏大、密度偏大"]},{"id":"phy-mech-2-q9","type":"short","stem":"某小组测得铝块的质量与体积如下表：体积 0、10、20、30 cm³ 时质量分别为 0、27、54、81 g。请在下面的坐标系中画出铝块的 m-V 图像。","answer":"把（10，27）、（20，54）、（30，81）三个点描在坐标系中，它们与原点在同一条直线上，用直线把这些点连起来，就得到一条过原点的倾斜直线。","explain":"图像题的关键是「描点—连线—看形状」：三个点刚好落在过原点的同一条直线上，说明质量与体积成正比，比值 2.7 g/cm³ 就是铝的密度。常见的错误是把点连成折线（应该用一条直线拟合），或忘了标坐标轴的单位。若某次实验的点明显偏离直线，那多半是测量或单位换算出了问题。","difficulty":2,"tags":["作图题","m-V 图像"],"rubric":["按表格数据正确描出三个点（含原点）","用一条直线把各点连接，图线过原点且不画成折线","坐标轴标注完整（横轴 V、纵轴 m，标出单位）","由图像得出「质量与体积成正比、斜率为密度」的结论"],"figure":{"id":"fig-mech-density-q9-blank","title":"待画的 m-V 坐标系","caption":"纵轴为质量，横轴为体积，把表格数据描点后连线","view":"square","alt":"一个空白的质量体积坐标系，纵轴标出 27 克、54 克和 81 克，横轴标出 10、20 和 30 立方厘米","prims":[{"t":"axis","x":22,"y":82,"w":66,"h":62,"xLabel":"V/cm³","yLabel":"m/g","origin":true,"grid":true,"xTicks":[{"at":0.33,"label":"10"},{"at":0.67,"label":"20"},{"at":1,"label":"30"}],"yTicks":[{"at":0.33,"label":"27"},{"at":0.67,"label":"54"},{"at":1,"label":"81"}]}]},"answerFigure":{"id":"fig-mech-density-q9-ans","title":"m-V 图像的标准画法","caption":"数据点与原点共线，说明质量与体积成正比","view":"square","alt":"质量体积图像上，横轴 10、20、30 立方厘米对应的 27、54、81 克的三个数据点与原点连成一条过原点的倾斜直线","prims":[{"t":"axis","x":22,"y":82,"w":66,"h":62,"xLabel":"V/cm³","yLabel":"m/g","origin":true,"xTicks":[{"at":0.33,"label":"10"},{"at":0.67,"label":"20"},{"at":1,"label":"30"}],"yTicks":[{"at":0.33,"label":"27"},{"at":0.67,"label":"54"},{"at":1,"label":"81"}]},{"t":"curve","points":[[22,82],[88,20]],"tone":"accent","width":0.9},{"t":"circle","cx":44,"cy":61.3,"r":1.4,"fill":true,"tone":"accent"},{"t":"circle","cx":66,"cy":40.7,"r":1.4,"fill":true,"tone":"accent"},{"t":"circle","cx":88,"cy":20,"r":1.4,"fill":true,"tone":"accent"},{"t":"text","x":62,"y":74,"text":"斜率 = 2.7 g/cm³","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-2-m1-q1","type":"short","stem":"（1）依据材料一，求小石块的密度，写成 g/cm³ 和 kg/m³ 两种单位。（6 分）","answer":"石块的体积等于水面上升的体积：$V=60\\ \\mathrm{mL}-40\\ \\mathrm{mL}=20\\ \\mathrm{mL}=20\\ \\mathrm{cm^3}$。密度 $\\rho=\\frac{m}{V}=\\frac{54\\ \\mathrm{g}}{20\\ \\mathrm{cm^3}}=2.7\\ \\mathrm{g/cm^3}=2.7\\times 10^3\\ \\mathrm{kg/m^3}$。","explain":"","tags":["密度计算","排水法"],"rubric":["用 V₂ − V₁ 求出石块体积 20 mL（说明 1 mL = 1 cm³）","写出密度公式 ρ = m / V","代入数据并算得 2.7 g/cm³","正确换算成 2.7×10³ kg/m³ 并带单位"]},{"id":"phy-mech-2-m1-q2","type":"short","stem":"（2）依据材料二、三，说明暖气片为什么装在窗户下面，而空调冷风出口为什么装在房间上部。（4 分）","answer":"空气受热时体积膨胀、密度变小，会向上流动；冷空气密度较大，会向下沉。暖气片装在窗户下面，它周围的空气受热后上升，上方的冷空气下沉补充，房间里形成对流，整间屋子都能暖起来；空调吹出的冷空气密度较大、容易下沉，出口装在房间上部可以让冷空气自然向下沉降，降温更快也更均匀。","explain":"","tags":["说理","密度与社会生活"],"rubric":["答出空气受热体积变大、密度变小","答出热空气上升、冷空气下沉形成对流","说明暖气片装低处的作用（使全屋空气循环）","说明冷风出口装高处的作用（冷空气下沉、降温均匀）"]},{"id":"phy-mech-2-m1-q3","type":"short","stem":"（3）如果这位同学先把石块放入量筒测体积，再拿出来用天平测质量，测得的密度会偏大还是偏小？说明理由。（4 分）","answer":"会偏大。石块从水中取出时表面沾有水，用天平测出的质量比石块的真实质量大，而量筒测出的体积是准确的；由 $\\rho=\\frac{m}{V}$ 可知，体积一定时质量偏大，算出的密度就偏大。","explain":"","tags":["实验评估","误差分析"],"rubric":["判断出「偏大」","指出石块沾水使测得的质量偏大","指出体积测量不受影响（是准确的）","用 ρ = m / V 说明分子偏大导致结果偏大"]}]},{"id":"phy-mech-3","title":"力·弹力·重力","subtitle":"人教版八下 · 第 7 章 力 · 8b","grade":"8b","tags":["人教版八下 · 第 7 章 力"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八下 · 第 7 章 力 · 8b"},{"type":"note","title":"问题切入","text":"为什么画一个力必须同时说清「多大、朝哪个方向、作用在哪一点」？为什么弹簧秤能测力，用它可以算出质量吗？"},{"type":"note","title":"一句话抓住关键","text":"力是物体对物体的作用，作用效果由大小、方向、作用点共同决定，画图时用一条带箭头的线段表示，这三条信息缺一不可。弹力由形变产生，在弹性限度内弹簧的伸长量与拉力成正比（弹簧测力计的原理）；重力 $G=mg$，方向竖直向下，作用点在重心。"},{"type":"h","text":"先看现象：力能做哪两件事"},{"type":"p","text":"拉长弹簧、捏扁橡皮泥，物体的形状变了；踢出去的足球拐了个弯、静止的球被踢动，物体的运动状态变了。所以力的作用效果归结为两条：使物体发生形变，或改变物体的运动状态。只要这两件事之一发生了，就一定有力的作用。"},{"type":"figure","figure":{"id":"fig-mech-force-1","title":"力的两种作用效果","caption":"左边把弹簧拉长，右边让球的运动方向改变","view":"wide","alt":"左边一段弹簧被向两侧拉长，右边一只足球沿一条弯曲的轨迹飞出，说明力可以改变物体的形状和运动状态","prims":[{"t":"text","x":26,"y":10,"text":"拉弹簧：形状改变","size":3.5,"tone":"muted"},{"t":"spring","x1":16,"y1":26,"x2":38,"y2":26,"coils":6},{"t":"arrow","x1":16,"y1":26,"x2":8,"y2":26,"tone":"accent","label":"F","labelDy":-3},{"t":"arrow","x1":38,"y1":26,"x2":46,"y2":26,"tone":"accent","label":"F","labelDy":-3},{"t":"text","x":74,"y":10,"text":"踢球：运动状态改变","size":3.5,"tone":"muted"},{"t":"circle","cx":62,"cy":36,"r":3.4,"fill":true,"tone":"main"},{"t":"curve","points":[[62,36],[70,30],[80,25],[90,22]],"tone":"accent","dashed":true,"arrow":true},{"t":"text","x":50,"y":52,"text":"力的作用效果：使物体形变，或改变物体的运动状态","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":58,"text":"有作用效果 → 一定有力的作用","size":3.4,"tone":"muted"}]}},{"type":"h","text":"抓住哪个量：力的三要素与示意图"},{"type":"p","text":"力不能说清「有多大」，还得说清方向和作用点。用手推门：同样大小的力作用在门把手附近很容易推开，作用在靠近门轴的地方就很难推开，这就是作用点的影响。所以画力的示意图必须画出三件事：线段的长度表示大小、箭头表示方向、线段的起点（或终点）落在作用点上；重力、压力这些力还要标出作用点的位置。"},{"type":"figure","figure":{"id":"fig-mech-force-2","title":"同一个力，作用点不同效果不同","caption":"离门轴越远越省力，说明作用点影响力的作用效果","view":"wide","alt":"一扇门从左边门轴处打开，靠近门轴的力 F 拉不动门，作用在右边门把手上的力 F 容易把门推开","prims":[{"t":"rect","x":18,"y":12,"w":62,"h":32,"tone":"main"},{"t":"line","x1":18,"y1":12,"x2":18,"y2":44,"width":1.4},{"t":"circle","cx":74,"cy":28,"r":2,"tone":"accent","fill":true},{"t":"arrow","x1":26,"y1":28,"x2":40,"y2":28,"tone":"muted","label":"F₁"},{"t":"arrow","x1":70,"y1":28,"x2":86,"y2":28,"tone":"accent","label":"F₂","labelDy":-4},{"t":"text","x":18,"y":50,"text":"门轴","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":20,"text":"门把手","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":57,"text":"大小、方向、作用点，都会影响力的作用效果","size":3.6,"tone":"ok"}]}},{"type":"note","title":"","text":"力的示意图只画一条带箭头的线段，不必按比例画长度，但方向与作用点必须画对。"},{"type":"h","text":"建立关系：弹力由形变产生，弹簧测力计据此读数"},{"type":"p","text":"物体发生弹性形变时，要恢复原状就会对使它形变的物体产生力的作用，这个力叫弹力：压弹簧时弹簧对手有弹力，桌子支持书也是弹力。在弹性限度内，弹簧的伸长量 Δ L 与受到的拉力 F 成正比，所以弹簧测力计的分度值是均匀的。使用前要检查指针是否指零、所测的力不能超过量程，拉力的方向要沿弹簧的轴线方向。"},{"type":"figure","figure":{"id":"fig-mech-force-3","title":"弹簧的伸长量与拉力成正比","caption":"弹性限度内图线是过原点的直线，超过限度后弯曲","view":"square","alt":"以伸长量为横轴、拉力为纵轴的图像上，弹性限度内是一条过原点的直线，超过弹性限度后图线向右下弯曲","prims":[{"t":"axis","x":22,"y":84,"w":66,"h":64,"xLabel":"ΔL/cm","yLabel":"F/N","origin":true,"xTicks":[{"at":0.5,"label":"2"},{"at":1,"label":"4"}],"yTicks":[{"at":0.5,"label":"1"},{"at":1,"label":"2"}]},{"t":"curve","points":[[22,84],[66,52]],"tone":"accent"},{"t":"curve","points":[[66,52],[88,44]],"tone":"danger","dashed":true},{"t":"line","x1":66,"y1":84,"x2":66,"y2":52,"dashed":true,"tone":"muted"},{"t":"text","x":46,"y":18,"text":"弹性限度内：过原点的直线","size":3.4,"tone":"accent"},{"t":"text","x":72,"y":34,"text":"超过限度后不再成正比","size":3.2,"tone":"danger"}]}},{"type":"note","title":"","text":"「伸长量」是弹簧长度减去原长，不是弹簧的总长度——读图与计算时最容易混淆。"},{"type":"h","text":"建立关系：重力与质量成正比，方向总是竖直向下"},{"type":"p","text":"由于地球吸引而使物体受到的力叫重力，用弹簧测力计测出不同质量物体受到的重力，会发现重力与质量成正比，比值 g 约为 9.8 N/kg（计算时常取 10 N/kg），所以 G=mg。重力的方向总是竖直向下（不是「垂直向下」，垂直向下是垂直于接触面），重力的作用点叫重心，形状规则、质量分布均匀的物体重心在它的几何中心。"},{"type":"figure","figure":{"id":"fig-mech-force-4","title":"重力的方向与重心","caption":"无论物体形状如何，重力方向总是竖直向下","view":"wide","alt":"左边一个不规则形状的物体，重力从重心竖直向下；右边一个圆环的重心标在圆心的位置，说明重心可以不在物体上","prims":[{"t":"line","x1":6,"y1":46,"x2":94,"y2":46,"width":0.8},{"t":"hatch","x":6,"y":46,"w":88,"h":4.5,"gap":2.2},{"t":"poly","points":[[10,26],[30,20],[42,34],[42,46],[10,46]],"closed":true,"fill":true,"tone":"main"},{"t":"circle","cx":26,"cy":36,"r":1.8,"fill":true,"tone":"danger","label":"重心","labelDy":8},{"t":"arrow","x1":26,"y1":36,"x2":26,"y2":56,"tone":"accent","label":"G","labelDx":5},{"t":"circle","cx":72,"cy":28,"r":13,"tone":"main"},{"t":"circle","cx":72,"cy":28,"r":1.8,"fill":true,"tone":"danger"},{"t":"text","x":72,"y":10,"text":"圆环的重心在圆心","size":3.5,"tone":"muted"},{"t":"text","x":72,"y":52,"text":"重心可以不在物体上","size":3.5,"tone":"muted"}]}},{"type":"h","text":"换个情境：换到月球上，质量和重力各怎么变"},{"type":"p","text":"把同一个物体从地球带到月球，它含有的物质没变，所以质量不变；但月球对物体的吸引比地球小得多，g 只有约 1.6 N/kg，用 G=mg 算出的重力就变小了。所以「质量 50 kg、重力 500 N」这两句话在地球上同时成立，到了月球上要改成「质量仍是 50 kg，重力约 80 N」。"},{"type":"figure","figure":{"id":"fig-mech-force-5","title":"同一个物体，两种重力","caption":"质量都是 50 kg，地球上重力 500 N，月球上只有约 80 N","view":"wide","alt":"左边地球表面的物体受到 500 牛的重力，右边月球表面的同一物体受到约 80 牛的重力，两者质量都是 50 千克","prims":[{"t":"text","x":50,"y":8,"text":"质量都是 50 kg，位置不同，重力不同","size":3.6,"tone":"muted"},{"t":"line","x1":6,"y1":50,"x2":46,"y2":50,"width":0.8,"tone":"accent"},{"t":"hatch","x":6,"y":50,"w":40,"h":4,"gap":2.2},{"t":"circle","cx":26,"cy":32,"r":5,"fill":true,"tone":"main"},{"t":"arrow","x1":26,"y1":37,"x2":26,"y2":49,"tone":"accent","label":"G=500 N","labelDx":17},{"t":"text","x":26,"y":59,"text":"地球 g 取 10 N/kg","size":3.4,"tone":"accent"},{"t":"line","x1":54,"y1":50,"x2":94,"y2":50,"width":0.8,"tone":"muted"},{"t":"hatch","x":54,"y":50,"w":40,"h":4,"gap":2.2},{"t":"circle","cx":74,"cy":36,"r":5,"fill":true,"tone":"main"},{"t":"arrow","x1":74,"y1":41,"x2":74,"y2":49,"tone":"muted","label":"G≈80 N","labelDx":16},{"t":"text","x":74,"y":59,"text":"月球 g≈1.6 N/kg","size":3.4,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["重力与质量的关系","G = mg","G：牛顿（N）；m：千克（kg）；g：牛顿每千克（N/kg） · 适用于地面附近的物体。g 约为 9.8 N/kg，题目一般说明取 10 N/kg，就必须按 10 算。变形用法：m=(G)/(g)（由重力求质量）、g=(G)/(m)（求某星球表面的 g）。"],["g 的物理意义","g = (G)/(m) = 9.8\\ N/kg","g：牛顿每千克（N/kg） · 表示质量为 1 kg 的物体受到的重力是 9.8 N。g 随位置变化：月球约 1.6 N/kg，所以同一物体在不同星球上重力不同，但质量不变。"],["弹簧测力计的原理","F ∝ Δ L","F：牛顿（N）；ΔL：弹簧的伸长量，米（m）或厘米（cm） · 只在弹性限度内成立：伸长量与拉力成正比，所以刻度均匀。ΔL 是弹簧长度减去原长；超过弹性限度后弹簧不能完全恢复，读数不再可靠。"]]},{"type":"h","text":"应用 · 应用一：用弹簧测力计测重力，再算质量"},{"type":"note","title":"情境","text":"把一袋水果挂在弹簧测力计下，指针指在 3.6 N 处。求这袋水果受到的重力和它的质量（g 取 10 N/kg）。"},{"type":"note","title":"模型与思路","text":"弹簧测力计竖直悬挂时示数等于物体重力，所以可直接读出 G；再由 G=mg 变形得 m=(G)/(g) 求质量。注意弹簧测力计测的是力，单位是 N，不能直接读质量。"},{"type":"list","title":"解答步骤","items":["读数：弹簧测力计的示数就是水果的重力，G=3.6\\ N","由 G=mg 变形得 m=(G)/(g)","代入数据：m=3.6\\ N10\\ N/kg=0.36\\ kg","检验量级：0.36 kg 即 360 g，与一袋水果的实际质量相符"]},{"type":"note","title":"结论","text":"这袋水果重力为 3.6 N，质量为 0.36 kg。"},{"type":"h","text":"应用 · 应用二：重垂线为什么能检查墙砌得直不直"},{"type":"note","title":"情境","text":"建筑工人用一根细线系住一个铅锤，让铅锤自由下垂形成重垂线，把线贴在刚砌好的墙面上，用来检查墙是否竖直。这个办法的原理是什么？"},{"type":"note","title":"模型与思路","text":"重垂线静止时受重力和线的拉力而平衡，重力的方向总是竖直向下，所以线被拉成竖直方向。把竖直的线与墙面比较，就能判断墙是否竖直。"},{"type":"list","title":"解答步骤","items":["铅锤静止时受两个力：竖直向下的重力、沿线的拉力，二者平衡","平衡时拉力方向与重力方向相反、在同一直线上，所以线一定是竖直的","把线与墙面比较：线贴着墙面且与墙面平行，说明墙是竖直的","若线与墙之间有夹角，说明墙倾斜了，夹角的大小就是墙偏离竖直方向的角度"]},{"type":"figure","figure":{"id":"fig-mech-force-6","title":"重垂线检查墙面是否竖直","caption":"线与墙面平行，说明墙砌得竖直","view":"wide","alt":"一面墙的截面旁边挂着一条重垂线，细线竖直下垂，下端系着铅锤，线与墙面平行","prims":[{"t":"line","x1":6,"y1":46,"x2":94,"y2":46,"width":0.8},{"t":"hatch","x":6,"y":46,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":18,"y":10,"w":10,"h":36,"fill":true,"tone":"main","label":"墙"},{"t":"line","x1":36,"y1":10,"x2":36,"y2":40,"width":0.5,"tone":"accent"},{"t":"poly","points":[[33,40],[39,40],[36,46]],"closed":true,"fill":true,"tone":"accent"},{"t":"text","x":44,"y":24,"text":"重垂线","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"线竖直下垂，与墙面平行 → 墙是竖直的","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"重垂线利用「重力方向竖直向下」，把看不见的竖直方向变成了看得见的一条线。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["把「竖直向下」写成「垂直向下」，或在斜面上把重力画成垂直于斜面。","重力的方向总是竖直向下（指向地心附近的方向），与物体放在水平面还是斜面上无关。","「垂直向下」是指垂直于接触面，只在水平面这一种情况下才恰好与竖直方向重合。斜面上的物体，重力仍然竖直向下，垂直于斜面的那个是支持力。"],["认为「重心一定在物体上」，或认为「1 kg = 9.8 N」。","重心是重力的等效作用点，可以在物体之外（如圆环重心在圆心）；千克是质量单位，牛顿是力的单位，两者不能画等号，只能说质量 1 kg 的物体在地面附近重约 9.8 N。","质量与重力是两个不同的物理量，用 g 联系。把单位和物理量混为一谈，后面学密度、压强时会连续出错。"],["用弹簧测力计测重力时，把物体挂在挂钩上斜着拉，或超过量程使用。","测量时拉力方向要沿弹簧的轴线方向，所测力不能超过量程，使用前还要检查指针是否指在零刻度线。","斜拉会使弹簧与外壳摩擦，读数偏小；超过量程会使弹簧发生非弹性形变，测力计被损坏且读数不再可靠。"]]},{"type":"table","title":"重力与质量（最容易混的一对概念：一个随位置变，一个不变）","head":["比较项","质量 m","重力 G"],"rows":[["物理意义","物体所含物质的多少","由于地球吸引而使物体受到的力"],["单位","千克（kg）","牛顿（N）"],["测量工具","天平、秤","弹簧测力计"],["随位置变化","不变（到月球也不变）","变（月球上约为地球上的六分之一）"],["联系","G = mg 中的 m","G = mg 中的 G，g 取 9.8 N/kg 或 10 N/kg"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["力的示意图作图","要求画出物体受到的重力、拉力、支持力或压力的示意图，判分点是箭头方向、作用点位置与标注字母；斜面上的重力画成垂直于斜面是最常见的失分。"],["弹簧测力计的使用与读数","考查分度值的判断与读数、使用前的校零、拉力方向沿轴线、不能超过量程；也作为探究实验的测量工具，要求判断哪一步操作不规范。"],["探究弹簧的伸长量与拉力的关系","给实验数据表，要求分析数据得出结论（弹性限度内成正比）、找出比例系数，或预测某个拉力对应的伸长量，并解释为什么要用「伸长量」而不是「总长度」。"],["重力的计算与估测","用 G = mg 计算重力或反求质量，常与月球、太空、电梯情境结合；选择题多考生活量级估测（中学生重力约 500 N、鸡蛋约 0.5 N）。"]]},{"type":"quote","text":"【材料一】某小组探究弹簧的伸长量与拉力的关系，弹簧的原长是 10.0 cm，实验记录如下：\n拉力 F/N：0、0.5、1.0、1.5、2.0\n弹簧总长度 L/cm：10.0、11.0、12.0、13.0、14.0\n【材料二】弹簧测力计的使用说明：使用前要检查指针是否指在零刻度线上；测量时拉力的方向应沿弹簧的轴线方向；所测的力不能超过测力计的量程。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）依据材料一，算出每次弹簧的伸长量，并分析数据得出结论。（4 分）","【设问】（2）用这根弹簧做成弹簧测力计，某次测量时弹簧的总长度是 15.0 cm，此时它受到的拉力是多少？（4 分）","【设问】（3）依据材料二说明：为什么使用前要检查指针是否指零？为什么所测的力不能超过量程？（4 分）"]}],"questions":[{"id":"phy-mech-3-q1","type":"choice","stem":"用力推门时，把力作用在门把手附近比作用在靠近门轴处更容易把门推开，这说明力的作用效果与","answer":"A","explain":"两次推门，力的大小可以相同、方向也相同，唯一改变的是力的作用点（离门轴的距离），效果却明显不同，所以说明作用点影响力的作用效果，A 正确。B、C 所对应的变量在题中没有改变。D 中门还是那扇门，质量没变，而且「质量」不是力的三要素之一。","options":["力的作用点有关","力的大小有关","力的方向有关","门的质量有关"],"difficulty":1,"tags":["力的三要素"]},{"id":"phy-mech-3-q2","type":"choice","stem":"关于重力和它的方向，下列说法正确的是","answer":"B","explain":"重力的方向总是竖直向下，B 正确。A 错在「垂直向下」：那是垂直于接触面的方向，只有当接触面水平时才与竖直方向重合，物体放在斜面上时两者并不相同。C 错：重心是重力的等效作用点，圆环的重心在圆心，并不在环上。D 错：把物体带到月球，质量不变而重力变小，重力的大小与所在位置有关。","options":["重力的方向总是垂直向下","重力的方向总是竖直向下","物体的重心一定在物体上","物体所受重力的大小与它所在的位置无关"],"difficulty":1,"tags":["重力方向","重心"]},{"id":"phy-mech-3-q3","type":"choice","stem":"下图是某弹簧测力计的刻度放大示意（刻度从 2 N 到 3 N），指针所指位置表示它受到的拉力是","answer":"C","explain":"从 2 N 到 3 N 之间共分 5 格，每格 0.2 N，即分度值为 0.2 N。指针在 2 N 刻度下方第 2 格处，所以示数为 2 N + 2×0.2 N = 2.4 N，C 正确。A 少算了一格（把指针看成在第 1 格）；B 多算了一格；D 直接把指针当成落在 3 N 刻度上，相当于把 5 格看成了 1 格。读数题的第一步永远是先确定量程与分度值。","options":["2.2 N","2.6 N","2.4 N","3.0 N"],"difficulty":2,"tags":["弹簧测力计","读数"],"figure":{"id":"fig-mech-force-q3","title":"弹簧测力计的读数","caption":"先看清 2 N 到 3 N 之间分成了几格","view":"wide","alt":"弹簧测力计的示意图，外壳上的刻度从 2 牛到 3 牛，指针指在 2 牛下方第二格的位置","prims":[{"t":"rect","x":38,"y":10,"w":22,"h":40,"tone":"main"},{"t":"circle","cx":49,"cy":7,"r":2.6,"tone":"main"},{"t":"spring","x1":49,"y1":13,"x2":49,"y2":22,"coils":5},{"t":"text","x":49,"y":27,"text":"弹簧","size":3,"tone":"muted"},{"t":"line","x1":40,"y1":24,"x2":58,"y2":24,"width":0.7,"tone":"danger"},{"t":"line","x1":52,"y1":16,"x2":57,"y2":16,"width":0.4},{"t":"line","x1":52,"y1":20,"x2":57,"y2":20,"width":0.4},{"t":"line","x1":52,"y1":24,"x2":57,"y2":24,"width":0.4},{"t":"line","x1":52,"y1":28,"x2":57,"y2":28,"width":0.4},{"t":"line","x1":52,"y1":32,"x2":57,"y2":32,"width":0.4},{"t":"line","x1":52,"y1":36,"x2":57,"y2":36,"width":0.4},{"t":"text","x":60,"y":16,"text":"2","anchor":"start","size":3.4},{"t":"text","x":60,"y":36,"text":"3","anchor":"start","size":3.4},{"t":"line","x1":49,"y1":50,"x2":49,"y2":54,"width":0.6},{"t":"poly","points":[[47,54],[47,57],[51,57],[51,54]],"tone":"main"},{"t":"text","x":78,"y":24,"text":"指针","anchor":"start","size":3.4,"tone":"danger"},{"t":"line","x1":60,"y1":24,"x2":76,"y2":24,"dashed":true,"tone":"danger"}]}},{"id":"phy-mech-3-q4","type":"choice","stem":"下列估测中，最接近实际情况的是","answer":"D","explain":"中学生质量约 50 kg，取 g=10 N/kg，重力约 500 N，D 正确。B 的 50 N 相当于 5 kg，是婴儿的量级。A 错：一个鸡蛋质量约 50 g，重力约 0.5 N，写成 5 N 大了 10 倍。C 错：一支铅笔质量只有几克，重力约 0.02—0.05 N，离 2 N 差两个数量级。估测题要先把力换算成熟悉的质量再判断。","options":["一个鸡蛋的重力约为 5 N","一名中学生的重力约为 50 N","一支铅笔的重力约为 2 N","一名中学生的重力约为 500 N"],"difficulty":1,"tags":["重力估测"]},{"id":"phy-mech-3-q5","type":"fill","stem":"一个质量是 0.6 kg 的木块放在水平桌面上，它受到的重力是＿＿N。（g 取 10 N/kg）","answer":"6|6.0","explain":"由 G=mg=0.6\\ kg× 10\\ N/kg=6\\ N。常见错误是写成 0.6 N（忘了乘 g）或 6 kg（把力的单位写成质量的单位）。","difficulty":1,"tags":["重力计算"]},{"id":"phy-mech-3-q6","type":"fill","stem":"用弹簧测力计测得某物体受到的重力是 3.6 N，这个物体的质量是＿＿kg。（g 取 10 N/kg）","answer":"0.36|0.360","explain":"由 G=mg 变形得 m=(G)/(g)=3.6\\ N10\\ N/kg=0.36\\ kg。若答 36 kg，是把 3.6 除以 10 算成了乘以 10；若答 3.6 kg，是根本没有除以 g，把弹簧测力计的示数当成了质量。","difficulty":1,"tags":["重力计算","变形公式"]},{"id":"phy-mech-3-q7","type":"short","stem":"一名宇航员的质量是 60 kg。求他在地球上受到的重力；如果他登上月球，他的质量和受到的重力各是多少？（地球上 g 取 10 N/kg，月球上 g 取 1.6 N/kg）","answer":"在地球上：$G_{地}=mg_{地}=60\\ \\mathrm{kg}\\times 10\\ \\mathrm{N/kg}=600\\ \\mathrm{N}$。到月球上，宇航员所含物质的多少没有改变，质量仍是 60 kg；重力 $G_{月}=mg_{月}=60\\ \\mathrm{kg}\\times 1.6\\ \\mathrm{N/kg}=96\\ \\mathrm{N}$。","explain":"这道题考的是「质量不变、重力变」这一对关系。常见的错误有两种：一是到月球上把质量也改成 10 kg（错把重力当质量）；二是忘了换 g，月球上仍用 10 N/kg 算出 600 N。地球与月球的重力之比约为 6 : 1，60 kg 的宇航员在月球上重力只有 96 N，所以能轻松跳起来。","difficulty":2,"tags":["重力计算","质量与重力"],"rubric":["正确使用 G = mg 并代入 60 kg 与 10 N/kg","算得地球上重力 600 N","明确说明质量不随位置变化（仍为 60 kg）","算得月球上重力 96 N（用了月球的 g，不是 10 N/kg）"],"steps":["写出公式 G=mg。","代入地球上的数据：G_(地)=60\\ kg× 10\\ N/kg=600\\ N。","说明质量不随位置改变：月球上质量仍为 60 kg。","代入月球上的 g 计算：G_(月)=60\\ kg× 1.6\\ N/kg=96\\ N。","作答：地球上重力 600 N，月球上质量 60 kg、重力 96 N。"]},{"id":"phy-mech-3-q8","type":"short","stem":"某小组要探究「弹簧的伸长量与拉力的关系」，器材有弹簧、铁架台、钩码（每个 0.5 N）、刻度尺。请写出实验步骤，并说明为什么要在弹簧下挂不同数量的钩码多次测量。","answer":"步骤：① 把弹簧的一端固定在铁架台上，让弹簧自然下垂，用刻度尺测出弹簧的原长 L₀；② 在弹簧下端挂 1 个钩码，待弹簧静止后测出弹簧的总长度 L₁，算出伸长量 ΔL₁ = L₁ − L₀；③ 依次挂 2 个、3 个、4 个钩码，重复测量并记录每次的拉力 F 与伸长量 ΔL；④ 以 F 为纵轴、ΔL 为横轴描点作图（或计算 F 与 ΔL 的比值），分析得出结论。多次测量的目的：得到多组数据，才能看出伸长量与拉力之间是否存在正比关系，同时减小偶然误差，避免由一组数据得出片面结论。","explain":"这道实验题有两个必答点：一是「伸长量」必须用总长度减原长，不能直接拿总长度当伸长量；二是要有多组数据。数据处理有两种写法——画 F-ΔL 图像看是否过原点成直线，或算 F/ΔL 看比值是否为定值，两种都对。钩码逐个增加还隐含一个要求：所加拉力的最大值应在弹性限度内。","difficulty":2,"tags":["实验探究","弹力","数据分析"],"rubric":["器材与安装规范：弹簧竖直悬挂，先测原长 L₀","明确用「总长度减去原长」求伸长量 ΔL","逐次改变钩码数量（改变拉力）并记录多组数据","用图像或比值分析数据，得出「弹性限度内伸长量与拉力成正比」","说明多次测量的目的：找出规律、减小误差"],"figure":{"id":"fig-mech-3-spring-plan","title":"弹簧的伸长量与拉力的关系","caption":"在弹性限度内，弹簧的伸长量与所受拉力成正比：拉力每增加 0.5 N，伸长量按相同比例增加，图像是一条过原点的直线","view":"square","alt":"以拉力为横轴、弹簧伸长量为纵轴的坐标系中，一条直线从原点出发向右上方延伸；旁边画着竖直悬挂的弹簧，下端挂着一个钩码","prims":[{"t":"axis","x":34,"y":84,"w":52,"h":56,"xLabel":"F/N","yLabel":"Δx/cm","origin":true,"grid":true,"xTicks":[{"at":0.25,"label":"0.5"},{"at":0.5,"label":"1.0"},{"at":0.75,"label":"1.5"}]},{"t":"curve","points":[[34,84],[86,28]],"tone":"accent","width":1},{"t":"line","x1":16,"y1":14,"x2":28,"y2":14,"tone":"muted","width":0.8},{"t":"spring","x1":22,"y1":14,"x2":22,"y2":40,"coils":6,"label":"弹簧"},{"t":"line","x1":22,"y1":40,"x2":22,"y2":46,"tone":"main","width":0.5},{"t":"rect","x":15,"y":46,"w":14,"h":10,"tone":"muted","fill":true},{"t":"text","x":22,"y":66,"text":"0.5 N","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":22,"y":74,"text":"逐次加钩码","size":3.4,"tone":"accent","anchor":"middle"}]}},{"id":"phy-mech-3-q9","type":"short","stem":"一个木块静止在粗糙斜面上。请在下图中画出木块所受重力的示意图。","answer":"从木块的重心沿竖直方向向下画一条带箭头的线段，箭头竖直向下，标上字母 G。","explain":"作图的关键是方向：重力的方向只由重力本身决定，永远竖直向下，与物体放在什么面上无关。图中虚线画的是垂直于斜面的方向，那是支持力的方向，两者明显不同——把重力画成垂直于斜面，是这一类作图题最常见的错。另外，重力画在重心上，如果把作用点画在物体与斜面的接触面上，也很容易被扣分。","difficulty":2,"tags":["作图题","重力示意图"],"rubric":["作用点画在木块的重心上","箭头方向竖直向下（不是垂直于斜面向下）","标出字母 G，线段为直线且箭头规范","不画出题目没有要求的其它力（如支持力、摩擦力）"],"figure":{"id":"fig-mech-force-q9-blank","title":"静止在斜面上的木块","caption":"只要求画重力：注意方向与作用点","view":"wide","alt":"一个斜面，斜面上放着一块木块，木块静止，需要画出它受到的重力","prims":[{"t":"line","x1":14,"y1":44,"x2":96,"y2":44,"width":0.8},{"t":"hatch","x":14,"y":44,"w":82,"h":4.5,"gap":2.2},{"t":"incline","x":30,"y":44,"w":50,"deg":25},{"t":"poly","points":[[57.05,22.59],[60.43,29.83],[49.55,34.91],[46.17,27.67]],"closed":true,"fill":true,"tone":"accent"}]},"answerFigure":{"id":"fig-mech-force-q9-ans","title":"重力的示意图（标准作图）","caption":"重力的方向竖直向下，与斜面是否倾斜无关","view":"wide","alt":"斜面上的木块，从重心画出一条竖直向下的箭头，标注为 G，箭头方向与水平面垂直而不垂直于斜面","prims":[{"t":"line","x1":14,"y1":44,"x2":96,"y2":44,"width":0.8},{"t":"hatch","x":14,"y":44,"w":82,"h":4.5,"gap":2.2},{"t":"incline","x":30,"y":44,"w":50,"deg":25},{"t":"poly","points":[[57.05,22.59],[60.43,29.83],[49.55,34.91],[46.17,27.67]],"closed":true,"fill":true,"tone":"accent"},{"t":"circle","cx":53.3,"cy":28.75,"r":1.5,"fill":true,"tone":"danger"},{"t":"arrow","x1":53.3,"y1":28.75,"x2":53.3,"y2":43,"tone":"danger","label":"G","labelDx":4.5},{"t":"line","x1":62,"y1":26,"x2":68,"y2":38,"dashed":true,"tone":"muted"},{"t":"text","x":78,"y":34,"text":"垂直于斜面的是支持力方向","size":3.2,"tone":"muted"},{"t":"text","x":44,"y":56,"text":"重力竖直向下（与水平面垂直）","size":3.6,"tone":"ok"}]}},{"id":"phy-mech-3-m1-q1","type":"short","stem":"（1）依据材料一，算出每次弹簧的伸长量，并分析数据得出结论。（4 分）","answer":"伸长量分别为 0、1.0、2.0、3.0、4.0 cm，与对应拉力的比值都是 0.5 N/cm。结论：在弹性限度内，弹簧的伸长量与受到的拉力成正比。","explain":"","tags":["实验探究","弹力"],"rubric":["用总长度减去原长算出伸长量（0、1.0、2.0、3.0、4.0 cm）","指出伸长量与拉力的比值是定值（0.5 N/cm）","得出「弹性限度内，伸长量与拉力成正比」的结论","表述中限定「弹性限度内」这一条件"]},{"id":"phy-mech-3-m1-q2","type":"short","stem":"（2）用这根弹簧做成弹簧测力计，某次测量时弹簧的总长度是 15.0 cm，此时它受到的拉力是多少？（4 分）","answer":"伸长量 $\\Delta L=15.0\\ \\mathrm{cm}-10.0\\ \\mathrm{cm}=5.0\\ \\mathrm{cm}$。由 $F/\\Delta L=0.5\\ \\mathrm{N/cm}$ 得 $F=0.5\\ \\mathrm{N/cm}\\times 5.0\\ \\mathrm{cm}=2.5\\ \\mathrm{N}$。","explain":"","tags":["比例计算","弹力"],"rubric":["先算出伸长量 5.0 cm（不是直接用 15.0 cm）","正确使用比例关系（或用 2.0 N 对应 4.0 cm 推算）","算得拉力 2.5 N","结果带单位 N 并有结论性作答"]},{"id":"phy-mech-3-m1-q3","type":"short","stem":"（3）依据材料二说明：为什么使用前要检查指针是否指零？为什么所测的力不能超过量程？（4 分）","answer":"检查指针是否指零：若指针没有指在零刻度线上，每次测量的示数都会带有同一个偏差，测出的力偏大或偏小。不能超过量程：超过弹性限度后弹簧发生非弹性形变，不能完全恢复原状，测力计被损坏，而且此时伸长量与拉力不再成正比，读数也不可靠。","explain":"","tags":["实验评估","说理"],"rubric":["答出指针不指零会使每次读数都带上同一偏差（测量结果不准）","答出超过量程会使弹簧发生非弹性形变（不能恢复原状）","答出超过弹性限度后伸长量与拉力不再成正比","答出会损坏测力计"]}]},{"id":"phy-mech-4","title":"牛顿第一定律与惯性","subtitle":"人教版八下 · 第 8 章 运动和力 · 8b","grade":"8b","tags":["人教版八下 · 第 8 章 运动和力"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八下 · 第 8 章 运动和力 · 8b"},{"type":"note","title":"问题切入","text":"汽车急刹车时乘客为什么向前倾？为什么明明没有人「推」乘客，他还会往前冲？安全带和头枕到底在防什么？"},{"type":"note","title":"一句话抓住关键","text":"力不是维持运动的原因，而是改变运动状态的原因。牛顿第一定律：一切物体在没有受到力的作用时，总保持静止状态或匀速直线运动状态——它由斜面小车实验加上科学推理得出，不能由实验直接验证。惯性是一切物体保持原来运动状态不变的性质，只由质量决定。"},{"type":"h","text":"先看现象：让小车从同一高度滑下"},{"type":"p","text":"把同一辆小车每次都从斜面同一高度由静止释放，分别在毛巾、棉布、木板三种水平面上实验。看到的现象是：表面越光滑，小车滑得越远。控制「同一高度」是为了让小车到达水平面时的初速度相同，这样滑行距离的差别才只由表面的粗糙程度引起。"},{"type":"figure","figure":{"id":"fig-mech-inertia-1","title":"斜面小车实验的装置","caption":"每次都让小车从斜面同一高度由静止滑下","view":"wide","alt":"一个斜面接一段水平面，小车从斜面顶端由静止释放，水平面下方是地面，标注出小车与水平面","prims":[{"t":"line","x1":10,"y1":43,"x2":96,"y2":43,"width":0.8},{"t":"hatch","x":10,"y":43,"w":86,"h":4.5,"gap":2.2},{"t":"incline","x":10,"y":43,"w":30,"deg":25},{"t":"rect","x":42,"y":35,"w":11,"h":8,"rx":1,"fill":true,"tone":"accent"},{"t":"text","x":47,"y":52,"text":"小车","size":3.4,"tone":"accent"},{"t":"text","x":24,"y":12,"text":"由静止滑下","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":20,"text":"水平面：毛巾 → 棉布 → 木板","size":3.6,"tone":"muted"},{"t":"text","x":74,"y":26,"text":"只改变表面粗糙程度","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":54,"text":"表面越光滑，小车滑行越远","size":3.6,"tone":"ok"}]}},{"type":"note","title":"","text":"「同一高度」是控制变量：保证小车进入水平面时的速度相同，否则比较没有意义。"},{"type":"h","text":"抓住哪个量：阻力大小与滑行距离"},{"type":"p","text":"三次实验中，小车受到的重力、对水平面的压力都没有变，变的只有水平面的粗糙程度，也就是阻力。把三次结果并排画出来就看得很清楚：阻力越小，小车的速度减小得越慢，滑行的距离越长。这一步是从现象到规律的过渡——我们比较的不是「有没有力」，而是「阻力大不大」。"},{"type":"figure","figure":{"id":"fig-mech-inertia-2","title":"三种表面上小车滑行的距离","caption":"同一小车、同一高度，滑行距离随阻力减小而变长","view":"wide","alt":"三行对比图，小车分别在毛巾、棉布、木板上前进的虚线箭头越来越长，木板上的箭头最长","prims":[{"t":"text","x":50,"y":6,"text":"同一小车、同一高度滑下，只有表面不同","size":3.4,"tone":"muted"},{"t":"line","x1":10,"y1":20,"x2":92,"y2":20,"width":0.6},{"t":"rect","x":12,"y":12,"w":9,"h":8,"rx":1,"fill":true,"tone":"main"},{"t":"arrow","x1":24,"y1":16,"x2":40,"y2":16,"dashed":true,"tone":"danger"},{"t":"text","x":95,"y":20,"text":"毛巾","anchor":"end","size":3.4,"tone":"danger"},{"t":"line","x1":10,"y1":34,"x2":92,"y2":34,"width":0.6},{"t":"rect","x":12,"y":26,"w":9,"h":8,"rx":1,"fill":true,"tone":"main"},{"t":"arrow","x1":24,"y1":30,"x2":58,"y2":30,"dashed":true,"tone":"accent"},{"t":"text","x":95,"y":34,"text":"棉布","anchor":"end","size":3.4,"tone":"accent"},{"t":"line","x1":10,"y1":48,"x2":92,"y2":48,"width":0.6},{"t":"rect","x":12,"y":40,"w":9,"h":8,"rx":1,"fill":true,"tone":"main"},{"t":"arrow","x1":24,"y1":44,"x2":80,"y2":44,"dashed":true,"tone":"ok"},{"t":"text","x":95,"y":48,"text":"木板","anchor":"end","size":3.4,"tone":"ok"},{"t":"text","x":50,"y":58,"text":"阻力越小，速度减小得越慢，滑行越远","size":3.6,"tone":"ok"}]}},{"type":"h","text":"建立关系：把实验推到「不受力」的极限"},{"type":"p","text":"按这个趋势继续推下去：如果水平面绝对光滑、小车不受阻力，它的速度就不会减小，会永远以原来的速度做匀速直线运动。这就是牛顿第一定律。要特别注意它的来路：它是在实验事实的基础上经过科学推理得出的，不能用实验直接验证——因为现实中找不到完全不受力的物体。"},{"type":"figure","figure":{"id":"fig-mech-inertia-3","title":"从实验到推理","caption":"阻力越小滑得越远，推到不受阻力就是永远匀速直线运动","view":"wide","alt":"两行对比，上面一行小车受到阻力最终停下，下面一行小车不受阻力沿虚线一直向右匀速运动下去","prims":[{"t":"text","x":50,"y":7,"text":"实验现象 + 科学推理 → 牛顿第一定律","size":3.6,"tone":"muted"},{"t":"line","x1":8,"y1":26,"x2":62,"y2":26,"width":0.8},{"t":"rect","x":10,"y":18,"w":9,"h":8,"rx":1,"fill":true,"tone":"main"},{"t":"text","x":66,"y":26,"text":"有阻力：最终停下","anchor":"start","size":3.4,"tone":"muted"},{"t":"line","x1":8,"y1":44,"x2":86,"y2":44,"dashed":true,"width":0.7,"tone":"ok"},{"t":"rect","x":10,"y":36,"w":9,"h":8,"rx":1,"fill":true,"tone":"accent"},{"t":"arrow","x1":86,"y1":44,"x2":94,"y2":44,"tone":"ok"},{"t":"text","x":50,"y":54,"text":"不受阻力：永远做匀速直线运动","size":3.6,"tone":"ok"}]}},{"type":"note","title":"","text":"「物体不受力时总保持静止或匀速直线运动状态」——这一句就是牛顿第一定律的完整表述。"},{"type":"h","text":"抓住哪个量：惯性只与质量有关"},{"type":"p","text":"物体保持原来运动状态不变的性质叫惯性，一切物体在任何时候都有惯性，静止的、运动的、受力的、不受力的都有。惯性的大小只由质量决定：质量越大，运动状态越难改变。所以不能说「速度越大惯性越大」，也不能说「惯性是一种力」——惯性是性质，不是力，前面不能加「受到」两个字。"},{"type":"figure","figure":{"id":"fig-mech-inertia-4","title":"急刹车时乘客为什么向前倾","caption":"车减速了，人的上半身还要保持原来的运动状态","view":"wide","alt":"一辆向右行驶的公交车内，乘客的上半身向前倾斜，旁边标出上身继续向前移动的箭头","prims":[{"t":"line","x1":6,"y1":46,"x2":94,"y2":46,"width":0.8},{"t":"hatch","x":6,"y":46,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":10,"y":16,"w":48,"h":26,"rx":2,"fill":true,"tone":"main"},{"t":"circle","cx":22,"cy":43.5,"r":2.5},{"t":"circle","cx":44,"cy":43.5,"r":2.5},{"t":"circle","cx":26,"cy":26,"r":2.8,"tone":"accent","fill":true},{"t":"line","x1":26,"y1":28.8,"x2":23.5,"y2":38,"width":1.2,"tone":"accent"},{"t":"arrow","x1":28,"y1":21,"x2":40,"y2":21,"tone":"danger","label":"上身继续前移","labelDy":-3},{"t":"text","x":62,"y":30,"text":"车减速","size":3.6,"tone":"muted"},{"t":"arrow","x1":62,"y1":34,"x2":74,"y2":34,"tone":"muted"},{"t":"text","x":50,"y":53,"text":"乘客向前倾：不是受到向前的力，而是惯性","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":59,"text":"上身要保持原来的运动状态，脚却被车带着减速","size":3.4,"tone":"muted"}]}},{"type":"h","text":"换个情境：把惯性用起来"},{"type":"p","text":"锤头松了，把锤柄的一端在地面上撞几下，锤柄突然停止运动，锤头由于惯性继续向下运动，就紧紧套在锤柄上。跳远要助跑、拍打衣服除尘、紧固斧头，道理都一样：先用上运动，再让其中一部分突然停止或改变，另一部分「留在原地」。安全气囊、安全带、汽车头枕同样是在利用和防范惯性。"},{"type":"figure","figure":{"id":"fig-mech-inertia-5","title":"锤头为什么会套紧","caption":"锤柄撞地后停止，锤头由于惯性继续向下","view":"wide","alt":"一把锤子，锤柄竖直向下撞击地面，锤头旁边有一个向下的箭头表示锤头由于惯性继续向下运动","prims":[{"t":"line","x1":8,"y1":44,"x2":92,"y2":44,"width":0.8},{"t":"hatch","x":8,"y":44,"w":84,"h":4.5,"gap":2.2},{"t":"rect","x":42,"y":10,"w":16,"h":9,"rx":1,"fill":true,"tone":"main","label":"锤头"},{"t":"line","x1":50,"y1":19,"x2":50,"y2":43,"width":1.4},{"t":"arrow","x1":66,"y1":12,"x2":66,"y2":30,"tone":"danger","label":"锤头继续向下","labelDx":6},{"t":"text","x":24,"y":26,"text":"锤柄","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"锤柄撞地后停止，锤头由于惯性继续向下运动","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":59,"text":"结果：锤头被套紧在锤柄上","size":3.4,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["牛顿第一定律","一切物体在没有受到力的作用时，总保持静止状态或匀速直线运动状态。","定律说的是「不受力」的理想情况；实际中物体受到的力如果互相平衡（合力为零），效果与不受力相同，同样保持静止或匀速直线运动。它是由斜面小车实验加上科学推理得出的，不能用实验直接验证。"],["惯性","一切物体都有保持原来运动状态不变的性质，叫惯性；惯性大小只由物体的质量决定。","惯性是性质不是力，不能说「受到惯性」「惯性力的作用」；解释惯性现象时要按「原来的运动状态 → 哪一部分状态改变了 → 哪一部分由于惯性保持原状态 → 出现什么现象」四步写。"],["反应距离（惯性导致的匀速段）","s = v t","s：米（m）；v：米每秒（m/s）；t：秒（s） · 用于计算司机发现情况到踩下刹车这段时间内汽车通过的距离：这段时间内汽车仍按原速度匀速行驶，可直接用速度公式计算。"]]},{"type":"h","text":"应用 · 应用一：安全带与头枕分别在防什么"},{"type":"note","title":"情境","text":"汽车急刹车时，人会猛地向前冲；汽车被后车追尾时，人的头会向后甩。安全带与座椅头枕分别针对这两种情况设计。"},{"type":"note","title":"模型与思路","text":"以人为研究对象：人原来与车一起向前运动。急刹车时车突然减速，人的下半身被座椅和车带着减速，而上半身由于惯性仍要保持原来的运动状态，于是向前倾；被追尾时车突然加速向前，人的身体随座椅一起加速，头部由于惯性「留在原来的位置」，相对车身向后仰。"},{"type":"list","title":"解答步骤","items":["确定研究对象原来的运动状态：人与车一起向前运动","急刹车：车的速度迅速减小，人上半身由于惯性要保持原来的速度 → 身体前倾，安全带从胸前把人拉住，防止撞向前方","被追尾：车突然加速，人的头由于惯性保持原来的慢速 → 头相对车身向后仰，头枕托住头颈，防止颈部受伤","得出结论：安全带与头枕都是用来在速度突变时约束人的惯性带来的相对运动"]},{"type":"figure","figure":{"id":"fig-mech-inertia-6","title":"安全带的作用","caption":"急刹车时人前倾，安全带把人拉住","view":"wide","alt":"一辆汽车内坐着乘客，从肩部到腰部的安全带斜跨在胸前，乘客上身略微前倾，车轮下方是路面","prims":[{"t":"line","x1":8,"y1":46,"x2":92,"y2":46,"width":0.8},{"t":"hatch","x":8,"y":46,"w":84,"h":4.5,"gap":2.2},{"t":"rect","x":12,"y":16,"w":46,"h":26,"rx":2,"fill":true,"tone":"main"},{"t":"circle","cx":24,"cy":43.5,"r":2.5},{"t":"circle","cx":46,"cy":43.5,"r":2.5},{"t":"circle","cx":28,"cy":26,"r":2.8,"tone":"accent","fill":true},{"t":"line","x1":28,"y1":28.8,"x2":26,"y2":38,"width":1.2,"tone":"accent"},{"t":"line","x1":23,"y1":23,"x2":33,"y2":37,"width":0.9,"tone":"danger"},{"t":"text","x":46,"y":34,"text":"安全带","anchor":"start","size":3.4,"tone":"danger"},{"t":"text","x":72,"y":26,"text":"急刹车：人前倾","size":3.5,"tone":"muted"},{"t":"text","x":72,"y":34,"text":"被追尾：头后仰，头枕保护头颈","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"安全带与头枕都不能改变惯性，只是约束相对运动","size":3.4,"tone":"ok"}]}},{"type":"note","title":"结论","text":"安全带防「向前冲」，头枕防「向后仰」；它们改变不了惯性，只是用约束力让人和车一起改变运动状态。"},{"type":"h","text":"应用 · 应用二：反应距离与刹车距离"},{"type":"note","title":"情境","text":"一辆汽车以 15 m/s 的速度在平直公路上匀速行驶。司机发现前方有情况，经过 0.8 s 的反应时间才开始刹车，刹车后汽车又滑行了 9 m 才停下来。求反应时间内汽车通过的路程，以及从发现情况到停下的总路程。"},{"type":"note","title":"模型与思路","text":"把整个过程分成两段：反应时间内司机还没踩刹车，汽车仍按原速度做匀速直线运动；刹车后汽车减速滑行。两段的路程相加就是总路程。反应时间内汽车仍在运动，正是惯性导致的。"},{"type":"list","title":"解答步骤","items":["反应时间内汽车匀速行驶：s₁=v t₁=15\\ m/s× 0.8\\ s=12\\ m","刹车后汽车滑行的路程由题意给出：s₂=9\\ m","总路程 s=s₁+s₂=12\\ m+9\\ m=21\\ m","结论与安全提示：司机不能立即停车，从发现情况到停下的距离包括反应距离与刹车距离两部分"]},{"type":"figure","figure":{"id":"fig-mech-inertia-7","title":"反应距离与刹车距离","caption":"反应时间里车还在匀速前进，这部分路程由惯性「贡献」","view":"wide","alt":"一条平直的公路上，汽车先匀速前进一段表示反应距离，再减速滑行一段表示刹车距离，两段用箭头标出","prims":[{"t":"line","x1":10,"y1":32,"x2":92,"y2":32,"width":0.6},{"t":"line","x1":12,"y1":38,"x2":12,"y2":28,"width":0.5},{"t":"line","x1":46,"y1":38,"x2":46,"y2":28,"width":0.5},{"t":"line","x1":64,"y1":38,"x2":64,"y2":28,"width":0.5},{"t":"rect","x":12,"y":24,"w":11,"h":8,"rx":1,"fill":true,"tone":"main"},{"t":"arrow","x1":24,"y1":26,"x2":44,"y2":26,"tone":"muted"},{"t":"arrow","x1":46,"y1":26,"x2":63,"y2":26,"tone":"danger"},{"t":"text","x":32,"y":18,"text":"反应距离 12 m","size":3.4,"tone":"muted"},{"t":"text","x":62,"y":18,"text":"刹车距离 9 m","size":3.4,"tone":"danger"},{"t":"text","x":20,"y":48,"text":"发现情况","size":3.2,"tone":"muted"},{"t":"text","x":55,"y":48,"text":"开始刹车","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":57,"text":"总路程 21 m，其中前 12 m 是匀速行驶的距离","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"反应距离 12 m，从发现情况到停下的总路程是 21 m；车速越大、反应越慢，这段距离越长，所以要限速、要保持车距、严禁酒驾。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为「物体运动需要力来维持」，「没有推力物体就会立刻停下」。","力是改变物体运动状态的原因，不是维持运动的原因。物体停下来是因为受到了阻力，而不是因为「没有推力」。","这正是牛顿第一定律要纠正的直觉错误。斜面小车实验中，表面越光滑小车滑得越远，说明让小车停下的原因是阻力，而不是缺少推力。"],["说「物体受到惯性作用」「惯性力使乘客向前冲」，或认为「速度越大惯性越大」。","惯性是物体本身的性质，不是力，只能说「由于惯性」；惯性大小只由质量决定，与速度、受力情况都无关。","乘客向前倾的原因是「上身要保持原来的运动状态」，画受力示意图时也不能凭空添一个「惯性力」的箭头——这是受力分析题里最典型的错误。"],["认为牛顿第一定律可以用实验直接验证，或认为「静止的物体没有惯性」。","牛顿第一定律是在实验基础上经过科学推理概括出来的，现实中找不到完全不受力的物体，所以不能直接验证；一切物体在任何情况下都有惯性，静止的物体同样有。","惯性是一切物体的固有属性，与运动状态无关。把「不受力」当成定律成立的前提条件、再去问「静止物体有没有惯性」，是把条件与属性混为一谈。"]]},{"type":"table","title":"牛顿第一定律与惯性（一个是规律，一个是性质：考试最爱的辨析）","head":["比较项","牛顿第一定律","惯性"],"rows":[["是什么","描述物体不受力时运动规律的定律","物体保持原来运动状态不变的性质"],["成立条件","物体没有受到力的作用（或合力为零）","一切物体、任何时候都有，无条件"],["是否与质量有关","定律本身不涉及质量","惯性大小只由质量决定"],["怎么得到","实验 + 科学推理，不能直接验证","由现象归纳出的属性，可直接由实验现象说明"],["典型说法","不受力时保持静止或匀速直线运动","由于惯性，物体要保持原来的运动状态"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["探究阻力对物体运动的影响","以斜面小车实验为背景，考查控制变量（同一高度、同一小车）、推理得出结论的方法，以及「为什么不能直接验证」这一科学方法层面的追问。"],["用惯性解释生活现象","急刹车前倾、跳远助跑、拍打衣服除尘、锤头套紧、跳伞与安全带等情境，要求按固定的四步写法解释，判分点在于是否说清「哪部分状态改变、哪部分由于惯性保持原状」。"],["力与运动关系的判断","选择题常设置「物体运动一定受力」「物体受力运动状态一定改变」等表述，考查「力是改变运动状态的原因」这一核心观点。"],["交通安全情境的综合计算","结合反应距离、刹车距离、限速与车距的计算与说理，属于「阅读与理解」类非选择题的常见形态，需要先分清哪一段是匀速、哪一段是减速。"]]},{"type":"quote","text":"【材料一】某小组用同一辆小车做「阻力对物体运动的影响」实验：小车每次都从斜面同一高度由静止滑下，分别在毛巾、棉布、木板表面上运动，测出小车运动的距离分别为 0.21 m、0.39 m、0.62 m。\n【材料二】汽车在行驶中遇到紧急情况，司机从发现情况到踩下刹车需要一段时间，这段时间叫反应时间，一般为 0.4—1.0 s；在这段时间里汽车仍按原来的速度前进。\n【材料三】雨天路滑，汽车的刹车距离会明显变长。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）依据材料一，说明为什么要让小车每次都从斜面同一高度由静止滑下，并写出由实验数据可以得出的结论和进一步推理得到的规律。（6 分）","【设问】（2）依据材料二，汽车以 15 m/s 匀速行驶，司机的反应时间为 0.8 s。求反应时间内汽车通过的距离，并说明这段时间里汽车的运动状态。（4 分）","【设问】（3）依据材料三说明：雨天为什么要减慢车速、加大车距？（4 分）"]}],"questions":[{"id":"phy-mech-4-q1","type":"choice","stem":"关于牛顿第一定律，下列说法正确的是","answer":"A","explain":"A 就是牛顿第一定律的完整表述，正确。B 错：力是改变运动状态的原因，不是维持运动的原因，物体停下是因为受到阻力。C 错：现实中找不到完全不受力的物体，定律是实验加科学推理得出的，不能直接验证。D 错：惯性大小只由质量决定，与速度无关，速度大的物体惯性并不更大。","options":["物体在没有受到力的作用时，总保持静止状态或匀速直线运动状态","物体只有受到力的作用才能运动，没有力就会立刻停下","牛顿第一定律是直接由实验测量得出的","物体运动的速度越大，惯性就越大"],"difficulty":1,"tags":["牛顿第一定律"]},{"id":"phy-mech-4-q2","type":"choice","stem":"跳远运动员在起跳前要助跑一段距离，这样做是为了","answer":"B","explain":"助跑使运动员在起跳时已经具有较大的向前速度，起跳后由于惯性他要保持原来的运动状态，于是能在空中继续向前运动，跳得更远，B 正确。A 错：惯性只由质量决定，助跑不改变质量，所以惯性大小不变，助跑只是「利用」惯性。C、D 都错：重力由质量和 g 决定，助跑既不改变质量、也不改变 g。","options":["增大自身的惯性","利用惯性提高跳远成绩","减小自身受到的重力","增大自身受到的重力"],"difficulty":1,"tags":["惯性","生活应用"]},{"id":"phy-mech-4-q3","type":"choice","stem":"下图是公交车急刹车时乘客身体前倾的情景，关于乘客前倾的原因，下列说法正确的是","answer":"C","explain":"乘客原来随车一起向前运动，车突然减速时，乘客的下半身被车带着一起减速，而上半身由于惯性要保持原来的运动状态，于是相对车身向前倾，C 正确。A 错：只有座椅、车体可能对人施加向后的力，没有哪个物体给他向前的推力，前倾是惯性造成的。B 错：惯性是物体固有的性质，任何情况下都有，不会消失。D 错：惯性不是力，不能与重力比较大小。","options":["乘客受到一个方向向前的力推着他","汽车刹车时乘客的惯性消失了","乘客的上半身由于惯性要保持原来的运动状态，所以向前倾","乘客受到的惯性大于他受到的重力"],"difficulty":2,"tags":["惯性","配图判断"],"figure":{"id":"fig-mech-inertia-q3","title":"急刹车时乘客前倾","caption":"车减速了，人的上半身还要保持原来的运动状态","view":"wide","alt":"公交车内一名乘客在车减速时上半身向前倾斜，旁边有一个向前的箭头","prims":[{"t":"line","x1":6,"y1":46,"x2":94,"y2":46,"width":0.8},{"t":"hatch","x":6,"y":46,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":10,"y":16,"w":52,"h":26,"rx":2,"fill":true,"tone":"main"},{"t":"circle","cx":22,"cy":43.5,"r":2.5},{"t":"circle","cx":48,"cy":43.5,"r":2.5},{"t":"circle","cx":28,"cy":26,"r":2.8,"tone":"accent","fill":true},{"t":"line","x1":28,"y1":28.8,"x2":25.5,"y2":38,"width":1.2,"tone":"accent"},{"t":"arrow","x1":30,"y1":21,"x2":42,"y2":21,"tone":"danger"},{"t":"text","x":74,"y":30,"text":"v","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"乘客的脚随车减速，上半身仍要保持原来的运动状态","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-4-q4","type":"choice","stem":"关于物体的惯性，下列说法正确的是","answer":"D","explain":"惯性是物体保持原来运动状态不变的性质，其大小只由质量决定，与其他因素无关，D 正确。A 错：速度大小不影响惯性，质量相同、速度不同的物体惯性一样大。B 错：静止的物体同样有惯性，正因为它有惯性，才需要用力才能推动它。C 错：受力大小与惯性无关，惯性是物体本身的属性，不是力作用的结果。","options":["物体运动得越快，惯性越大","物体静止时没有惯性","物体受到的力越大，惯性越大","惯性的大小只由物体的质量决定"],"difficulty":1,"tags":["惯性大小"]},{"id":"phy-mech-4-q5","type":"fill","stem":"汽车以 20 m/s 的速度匀速行驶，司机发现前方有情况，经过 0.6 s 的反应时间才开始刹车。反应时间内汽车行驶的路程是＿＿m。","answer":"12|12.0","explain":"反应时间内司机还没有踩刹车，汽车仍以 20 m/s 做匀速直线运动，s=vt=20\\ m/s× 0.6\\ s=12\\ m。答 0.6 m 之类，是把速度当成了路程；答 33.3 m，是把除法做成了乘法。","difficulty":2,"tags":["速度计算","惯性"]},{"id":"phy-mech-4-q6","type":"fill","stem":"在探究「阻力对物体运动的影响」的实验中，小车从斜面同一高度由静止滑下，水平面越光滑，小车受到的阻力越小，它滑行的距离就越＿＿。","answer":"远|长|更远|更长","explain":"阻力越小，小车的速度减小得越慢，所以滑行距离越远。这一现象的进一步推理就是：若不受阻力，小车将永远做匀速直线运动。填「近」是把关系看反了；填「快」是把速度与距离混为一谈。","difficulty":1,"tags":["实验结论","牛顿第一定律"]},{"id":"phy-mech-4-q7","type":"short","stem":"一辆汽车以 15 m/s 的速度在平直公路上匀速行驶，司机发现情况后经过 0.8 s 开始刹车，刹车后汽车又滑行了 9 m 才停下。求反应时间内汽车行驶的路程，以及从发现情况到汽车停下的总路程。","answer":"反应时间内汽车仍按原速度做匀速直线运动：$s_1=vt=15\\ \\mathrm{m/s}\\times 0.8\\ \\mathrm{s}=12\\ \\mathrm{m}$。刹车后滑行的路程 $s_2=9\\ \\mathrm{m}$。总路程 $s=s_1+s_2=12\\ \\mathrm{m}+9\\ \\mathrm{m}=21\\ \\mathrm{m}$。","explain":"这类题的难点不在计算而在「分过程」：很多同学直接用 15 m/s 乘 0.8 s 之外的数，或者把 9 m 当成总路程。要养成先画示意图或先分段的习惯，把「匀速段」和「减速段」分开算再相加。从物理上看，反应距离的存在正是因为惯性——司机的反应需要时间，而车在这段时间里不会自己减速。","difficulty":2,"tags":["解答与计算","惯性"],"rubric":["正确分过程，指出反应时间内做匀速直线运动","用 s = vt 算出反应距离 12 m（单位正确）","把两段路程相加得 21 m","有明确的结论性作答（两个问都回答）"],"steps":["分过程：从发现情况到踩下刹车是匀速运动，刹车后是减速运动。","求反应距离：s₁=vt=15\\ m/s× 0.8\\ s=12\\ m。","刹车距离由题意直接给出：s₂=9\\ m。","求总路程：s=s₁+s₂=21\\ m。","作答：反应距离 12 m，从发现情况到停下的总路程是 21 m。"],"figure":{"id":"fig-mech-4-brake","title":"反应距离与刹车距离","caption":"从发现情况到开始刹车（0.8 s）汽车仍以 15 m/s 匀速前进，这段是反应距离；刹车后又滑行 9 m 才停下","view":"wide","alt":"平直的公路上有一辆汽车，司机位置画有发现情况的标记；从该处到开始刹车处标出反应距离，从开始刹车处到停车处标出刹车距离 9 米","prims":[{"t":"line","x1":4,"y1":48,"x2":96,"y2":48,"tone":"muted","width":1},{"t":"hatch","x":4,"y":48,"w":92,"h":3,"tone":"muted"},{"t":"rect","x":12,"y":36,"w":16,"h":10,"tone":"main","fill":true},{"t":"circle","cx":16,"cy":47,"r":2.2,"tone":"muted"},{"t":"circle","cx":24,"cy":47,"r":2.2,"tone":"muted"},{"t":"text","x":20,"y":33,"text":"v = 15 m/s","size":3.4,"tone":"accent","anchor":"middle"},{"t":"text","x":28,"y":30,"text":"发现情况（开始计时）","size":3.2,"tone":"danger","anchor":"start"},{"t":"line","x1":28,"y1":24,"x2":28,"y2":48,"tone":"danger","dashed":true},{"t":"line","x1":52,"y1":24,"x2":52,"y2":48,"tone":"danger","dashed":true},{"t":"line","x1":76,"y1":24,"x2":76,"y2":48,"tone":"danger","dashed":true},{"t":"arrow","x1":28,"y1":20,"x2":52,"y2":20,"tone":"accent","label":"反应距离"},{"t":"arrow","x1":52,"y1":20,"x2":76,"y2":20,"tone":"muted","label":"刹车距离 9 m"},{"t":"rect","x":60,"y":36,"w":16,"h":10,"tone":"muted","fill":true,"dashed":true},{"t":"text","x":50,"y":58,"text":"反应距离 = vt = 15 m/s × 0.8 s = 12 m；总路程 = 12 m + 9 m","size":3.6,"tone":"main","anchor":"middle"}]}},{"id":"phy-mech-4-q8","type":"short","stem":"某小组要探究「阻力对物体运动的影响」，器材有斜面、小车、毛巾、棉布、木板、刻度尺。请写出实验步骤，并说明为什么这一实验还得不出牛顿第一定律、需要补充什么。","answer":"步骤：① 把毛巾铺在水平面上，让小车从斜面同一高度由静止滑下，用刻度尺量出小车在水平面上滑行的距离；② 换用棉布、木板重复上述实验，每次都从同一高度由静止滑下；③ 比较三次滑行的距离，发现表面越光滑、阻力越小，小车滑行得越远；④ 在此基础上推理：如果水平面绝对光滑、小车不受阻力，它将永远做匀速直线运动。仅仅靠实验得不出牛顿第一定律，因为现实中不存在完全不受力的物体，无法用实验直接验证「不受力」的情形，只能由实验事实加上科学推理概括出来。","explain":"这一实验的价值一半在操作、一半在方法。操作上的关键是控制变量：同一小车、同一斜面、同一高度，否则比较滑行距离没有意义。方法上的关键是「理想实验」——实验只能做到阻力越来越小，不能做到阻力为零，所以结论的最后一跳必须靠推理。答题时把这两层都写出来，才算答到点上。","difficulty":2,"tags":["实验探究","理想实验"],"rubric":["器材与操作规范：三种表面、同一小车、从斜面同一高度由静止滑下","用刻度尺测出滑行距离并比较（体现控制变量）","由实验现象推理出「不受阻力将永远匀速直线运动」","说明定律是实验加推理得出的，不能由实验直接验证"]},{"id":"phy-mech-4-q9","type":"short","stem":"一辆小车在水平木板上向右滑行，速度越来越小。请在图中画出小车此时所受力的示意图（不计空气阻力）。","answer":"小车一共受到三个力：重力 G，从重心竖直向下；支持力 N，从重心竖直向上，与重力大小相等；摩擦力 f，沿水平面向左（与运动方向相反）。","explain":"受力分析要按「先重力、再看接触」的顺序：重力不管怎样都有；小车与木板接触，所以有支持力和摩擦力；题目说明不计空气阻力，就不用画。竖直方向小车没有上下运动，重力和支持力是一对平衡力，长度应画得差不多；水平方向只有摩擦力，所以小车的速度越来越小——这正是「力改变运动状态」的例子。最容易犯的错是凭直觉添一个「向前的惯性力」，惯性不是力，不能画。","difficulty":3,"tags":["作图题","受力分析"],"rubric":["重力 G：作用点在重心，方向竖直向下","支持力 N：方向竖直向上，与重力大小相等（画成等长即可）","摩擦力 f：沿水平方向、指向左（与运动方向相反）","箭头规范、标注字母，不画出多余的力（不能画「惯性力」）"],"figure":{"id":"fig-mech-inertia-q9-blank","title":"在木板上向右滑行的小车","caption":"先想清楚小车受到哪几个力，再逐一画箭头","view":"wide","alt":"水平木板上有一辆向右滑行的小车，木板上方画出了小车的轮廓，需要画出它受到的力","prims":[{"t":"line","x1":8,"y1":42,"x2":94,"y2":42,"width":0.8},{"t":"hatch","x":8,"y":42,"w":86,"h":4.5,"gap":2.2},{"t":"rect","x":38,"y":28,"w":24,"h":14,"rx":1,"fill":true,"tone":"main"},{"t":"text","x":76,"y":26,"text":"运动方向 →","size":3.6,"tone":"muted"}]},"answerFigure":{"id":"fig-mech-inertia-q9-ans","title":"滑行小车的受力示意图（标准作图）","caption":"竖直方向两个力平衡，水平方向只有摩擦力，所以小车减速","view":"wide","alt":"水平木板上的小车，重心处画出三个箭头：重力竖直向下、支持力竖直向上、摩擦力水平向左","prims":[{"t":"line","x1":8,"y1":42,"x2":94,"y2":42,"width":0.8},{"t":"hatch","x":8,"y":42,"w":86,"h":4.5,"gap":2.2},{"t":"rect","x":38,"y":28,"w":24,"h":14,"rx":1,"fill":true,"tone":"main"},{"t":"circle","cx":50,"cy":35,"r":1.5,"fill":true,"tone":"danger"},{"t":"arrow","x1":50,"y1":35,"x2":50,"y2":56,"tone":"accent","label":"G","labelDx":5},{"t":"arrow","x1":50,"y1":35,"x2":50,"y2":18,"tone":"ok","label":"N","labelDx":5},{"t":"arrow","x1":50,"y1":35,"x2":22,"y2":35,"tone":"danger","label":"f","labelDy":-4},{"t":"text","x":80,"y":26,"text":"运动方向 →","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":62,"text":"摩擦力与运动方向相反，是它让小车减速","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-4-m1-q1","type":"short","stem":"（1）依据材料一，说明为什么要让小车每次都从斜面同一高度由静止滑下，并写出由实验数据可以得出的结论和进一步推理得到的规律。（6 分）","answer":"从同一高度由静止滑下，是为了让小车到达水平面时的速度相同（控制变量），这样小车滑行距离的不同就只能由表面的粗糙程度（阻力大小）引起。结论：表面越光滑，小车受到的阻力越小，速度减小得越慢，滑行的距离越远。进一步推理：如果小车不受阻力，它的速度将不会减小，会永远以原来的速度做匀速直线运动——这就是牛顿第一定律。","explain":"","tags":["实验探究","科学推理"],"rubric":["答出「同一高度由静止滑下」是为了控制小车进入水平面时的速度相同","答出阻力越小、滑行距离越远（结合数据 0.21 m、0.39 m、0.62 m）","由推理得出「不受力时永远做匀速直线运动」","指出该规律是在实验基础上推理得出的，不能用实验直接验证"]},{"id":"phy-mech-4-m1-q2","type":"short","stem":"（2）依据材料二，汽车以 15 m/s 匀速行驶，司机的反应时间为 0.8 s。求反应时间内汽车通过的距离，并说明这段时间里汽车的运动状态。（4 分）","answer":"反应时间内司机还未踩刹车，汽车仍以 15 m/s 做匀速直线运动，通过的距离 $s=vt=15\\ \\mathrm{m/s}\\times 0.8\\ \\mathrm{s}=12\\ \\mathrm{m}$。这段距离说明：虽然司机已经发现了情况，但由于惯性汽车不能立即减速，必须行驶一段距离后才开始刹车。","explain":"","tags":["速度计算","惯性"],"rubric":["判断出反应时间内汽车做匀速直线运动","用 s = vt 计算并代入正确数据","算得 12 m 且带单位","用惯性说明这段时间汽车为什么仍在前进"]},{"id":"phy-mech-4-m1-q3","type":"short","stem":"（3）依据材料三说明：雨天为什么要减慢车速、加大车距？（4 分）","answer":"雨天路面变滑，轮胎与地面之间的阻力变小。由斜面小车实验的结论可知，阻力越小，汽车速度减小得越慢、刹车距离越长；同时车速越大，反应时间内行驶的距离也越长。因此雨天必须减小车速并加大与前车的距离，才能在发现情况后及时停下，避免追尾。","explain":"","tags":["说理","交通安全"],"rubric":["答出雨天路面阻力变小","答出阻力小则刹车距离变长（速度减小得慢）","答出车速越大反应距离越长","得出结论：应减速、加大车距（有安全表述）"]}]},{"id":"phy-mech-5","title":"二力平衡与摩擦力","subtitle":"人教版八下 · 第 8 章 运动和力 · 8b","grade":"8b","tags":["人教版八下 · 第 8 章 运动和力"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八下 · 第 8 章 运动和力 · 8b"},{"type":"note","title":"问题切入","text":"用力推箱子没推动，是推力比摩擦力小吗？为什么自行车刹车时用力捏闸能更快停下，而轮胎花纹磨平后刹车会变差？"},{"type":"note","title":"一句话抓住关键","text":"物体处于静止或匀速直线运动状态时，受到的力互相平衡：两个力必须作用在同一物体上、大小相等、方向相反、作用在同一条直线上。摩擦力是阻碍相对运动（或相对运动趋势）的力，滑动摩擦力的大小只与压力大小和接触面的粗糙程度有关，与接触面积、速度都无关。"},{"type":"h","text":"先看现象：推不动，摩擦力是不是更大"},{"type":"p","text":"用力推箱子，箱子没动，很多同学认定「摩擦力大于推力」。但真相正相反：箱子静止，说明它在水平方向受到的推力与摩擦力是一对平衡力，两者大小相等。继续加大推力，箱子仍然没动，是因为静摩擦力也跟着变大；当推力增大到某一数值时，箱子被推动，此后摩擦力反而不再随推力增大而增大。"},{"type":"figure","figure":{"id":"fig-mech-balance-1","title":"推不动时的受力关系","caption":"箱子静止，推力与摩擦力大小相等、方向相反","view":"wide","alt":"水平地面上一个箱子，左上方有一个向右的推力箭头，左下角有一个向左的摩擦力箭头，两个力大小相等","prims":[{"t":"line","x1":6,"y1":44,"x2":94,"y2":44,"width":0.8},{"t":"hatch","x":6,"y":44,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":34,"y":22,"w":28,"h":22,"fill":true,"tone":"main","label":"箱子"},{"t":"arrow","x1":14,"y1":31,"x2":33,"y2":31,"tone":"accent"},{"t":"arrow","x1":34,"y1":41,"x2":15,"y2":41,"tone":"danger"},{"t":"text","x":22,"y":26,"text":"F推","size":3.6,"tone":"accent"},{"t":"text","x":23,"y":48,"text":"f","size":3.6,"tone":"danger"},{"t":"text","x":50,"y":56,"text":"箱子静止：F推 与 f 是一对平衡力，大小相等","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":61,"text":"推力增大，静摩擦力也增大，直到刚好被推动","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"「推不动说明摩擦力更大」是初中最顽固的错误直觉，必须用平衡力的思路纠正。"},{"type":"h","text":"抓住哪个量：二力平衡的四个条件"},{"type":"p","text":"二力平衡的条件有四条：作用在同一物体上、大小相等、方向相反、作用在同一条直线上，缺一不可。任何一条不满足，物体都不会保持静止或匀速直线运动。判断时最容易被忽略的是第一条——力必须作用在同一个物体上，这正是平衡力与相互作用力的分水岭。"},{"type":"figure","figure":{"id":"fig-mech-balance-2","title":"二力平衡的四个条件","caption":"同物、等大、反向、共线","view":"wide","alt":"水平地面的箱子上，左右各有一个大小相等、方向相反的力，两个力作用在同一条水平线上","prims":[{"t":"line","x1":6,"y1":44,"x2":94,"y2":44,"width":0.8},{"t":"hatch","x":6,"y":44,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":34,"y":22,"w":28,"h":22,"fill":true,"tone":"main"},{"t":"circle","cx":48,"cy":33,"r":1.5,"fill":true,"tone":"danger"},{"t":"arrow","x1":34,"y1":33,"x2":12,"y2":33,"tone":"accent","label":"F₁","labelDy":-4},{"t":"arrow","x1":62,"y1":33,"x2":84,"y2":33,"tone":"accent","label":"F₂","labelDy":-4},{"t":"text","x":50,"y":56,"text":"同物、等大、反向、共线，四个条件缺一不可","size":3.8,"tone":"ok"},{"t":"text","x":50,"y":61,"text":"两个力都作用在这个箱子上（同一物体）","size":3.4,"tone":"muted"}]}},{"type":"h","text":"换个角度：平衡力与相互作用力不一样"},{"type":"p","text":"把一本书放在水平桌面上，可以找出两对力：书受到的重力 G 与桌面对书的支持力 N，这一对都作用在书上，是平衡力；桌面对书的支持力 N 与书对桌面的压力 F压，这一对分别作用在书和桌面上，是相互作用力。判断口诀只有一句：看这两个力是否作用在同一个物体上——同物是平衡力，异体是相互作用力。"},{"type":"figure","figure":{"id":"fig-mech-balance-3","title":"平衡力与相互作用力","caption":"同一对力，作用对象不同，性质就不同","view":"wide","alt":"水平桌面上放着一本书，书上画出重力向下和支持力向上，桌面接触处画出书对桌面的压力向下","prims":[{"t":"line","x1":16,"y1":34,"x2":84,"y2":34,"width":0.8},{"t":"hatch","x":16,"y":34,"w":68,"h":4.5,"gap":2.2},{"t":"rect","x":34,"y":20,"w":32,"h":14,"fill":true,"tone":"main","label":"书"},{"t":"circle","cx":50,"cy":27,"r":1.4,"fill":true,"tone":"danger"},{"t":"arrow","x1":50,"y1":27,"x2":50,"y2":44,"tone":"accent","label":"G","labelDx":5},{"t":"arrow","x1":50,"y1":27,"x2":50,"y2":12,"tone":"ok","label":"N","labelDx":5},{"t":"arrow","x1":66,"y1":34,"x2":66,"y2":50,"tone":"danger","label":"F压","labelDx":7},{"t":"text","x":50,"y":55,"text":"G 与 N 都作用在书上 → 一对平衡力","size":3.4,"tone":"ok"},{"t":"text","x":50,"y":60,"text":"N 与 F压 作用在两个物体上 → 相互作用力","size":3.4,"tone":"danger"}]}},{"type":"note","title":"","text":"相互作用力一定大小相等、方向相反，与平衡力的区别只在「是否作用在同一物体上」和「是否同时消失」。"},{"type":"h","text":"建立关系：摩擦力的大小由什么决定"},{"type":"p","text":"用弹簧测力计沿水平方向匀速拉动木块，木块做匀速直线运动，拉力与滑动摩擦力是一对平衡力，所以弹簧测力计的示数就等于摩擦力的大小——这是「转换法」。实验表明：压力越大、接触面越粗糙，滑动摩擦力越大；而接触面积的大小、拉动速度的快慢，都不影响滑动摩擦力。"},{"type":"figure","figure":{"id":"fig-mech-balance-4","title":"用弹簧测力计测滑动摩擦力","caption":"匀速拉动时，测力计的示数等于滑动摩擦力","view":"wide","alt":"水平面上一个木块被弹簧测力计沿水平方向匀速拉动，木块下方画出向左的摩擦力箭头，弹簧测力计示数等于摩擦力","prims":[{"t":"line","x1":6,"y1":40,"x2":94,"y2":40,"width":0.8},{"t":"hatch","x":6,"y":40,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":30,"y":26,"w":26,"h":14,"fill":true,"tone":"main","label":"木块"},{"t":"line","x1":56,"y1":33,"x2":66,"y2":33,"width":0.6},{"t":"rect","x":66,"y":25,"w":20,"h":16,"tone":"main","label":"测力计"},{"t":"arrow","x1":60,"y1":33,"x2":66,"y2":33,"tone":"accent"},{"t":"arrow","x1":30,"y1":38,"x2":12,"y2":38,"tone":"danger","label":"f"},{"t":"text","x":76,"y":19,"text":"读数 = 摩擦力","size":3.4,"tone":"ok"},{"t":"text","x":50,"y":52,"text":"匀速直线运动 → 拉力与滑动摩擦力大小相等","size":3.4,"tone":"ok"},{"t":"text","x":50,"y":58,"text":"木块上加砝码 → 压力变大 → 摩擦力变大","size":3.4,"tone":"muted"}]}},{"type":"h","text":"换个情境：增大摩擦与减小摩擦"},{"type":"p","text":"需要摩擦的地方就设法增大它：鞋底和轮胎刻花纹（增大接触面粗糙程度）、用力捏闸或握紧瓶盖（增大压力）、运动员手上涂镁粉。不需要摩擦的地方就设法减小它：用滚动代替滑动、加润滑油、用气垫或磁悬浮使接触面分开。判断的关键是先想清楚「这里需不需要摩擦」，再去选办法。"},{"type":"figure","figure":{"id":"fig-mech-balance-5","title":"增大摩擦与减小摩擦","caption":"左边靠增大粗糙程度，右边靠把滑动变成滚动","view":"wide","alt":"左边是一个带斜线花纹的鞋底示意表示增大摩擦，右边是上下两块板之间夹着三个滚珠表示用滚动代替滑动来减小摩擦","prims":[{"t":"text","x":26,"y":10,"text":"增大摩擦","size":3.6,"tone":"danger"},{"t":"rect","x":10,"y":16,"w":32,"h":26,"fill":true,"tone":"main"},{"t":"hatch","x":10,"y":16,"w":32,"h":26,"gap":3},{"t":"text","x":26,"y":50,"text":"鞋底刻花纹","size":3.4,"tone":"danger"},{"t":"text","x":74,"y":10,"text":"减小摩擦","size":3.6,"tone":"ok"},{"t":"rect","x":58,"y":16,"w":32,"h":8,"tone":"main"},{"t":"rect","x":58,"y":34,"w":32,"h":8,"tone":"main"},{"t":"circle","cx":66,"cy":29,"r":3.5,"tone":"accent"},{"t":"circle","cx":74,"cy":29,"r":3.5,"tone":"accent"},{"t":"circle","cx":82,"cy":29,"r":3.5,"tone":"accent"},{"t":"text","x":74,"y":50,"text":"滚动代替滑动","size":3.4,"tone":"ok"},{"t":"text","x":50,"y":58,"text":"先判断这里需不需要摩擦，再选增大还是减小","size":3.6,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["二力平衡的条件","F₁ = F₂","F：牛顿（N） · 只适用于同一个物体受到的两个力，并且还要满足「方向相反、作用在同一直线上」；公式 F₁=F₂ 只是四个条件中的一个，不能只凭大小相等就判定为平衡力。"],["滑动摩擦力的测量（转换法）","f = F_(拉)","f：牛顿（N）；F拉：弹簧测力计的示数，牛顿（N） · 只在「用弹簧测力计沿水平方向匀速拉动」时成立：此时摩擦力与拉力是一对平衡力。若物体加速或减速运动，示数就不再等于摩擦力。"],["滑动摩擦力的大小","滑动摩擦力的大小由压力大小和接触面的粗糙程度决定：压力越大、接触面越粗糙，滑动摩擦力越大。","与接触面积的大小、运动速度的快慢无关，也与拉力大小无关（拉力增大摩擦力不变，只是合力变了）。静摩擦力的大小则由使物体产生相对运动趋势的力决定，随它变化，最大不超过刚被推动时的值。"]]},{"type":"h","text":"应用 · 应用一：拉力变大以后，摩擦力变不变"},{"type":"note","title":"情境","text":"一个木块放在水平桌面上，用 15 N 的水平拉力拉它，木块做匀速直线运动；把拉力增大到 20 N，木块加速运动。求两种情况中木块受到的滑动摩擦力的大小。"},{"type":"note","title":"模型与思路","text":"匀速直线运动时拉力与滑动摩擦力是平衡力，可直接求出摩擦力。滑动摩擦力的大小只由压力大小与接触面粗糙程度决定：拉力增大并不改变这两个因素，所以摩擦力保持不变，此时水平方向不再平衡，木块加速运动。"},{"type":"list","title":"解答步骤","items":["匀速运动时：木块水平方向受平衡力，f=F₁=15\\ N","拉力增大到 20 N 后，木块仍在同一桌面上滑动，压力大小与接触面粗糙程度都没变","因此滑动摩擦力仍是 f=15\\ N","此时水平方向合力 F_(合)=20\\ N-15\\ N=5\\ N，方向与拉力相同，所以木块做加速运动"]},{"type":"figure","figure":{"id":"fig-mech-balance-6","title":"拉力大于摩擦力时木块加速","caption":"摩擦力仍是 15 N，但拉力增到 20 N，两力不再平衡","view":"wide","alt":"水平桌面上的木块，向右的拉力箭头比向左的摩擦力箭头长，拉力是 20 牛，摩擦力是 15 牛","prims":[{"t":"line","x1":6,"y1":42,"x2":94,"y2":42,"width":0.8},{"t":"hatch","x":6,"y":42,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":34,"y":24,"w":28,"h":18,"fill":true,"tone":"main","label":"木块"},{"t":"arrow","x1":62,"y1":33,"x2":90,"y2":33,"tone":"accent","label":"F = 20 N","labelDy":-4},{"t":"arrow","x1":34,"y1":39,"x2":12,"y2":39,"tone":"danger","label":"f = 15 N","labelDy":6},{"t":"text","x":50,"y":56,"text":"两个力不平衡，木块的速度不断变大","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"两种情况中滑动摩擦力都是 15 N；拉力增大不会使摩擦力变大，只会使合力变为 5 N，从而改变木块的运动状态。"},{"type":"h","text":"应用 · 应用二：自行车刹车的两个动作"},{"type":"note","title":"情境","text":"骑自行车下坡时，用力捏闸能迅速减速；如果轮胎花纹已经磨平，捏闸的效果会明显变差。这是为什么？"},{"type":"note","title":"模型与思路","text":"刹车靠的是闸皮与车轮（或车轮与地面）之间的摩擦力。用力捏闸增大了压力，花纹则提供粗糙的接触面，两者都使摩擦力变大，从而更快改变运动状态。"},{"type":"list","title":"解答步骤","items":["刹车时闸皮压紧车轮，压力越大、摩擦力越大，车轮更快停止转动","轮胎花纹使接触面更粗糙，同样条件下摩擦力更大，这就是花纹的作用","花纹磨平后接触面变光滑，摩擦力变小，同样用力捏闸也刹不住","结论：增大摩擦有两条途径——增大压力、增大接触面的粗糙程度，刹车恰好把两条都用上了"]},{"type":"note","title":"结论","text":"用力捏闸是「增大压力」，轮胎花纹是「增大粗糙程度」；花纹磨平相当于粗糙程度变小，摩擦力随之变小，所以要按时更换轮胎。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为「推箱子没推动，是因为推力小于摩擦力」。","推不动时箱子静止，推力与静摩擦力是一对平衡力，两者大小相等；推力增大，静摩擦力也随之增大。","如果摩擦力大于推力，箱子受到的合力方向就与推力相反，箱子会向后运动，这与观察到的事实矛盾。静摩擦力的大小「要多少给多少」，直到达到最大值。"],["认为「摩擦力的方向一定与物体运动方向相反」，或认为「传送带上的物体受到的摩擦力一定是阻力」。","摩擦力的方向与相对运动（或相对运动趋势）方向相反，不一定与物体的运动方向相反。","把物体轻轻放在水平传送带上，物体相对传送带向后滑动，受到的摩擦力方向向前，正是这个摩擦力让物体加速到与传送带同速——摩擦力在这里是动力。"],["认为「滑动摩擦力与接触面积有关」「速度越大滑动摩擦力越大」。","滑动摩擦力只与压力大小和接触面粗糙程度有关，与接触面积、速度都无关。","这是实验中可以检验的：把木块侧放（面积变小）匀速拉动，弹簧测力计的示数不变；用不同速度匀速拉动，示数也不变。"]]},{"type":"table","title":"平衡力与相互作用力（都「大小相等、方向相反」，区别只在作用对象）","head":["比较项","一对平衡力","一对相互作用力"],"rows":[["作用对象","作用在同一个物体上","分别作用在两个不同的物体上"],["力的性质","可以是不同性质的力（如重力与支持力）","一定是同种性质的力（如压力与支持力都是弹力）"],["是否同时存在","去掉其中一个，另一个可能仍然存在","同时产生、同时消失，缺一不可"],["运动效果","物体保持静止或匀速直线运动","两个物体各自的运动状态都可能改变"],["典型例子","书受到的重力与桌面对书的支持力","书对桌面的压力与桌面对书的支持力"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["探究滑动摩擦力的大小与什么有关","考查「匀速拉动」的理由、控制变量（同一个木块改变压力、同一压力改变接触面）、读数方法，以及由数据得出结论；也常追问「为什么不能用手拉木块快速移动」。"],["二力平衡条件与平衡力判断","给出物体受力的示意图或情境，判断哪两个力是一对平衡力、哪一对是相互作用力，或反过来要求补画另一个力使物体平衡，落点是「同物、等大、反向、共线」。"],["摩擦力的大小与方向判断","以传送带、斜面上静止的物体、匀速运动的物体为情境，判断摩擦力方向；或要求区分「拉力变化」与「摩擦力变化」，考查滑动摩擦力只由压力和粗糙程度决定。"],["增大与减小摩擦的方法","结合自行车、鞋底、瓶盖、轴承、磁悬浮列车等生活情景选择合适的方法，并要求说明「是通过增大压力还是增大粗糙程度」。"]]},{"type":"quote","text":"【材料一】某小组探究滑动摩擦力的大小与哪些因素有关。他们用弹簧测力计沿水平方向匀速拉动木块，记录如下：木块单独放在木板上，示数为 1.2 N；木块上加一个砝码，示数为 1.8 N；再加一个砝码，示数为 2.4 N；把木块单独放在毛巾上，示数为 2.0 N。\n【材料二】自行车刹车时用力捏闸；轮胎上有凹凸的花纹；雨天路面湿滑，骑车人往往要提前刹车。\n【材料三】把木块侧放（接触面积变小）在同一木板上匀速拉动，弹簧测力计的示数不变。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）分析材料一的数据，说明滑动摩擦力的大小与压力大小、接触面粗糙程度各有什么关系。（6 分）","【设问】（2）实验中为什么要用弹簧测力计沿水平方向匀速拉动木块？（4 分）","【设问】（3）结合材料二、三说明：用力捏闸、轮胎花纹各是通过什么方式改变摩擦力的？雨天为什么要提前刹车？（4 分）"]}],"questions":[{"id":"phy-mech-5-q1","type":"choice","stem":"一本书静止在水平桌面上，下列各对力中属于一对平衡力的是","answer":"A","explain":"书受到的重力与桌面对书的支持力都作用在书上，大小相等、方向相反、在同一直线上，是一对平衡力，A 正确。B 中两个力分别作用在桌面和书上，是一对相互作用力。C 中两个力都竖直向下，且作用在两个不同的物体上，既不是平衡力也不是相互作用力。D 中桌子还压着书，地面对桌子的支持力大于桌子自身的重力，两力大小不相等，不是平衡力。","options":["书受到的重力与桌面对书的支持力","书对桌面的压力与桌面对书的支持力","书受到的重力与书对桌面的压力","桌子受到的重力与地面对桌子的支持力"],"difficulty":2,"tags":["二力平衡","平衡力判断"]},{"id":"phy-mech-5-q2","type":"choice","stem":"跳伞运动员和降落伞在空中沿竖直方向匀速直线下降时，他们受到的","answer":"B","explain":"匀速直线下降是平衡状态，运动员和伞在竖直方向只受重力和空气阻力，两者必须大小相等、方向相反、作用在同一直线上，B 正确。若重力大于阻力，合力向下，他们会加速下降（这正是刚打开伞之前的阶段）；若阻力大于重力，合力向上，他们会减速；D 的错误在于把「有重力」与「合力向下」混为一谈——处于平衡状态时合力为零。","options":["重力大于空气阻力","重力等于空气阻力","重力小于空气阻力","重力和空气阻力的合力方向向下"],"difficulty":2,"tags":["二力平衡","平衡状态"]},{"id":"phy-mech-5-q3","type":"choice","stem":"如下图，木块在 5 N 的水平拉力作用下沿水平地面向右做匀速直线运动，则木块受到的摩擦力","answer":"C","explain":"木块做匀速直线运动，处于平衡状态，水平方向只受拉力和摩擦力两个力，它们必须大小相等、方向相反，所以摩擦力等于 5 N，方向与拉力相反即水平向左，C 正确。A 错：摩擦力大于拉力，合力就向左，木块会减速，不可能匀速。B 错：摩擦力方向与相对运动方向相反，木块向右运动，摩擦力必须向左。D 错：摩擦力小于拉力，合力向右，木块会加速。","options":["大于 5 N，方向向右","等于 5 N，方向向右","等于 5 N，方向向左","小于 5 N，方向向左"],"difficulty":2,"tags":["二力平衡","摩擦力方向"],"figure":{"id":"fig-mech-balance-q3","title":"水平拉力作用下的木块","caption":"木块向右做匀速直线运动，拉力为 5 N","view":"wide","alt":"水平地面上一个木块，右侧有一个向右的 5 牛拉力箭头，上方标明木块向右做匀速直线运动","prims":[{"t":"line","x1":8,"y1":42,"x2":94,"y2":42,"width":0.8},{"t":"hatch","x":8,"y":42,"w":86,"h":4.5,"gap":2.2},{"t":"rect","x":32,"y":24,"w":26,"h":18,"fill":true,"tone":"main","label":"木块"},{"t":"arrow","x1":58,"y1":33,"x2":84,"y2":33,"tone":"accent","label":"F = 5 N","labelDy":-4},{"t":"text","x":50,"y":14,"text":"匀速直线运动，方向向右","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"问：木块受到的摩擦力有多大、方向如何","size":3.6,"tone":"muted"}]}},{"id":"phy-mech-5-q4","type":"choice","stem":"下列做法中，属于减小摩擦的是","answer":"D","explain":"加润滑油使接触面之间形成油膜，摩擦显著减小，D 正确。A 是通过增大接触面的粗糙程度来增大摩擦，防止走路打滑。B 是通过增大闸皮对车轮的压力来增大摩擦，使车更快停下。C 是增大接触面的粗糙程度（并吸汗保持干燥）来增大摩擦，防止手滑脱。判断时先想清楚「这里需不需要摩擦」，再做选择。","options":["鞋底上刻有凹凸的花纹","骑自行车下坡时用力捏闸","体操运动员上器械前在手上涂镁粉","给自行车的车轴加润滑油"],"difficulty":1,"tags":["增大与减小摩擦"]},{"id":"phy-mech-5-q5","type":"fill","stem":"用弹簧测力计沿水平方向匀速拉动放在水平桌面上的木块，弹簧测力计的示数是 3.6 N，木块受到的滑动摩擦力是＿＿N。","answer":"3.6|3.60","explain":"匀速拉动时木块处于平衡状态，水平方向拉力与滑动摩擦力是一对平衡力，大小相等，所以摩擦力等于弹簧测力计的示数 3.6 N。这是「转换法」：把看不见的摩擦力转换成可以直接读出的拉力。若答 0，是误以为匀速运动说明不受力；若答 7.2 N，是把两个力相加了。","difficulty":1,"tags":["摩擦力测量","二力平衡"]},{"id":"phy-mech-5-q6","type":"fill","stem":"一本书静止在水平桌面上，书受到的重力与桌面对书的支持力是一对＿＿。","answer":"平衡力","explain":"这两个力都作用在书上，大小相等、方向相反、作用在同一直线上，符合二力平衡的四个条件，所以是一对平衡力。若填「相互作用力」就错了：相互作用力必须作用在两个不同的物体上，比如书对桌面的压力与桌面对书的支持力。判断的关键永远是有没有作用在同一个物体上。","difficulty":1,"tags":["平衡力与相互作用力"]},{"id":"phy-mech-5-q7","type":"short","stem":"一个木块放在水平桌面上，用 15 N 的水平拉力可以使它做匀速直线运动。若把水平拉力增大到 20 N，木块仍在同一桌面上滑动。求拉力为 15 N 和 20 N 时木块受到的滑动摩擦力的大小，并说明木块的运动状态会怎样变化。","answer":"拉力为 15 N 时木块做匀速直线运动，处于平衡状态，滑动摩擦力与拉力大小相等：$f=15\\ \\mathrm{N}$，方向与拉力相反。拉力增大到 20 N 后，木块仍在同一桌面上滑动，压力大小和接触面的粗糙程度都没有改变，所以滑动摩擦力仍然是 15 N。此时水平方向合力 $F_{合}=20\\ \\mathrm{N}-15\\ \\mathrm{N}=5\\ \\mathrm{N}$，方向与拉力相同，木块的速度不断变大，做加速运动。","explain":"这道题的问法是「换一个条件再想一遍」的典型：拉力变了，摩擦力变不变？答案是不变，因为决定摩擦力的是压力和粗糙程度，拉力不在其中。很多同学把「拉力越大摩擦力越大」当成规律，结果算出 f=20 N、合力为零，就等于说「用更大力拉，木块反而还匀速」——这与实验事实矛盾。","difficulty":3,"tags":["解答与计算","滑动摩擦力"],"rubric":["由匀速运动与二力平衡求出摩擦力 15 N","说明滑动摩擦力只由压力大小与粗糙程度决定（此处二者不变）","明确拉力增大后摩擦力仍是 15 N","算出合力 5 N 并说明木块做加速运动"],"steps":["先分析匀速运动的过程：由二力平衡得 f = F = 15 N。","说明影响滑动摩擦力的因素：只有压力大小与接触面粗糙程度，两者都没有变。","得出拉力增大后摩擦力仍为 15 N（不是 20 N）。","求合力：F_(合)=20\\ N-15\\ N=5\\ N，方向与拉力相同。","作答：两种情况下摩擦力都是 15 N；木块由匀速变为加速运动。"]},{"id":"phy-mech-5-q8","type":"short","stem":"某小组要探究「滑动摩擦力的大小与压力大小的关系」，器材有弹簧测力计、木块、砝码若干、长木板。请写出实验步骤与需要控制的变量，并说明怎样由数据得出结论。","answer":"步骤：① 把长木板放在水平桌面上，把木块放在木板上，用弹簧测力计沿水平方向匀速拉动木块，读出并记录弹簧测力计的示数 F₁，即摩擦力 f₁；② 在木块上放一个砝码，重复上述操作，记录示数 f₂；③ 再增加砝码个数，重复实验，记录 f₃；④ 比较 f₁、f₂、f₃ 与对应压力的大小关系，得出结论。需要控制的变量：接触面的粗糙程度（都用同一块木板、同一个木块）、接触面积、拉动方式（都水平匀速拉动）。结论：接触面粗糙程度相同时，压力越大，滑动摩擦力越大。","explain":"这道实验题的三条踩分点是：匀速拉、只改一个变量、多次测量。其中「匀速」是原理上的要求（保证二力平衡，示数等于摩擦力），「只改压力」是控制变量法的要求。若用弹簧测力计斜着拉，或拉动时快时慢，测出的示数都不等于摩擦力，实验就失去意义。","difficulty":2,"tags":["实验探究","控制变量","摩擦力"],"rubric":["器材与操作：弹簧测力计沿水平方向匀速拉动木块","明确读出弹簧测力计的示数即为摩擦力（转换法）","只改变压力（加减砝码），控制接触面粗糙程度与接触面积不变","记录多组数据并比较，得出「粗糙程度相同时压力越大摩擦力越大」"]},{"id":"phy-mech-5-q9","type":"short","stem":"一个木块静止在粗糙的斜面上，请在下图中画出木块所受力的示意图。","answer":"木块受到三个力：重力 G，从重心竖直向下；支持力 N，从重心垂直于斜面向外；静摩擦力 f，沿斜面向上（因为木块有沿斜面下滑的趋势，静摩擦力阻碍这个趋势）。","explain":"斜面上静止的木块是最考验受力分析的一道题。判断静摩擦力方向要看「相对运动趋势」：木块有沿斜面下滑的趋势，所以静摩擦力沿斜面向上。支持力的方向垂直于接触面（斜面），重力始终竖直向下。三个力中重力与另外两个力的合力平衡，木块才保持静止。常见错误是把重力画成垂直于斜面，或漏掉静摩擦力。","difficulty":3,"tags":["作图题","受力分析","静摩擦力"],"rubric":["三个力的作用点都画在重心上","重力 G 竖直向下（不是垂直斜面向下）","支持力 N 垂直于斜面向上","静摩擦力 f 沿斜面向上（与下滑趋势方向相反），并标注字母"],"figure":{"id":"fig-mech-balance-q9-blank","title":"静止在斜面上的木块","caption":"木块静止，说明它受到的力互相平衡","view":"wide","alt":"一个斜面上放着一块静止的木块，需要画出木块受到的所有力","prims":[{"t":"line","x1":14,"y1":44,"x2":96,"y2":44,"width":0.8},{"t":"hatch","x":14,"y":44,"w":82,"h":4.5,"gap":2.2},{"t":"incline","x":30,"y":44,"w":50,"deg":25},{"t":"poly","points":[[57.05,22.59],[60.43,29.83],[49.55,34.91],[46.17,27.67]],"closed":true,"fill":true,"tone":"accent"}]},"answerFigure":{"id":"fig-mech-balance-q9-ans","title":"斜面上木块的受力示意图（标准作图）","caption":"重力竖直向下、支持力垂直斜面、静摩擦力沿斜面向上","view":"wide","alt":"斜面上的木块重心处画出三个箭头：重力竖直向下，支持力垂直于斜面向上，静摩擦力沿斜面向上","prims":[{"t":"line","x1":14,"y1":44,"x2":96,"y2":44,"width":0.8},{"t":"hatch","x":14,"y":44,"w":82,"h":4.5,"gap":2.2},{"t":"incline","x":30,"y":44,"w":50,"deg":25},{"t":"poly","points":[[57.05,22.59],[60.43,29.83],[49.55,34.91],[46.17,27.67]],"closed":true,"fill":true,"tone":"accent"},{"t":"circle","cx":53.3,"cy":28.75,"r":1.5,"fill":true,"tone":"danger"},{"t":"arrow","x1":53.3,"y1":28.75,"x2":53.3,"y2":42,"tone":"main","label":"G","labelDx":5},{"t":"arrow","x1":53.3,"y1":28.75,"x2":48.9,"y2":19.3,"tone":"ok","label":"N","labelDx":-4.5},{"t":"arrow","x1":53.3,"y1":28.75,"x2":42.5,"y2":33.8,"tone":"danger","label":"f","labelDy":4},{"t":"text","x":76,"y":38,"text":"N 垂直于斜面","size":3.2,"tone":"ok"},{"t":"text","x":44,"y":56,"text":"G 竖直向下，f 沿斜面向上","size":3.6,"tone":"muted"}]}},{"id":"phy-mech-5-m1-q1","type":"short","stem":"（1）分析材料一的数据，说明滑动摩擦力的大小与压力大小、接触面粗糙程度各有什么关系。（6 分）","answer":"比较木块单独放、加一个砝码、加两个砝码三次实验：接触面都是木板（粗糙程度相同），压力依次增大，示数由 1.2 N 增大到 1.8 N、2.4 N，说明接触面粗糙程度相同时，压力越大，滑动摩擦力越大。比较木块单独放在木板上与单独放在毛巾上的两次实验：压力相同（都是木块的重力），毛巾表面更粗糙，示数由 1.2 N 增大到 2.0 N，说明压力相同时，接触面越粗糙，滑动摩擦力越大。","explain":"","tags":["实验探究","控制变量"],"rubric":["指出比较「同一接触面、改变压力」的三组数据","得出「粗糙程度相同时，压力越大摩擦力越大」","指出比较「同一压力、改变接触面」的两组数据","得出「压力相同时，接触面越粗糙摩擦力越大」","体现控制变量的思想（每次只改变一个因素）"]},{"id":"phy-mech-5-m1-q2","type":"short","stem":"（2）实验中为什么要用弹簧测力计沿水平方向匀速拉动木块？（4 分）","answer":"匀速拉动时，木块做匀速直线运动，处于平衡状态，水平方向上拉力与滑动摩擦力是一对平衡力，大小相等，所以弹簧测力计的示数就等于滑动摩擦力的大小。如果加速或减速拉动，拉力与摩擦力不再平衡，示数就不等于摩擦力，测量结果不准确。","explain":"","tags":["实验原理","二力平衡"],"rubric":["答出匀速拉动时木块处于平衡状态","答出拉力与滑动摩擦力是一对平衡力、大小相等","说明示数等于摩擦力（转换法）","指出非匀速拉动时示数不等于摩擦力"]},{"id":"phy-mech-5-m1-q3","type":"short","stem":"（3）结合材料二、三说明：用力捏闸、轮胎花纹各是通过什么方式改变摩擦力的？雨天为什么要提前刹车？（4 分）","answer":"用力捏闸是通过增大闸皮对车轮的压力来增大摩擦，使车轮更快停止转动；轮胎花纹是通过使接触面更粗糙来增大摩擦，防止车轮打滑。雨天路面湿滑，轮胎与地面之间的接触面变光滑，摩擦力变小，刹车后自行车需要更长的距离才能停下，所以要提前刹车。材料三还说明摩擦力与接触面积无关，所以靠加宽轮胎是没用的。","explain":"","tags":["生活应用","说理"],"rubric":["答出用力捏闸是增大压力","答出轮胎花纹是增大接触面的粗糙程度","答出雨天路面变滑、摩擦力变小、刹车距离变长","结论落在「提前刹车（减速、加大距离）」上"]}]},{"id":"phy-mech-6","title":"压强","subtitle":"人教版八下 · 第 9 章 压强 · 8b","grade":"8b","tags":["人教版八下 · 第 9 章 压强"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八下 · 第 9 章 压强 · 8b"},{"type":"note","title":"问题切入","text":"同样用一根手指按气球，用指腹和用针尖的效果为什么完全不同？为什么深海潜水员必须穿抗压服，而高原上煮饭又总是煮不熟？"},{"type":"note","title":"一句话抓住关键","text":"压力的作用效果由压力大小与受力面积共同决定，用压强 $p=\\frac{F}{S}$ 来量化。液体压强只由液体密度与深度决定：$p=\\rho gh$；大气压随高度增大而减小；流体中流速越大的位置压强越小。"},{"type":"h","text":"先看现象：同样的力，效果差很多"},{"type":"p","text":"用同样的力把手指按在同一种泡沫上：用指腹按，泡沫只是浅浅凹下去；用针尖按，会扎出一个深坑。力的大小一样，差别只在受力面积。可见描述压力的作用效果，不能只看压力的大小，还要看这些压力分布在多大的面积上。"},{"type":"figure","figure":{"id":"fig-mech-pressure-1","title":"压力相同，受力面积不同","caption":"受力面积越小，压力的作用效果越明显","view":"wide","alt":"左右对比：左边用较大的手掌压在泡沫上只留下浅坑，右边用很细的针尖压同样的泡沫，扎出很深的坑","prims":[{"t":"arrow","x1":26,"y1":6,"x2":26,"y2":17,"tone":"accent","label":"F","labelDx":-4},{"t":"rect","x":12,"y":18,"w":28,"h":6,"fill":true,"tone":"main"},{"t":"rect","x":10,"y":24,"w":32,"h":10,"tone":"muted"},{"t":"text","x":26,"y":41,"text":"受力面积大：下陷浅","size":3.4,"tone":"muted"},{"t":"arrow","x1":75,"y1":6,"x2":75,"y2":17,"tone":"accent","label":"F","labelDx":4},{"t":"poly","points":[[71,17],[79,17],[75,25]],"closed":true,"fill":true,"tone":"accent"},{"t":"rect","x":59,"y":24,"w":32,"h":10,"tone":"muted"},{"t":"text","x":75,"y":41,"text":"受力面积小：下陷深","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":52,"text":"压力相同时，受力面积越小，压力的作用效果越明显","size":3.6,"tone":"ok"}]}},{"type":"note","title":"","text":"「压力的作用效果」是压强的定义角度：效果越明显，压强越大。"},{"type":"h","text":"抓住哪个量：压力除以受力面积"},{"type":"p","text":"把「作用效果」变成可计算的量：物体单位面积上受到的压力叫压强，p=(F)/(S)，单位是帕斯卡（Pa），1 Pa = 1 N/m²。这里的 F 是垂直压在物体表面上的力，S 是两物体实际接触部分的面积。同一块砖平放和侧放，对地面的压力相同，但侧放时接触面积小，压强就大。"},{"type":"figure","figure":{"id":"fig-mech-pressure-2","title":"同一块砖，平放与侧放","caption":"压力不变，受力面积越小压强越大","view":"wide","alt":"同一块砖两次放在地面上，左边平放时与地面的接触面积大，右边侧放时接触面积小，接触部分用粗线标出","prims":[{"t":"line","x1":6,"y1":42,"x2":94,"y2":42,"width":0.8},{"t":"hatch","x":6,"y":42,"w":88,"h":4.5,"gap":2.2},{"t":"rect","x":14,"y":26,"w":32,"h":16,"fill":true,"tone":"main"},{"t":"line","x1":14,"y1":42,"x2":46,"y2":42,"width":1.8,"tone":"accent"},{"t":"rect","x":64,"y":18,"w":12,"h":24,"fill":true,"tone":"main"},{"t":"line","x1":64,"y1":42,"x2":76,"y2":42,"width":1.8,"tone":"danger"},{"t":"text","x":30,"y":52,"text":"平放：S 大","size":3.6,"tone":"accent"},{"t":"text","x":70,"y":52,"text":"侧放：S 小","size":3.6,"tone":"danger"},{"t":"text","x":50,"y":60,"text":"p = F / S：压力相同时，受力面积越小压强越大","size":3.6,"tone":"ok"}]}},{"type":"h","text":"换个情境：需要什么就往哪边调"},{"type":"p","text":"压强是可以按要求调大调小的。想让压强小一些，就增大受力面积：书包用宽背带、坦克装履带、铁轨铺在枕木上、滑雪板又宽又长。想让压强大一些，就减小受力面积：刀刃磨薄、针尖做细、图钉尖很尖、啄木鸟的喙又细又硬。"},{"type":"figure","figure":{"id":"fig-mech-pressure-3","title":"增大压强与减小压强","caption":"左边靠减小受力面积，右边靠增大受力面积","view":"wide","alt":"左边是一把刀刃朝下的刀把物体切开，刀刃与物体接触面积很小；右边是一根宽的书包带压在肩上，接触面积较大","prims":[{"t":"arrow","x1":24,"y1":8,"x2":24,"y2":17,"tone":"danger","label":"F","labelDx":-4},{"t":"poly","points":[[12,18],[36,18],[24,30]],"closed":true,"fill":true,"tone":"danger"},{"t":"rect","x":10,"y":30,"w":32,"h":8,"tone":"main"},{"t":"text","x":24,"y":48,"text":"刀刃磨薄：压强大","size":3.4,"tone":"danger"},{"t":"poly","points":[[62,26],[80,18],[92,30],[74,38]],"closed":true,"fill":true,"tone":"muted"},{"t":"rect","x":60,"y":30,"w":32,"h":7,"fill":true,"tone":"accent"},{"t":"text","x":76,"y":48,"text":"书包宽带：压强小","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":57,"text":"增大压强：减小受力面积；减小压强：增大受力面积","size":3.6,"tone":"ok"}]}},{"type":"h","text":"建立关系：液体压强只看密度和深度"},{"type":"p","text":"把压强计的探头放进水中，越深，U 形管两边的液面高度差越大；换用盐水（密度更大），同一深度处的压强也更大。实验表明：液体内部的压强只由液体密度和深度决定，p=ρ gh，与液体的多少、容器的形状都无关。这里的 h 是深度——从自由液面竖直向下量到该点的距离，不是容器的高度，也不是该点到容器底的距离。"},{"type":"figure","figure":{"id":"fig-mech-pressure-4","title":"液体压强与深度","caption":"深度 h 从自由液面竖直向下量","view":"wide","alt":"一个装水的水槽中放有压强计的探头，旁边用双向箭头标出从液面到探头的竖直深度 h","prims":[{"t":"beaker","x":14,"y":16,"w":30,"h":28,"fill":0.85},{"t":"line","x1":14,"y1":20.2,"x2":44,"y2":20.2,"width":0.6,"tone":"accent"},{"t":"circle","cx":29,"cy":37,"r":2.2,"fill":true,"tone":"main"},{"t":"line","x1":50,"y1":20.2,"x2":50,"y2":37,"dashed":true,"tone":"muted"},{"t":"arrow","x1":50,"y1":20.2,"x2":50,"y2":37,"both":true,"tone":"muted","label":"h","labelDx":5},{"t":"text","x":29,"y":50,"text":"压强计探头","size":3.4,"tone":"main"},{"t":"text","x":50,"y":58,"text":"h 是从自由液面竖直向下的深度，不是容器高度","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"同一深度处，液体向各个方向的压强都相等——这一点用压强计转动探头方向即可验证。"},{"type":"h","text":"换个情境：大气压与流体压强"},{"type":"p","text":"大气也有压强：托里拆利实验用水银柱测出大气压相当于 760 mm 高水银柱产生的压强，约为 1.0×10⁵ Pa。海拔越高，空气越稀薄，大气压越小。流体（液体和气体）还有一个共同的规律：流速越大的位置压强越小。对着两张竖直的纸中间吹气，两张纸会互相靠拢；列车进站时，站台边缘附近的空气流速大、压强小，人容易被「吸」向列车，所以必须站在安全线以外。"},{"type":"figure","figure":{"id":"fig-mech-pressure-5","title":"托里拆利实验","caption":"大气压支持约 760 mm 高的水银柱","view":"wide","alt":"一根一端封闭的玻璃管倒插在水银槽中，管内水银面比槽内水银面高出约七百六十毫米，管顶是真空","prims":[{"t":"beaker","x":26,"y":36,"w":48,"h":12,"fill":0.8},{"t":"line","x1":46,"y1":6,"x2":46,"y2":40,"width":0.5},{"t":"line","x1":54,"y1":6,"x2":54,"y2":40,"width":0.5},{"t":"line","x1":46,"y1":6,"x2":54,"y2":6,"width":0.6},{"t":"rect","x":46.6,"y":12,"w":6.8,"h":26,"fill":true,"tone":"accent"},{"t":"text","x":50,"y":9.4,"text":"真空","size":2.8,"tone":"muted"},{"t":"arrow","x1":66,"y1":12,"x2":66,"y2":38,"both":true,"tone":"muted"},{"t":"text","x":78,"y":25,"text":"760 mm","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":55,"text":"大气压支持约 760 mm 高的水银柱","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":60,"text":"1 标准大气压 ≈ 1.0×10⁵ Pa","size":3.4,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["压强","p = (F)/(S)","p：帕斯卡（Pa）；F：牛顿（N）；S：平方米（m²），1 Pa = 1 N/m² · 适用于固体、液体、气体的压强计算。F 是垂直压在物体表面上的力，S 是两物体实际接触部分的面积（不是物体的总面积）；变形用法：F=pS（求压力）、S=(F)/(p)（求受力面积）。"],["液体压强","p = ρ g h","p：帕斯卡（Pa）；ρ：千克每立方米（kg/m³）；h：米（m） · 只适用于液体内部压强的计算，以及密度均匀的柱体对水平面的压强。h 是深度：从自由液面竖直向下量到该点的距离，不是容器的高度，也不是到容器底的距离。液体压强与液体的多少、容器的形状无关。"],["大气压的数值","p₀ ≈ 1.0× 10⁵\\ Pa","帕斯卡（Pa）；相当于 760 mm 高水银柱产生的压强 · 用于粗略计算大气压的大小。大气压随海拔升高而减小（海拔 3000 m 附近约为 7×10⁴ Pa），也随天气变化；气压减小时液体的沸点降低，这就是高原上煮不熟饭的原因。"],["流体压强与流速的关系","在液体和气体中，流速越大的位置压强越小。","用来解释机翼升力、站台安全线、两纸片中间吹气后靠拢等现象。注意表述方向：是「流速大 → 压强小」，说反就是错的；这里的「压强小」是相对于同一流体中流速较小的位置而言。"]]},{"type":"h","text":"应用 · 应用一：中学生站立时对地面的压强"},{"type":"note","title":"情境","text":"一名中学生的质量是 60 kg，站立时双脚与地面的总接触面积约为 0.04 m²。求他站立时对地面的压强（g 取 10 N/kg）。"},{"type":"note","title":"模型与思路","text":"人站在水平地面上，竖直方向没有其它力，所以他对地面的压力大小等于自身的重力；受力面积是两只脚与地面的总接触面积。用 p=(F)/(S) 计算，注意单位用 m²。"},{"type":"list","title":"解答步骤","items":["求重力（即压力）：F=G=mg=60\\ kg× 10\\ N/kg=600\\ N","受力面积 S=0.04\\ m²（两只脚的总面积）","代入公式：p=(F)/(S)=600\\ N0.04\\ m²=1.5× 10⁴\\ Pa","检验量级：约 1.5 万帕，相当于在每平方厘米的地面上压着约 1.5 N 的力，与实际感觉相符"]},{"type":"figure","figure":{"id":"fig-mech-pressure-6","title":"站立时受力面积是两只脚的总面积","caption":"抬起一只脚，受力面积减半，压强加倍","view":"wide","alt":"一个人站立在地面上，两只脚与地面接触，下方标出总接触面积，旁边写着压力等于重力","prims":[{"t":"line","x1":6,"y1":44,"x2":94,"y2":44,"width":0.8},{"t":"hatch","x":6,"y":44,"w":88,"h":4.5,"gap":2.2},{"t":"circle","cx":50,"cy":16,"r":3.4,"tone":"main","fill":true},{"t":"line","x1":50,"y1":19.4,"x2":50,"y2":34,"width":1.6},{"t":"poly","points":[[46,34],[54,34],[56,44],[44,44]],"closed":true,"fill":true,"tone":"main"},{"t":"arrow","x1":50,"y1":20,"x2":50,"y2":40,"tone":"accent","label":"G = 600 N","labelDx":22},{"t":"line","x1":44,"y1":44,"x2":56,"y2":44,"width":1.8,"tone":"danger"},{"t":"text","x":74,"y":40,"text":"S = 0.04 m²","size":3.6,"tone":"danger"},{"t":"text","x":50,"y":54,"text":"压力 F = G = 600 N，p = F / S = 1.5×10⁴ Pa","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"中学生站立时对地面的压强约为 1.5×10⁴ Pa。若他抬起一只脚，受力面积减半，压强就变成 3×10⁴ Pa。"},{"type":"h","text":"应用 · 应用二：水深 10 m 处的压强有多大"},{"type":"note","title":"情境","text":"某游泳池最深处水深 10 m，水的密度取 1.0×10³ kg/m³，g 取 10 N/kg。求池底受到水的压强，并与大气压比较。"},{"type":"note","title":"模型与思路","text":"液体压强只由液体密度与深度决定，用 p=ρ gh，其中 h 是从自由液面竖直向下到池底的深度。注意池底受到的压强还要加上大气压，但初中一般只要求计算水产生的压强。"},{"type":"list","title":"解答步骤","items":["取 ρ = 1.0×10³ kg/m³，h = 10 m，g = 10 N/kg","p=ρ gh=1.0× 10³\\ kg/m³× 10\\ N/kg× 10\\ m=1.0× 10⁵\\ Pa","与大气压比较：1 标准大气压约 1.0×10⁵ Pa，所以 10 m 深的水产生的压强大约就是一个大气压","结论：水深每增加 10 m，水产生的压强就增加约 1 个大气压，这就是深海潜水必须穿抗压服的原因"]},{"type":"figure","figure":{"id":"fig-mech-pressure-7","title":"水深与压强","caption":"深度每增加 10 m，水产生的压强就增加约 1 个大气压","view":"wide","alt":"一池水从水面到底部，右侧用双向箭头标出十米的深度，底部标注出压强的大小","prims":[{"t":"rect","x":20,"y":12,"w":60,"h":36,"fill":true,"tone":"accent"},{"t":"line","x1":20,"y1":12,"x2":80,"y2":12,"width":0.7,"tone":"accent"},{"t":"line","x1":20,"y1":48,"x2":80,"y2":48,"width":0.9},{"t":"arrow","x1":88,"y1":12,"x2":88,"y2":48,"both":true,"tone":"muted"},{"t":"text","x":90,"y":30,"text":"h = 10 m","anchor":"start","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":7,"text":"自由液面","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"p = ρgh = 1.0×10³ × 10 × 10 Pa = 1.0×10⁵ Pa","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"池底受到水的压强约为 1.0×10⁵ Pa，相当于 1 个标准大气压。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为「压力一定等于物体的重力」，把 F 直接代成 G，也不管接触面是斜的还是竖直的。","只有当物体放在水平面上、且竖直方向没有其它力时，压力大小才等于重力；把物体按在竖直墙面上时，压力与重力无关。","重力是地球吸引产生的力，作用在物体的重心上、方向竖直向下；压力是物体对支持面的力，作用在接触面上、方向垂直于接触面。两者只有在特定条件下数值才相等。"],["把 $p=\\rho gh$ 用在固体上，或用它算桌面受到一本书的压强。","$p=\\rho gh$ 只适用于液体（以及密度均匀的柱体对水平面）。固体压强要用 $p=\\frac{F}{S}$。","液体压强的公式是由「液柱的重力除以底面积」推出来的，只对液体和柱状固体成立。对一般的固体用错公式，结果会与真实值差很远。"],["把「深度 h」理解成容器的高度或该点到容器底的距离。","h 是从自由液面（液体的上表面）竖直向下量到该点的距离。","同一个容器，侧壁上不同高度的孔喷水的射程不同，说明压强由深度决定；若 h 取容器高度，就会得出「容器底处处压强相同却与水深无关」这种自相矛盾的结论。"],["认为「流速越大的地方压强越大」。","流体中流速越大的位置压强越小：站台边缘空气流速大、压强小，人会被压向列车。","把方向说反，安全线、机翼升力这些现象就全都解释不通。记忆时抓住「快的地方压强小」这一句即可。"]]},{"type":"table","title":"固体压强与液体压强（两套公式，各有各的适用范围）","head":["比较项","固体压强","液体压强"],"rows":[["计算公式","p = F / S","p = ρgh（也可用 p = F / S，但更麻烦）"],["决定因素","压力大小与受力面积","液体密度与深度"],["与受力面积的关系","压力一定时，面积越小压强越大","与容器底面积无关（同一深度处处相等）"],["与深度的关系","没有直接关系","深度越大压强越大，且成正比"],["方向特点","压力的方向垂直于接触面","液体向各个方向都有压强，同一深度各方向相等"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["增大与减小压强的判断","以刀刃、书包带、履带、枕木、图钉等生活情景命题，要求指出是通过改变压力还是改变受力面积来实现的，属于选择题与说理题的高频点。"],["固体的压强计算","以人站立（走路）、行李箱、砖块平放侧放为情境，注意「压力等于重力」的前提、受力面积是接触面积（站立用两只脚、走路用一只脚），以及单位换算（cm² 化成 m²）。"],["探究液体内部压强的特点","用压强计探究压强与深度、方向、液体密度的关系，考查操作（探头朝向、读数看液面高度差）、控制变量与结论表述。"],["大气压与沸点、流体压强与流速","结合托里拆利实验、高原煮饭、高压锅、站台安全线、机翼升力等情境，考查现象解释与影响因素的分析。"]]},{"type":"quote","text":"【材料一】托里拆利实验：在一端封闭、长约 1 m 的玻璃管内装满水银，用手指堵住管口倒插在水银槽里，放开手指后，管内水银面下降到比槽内水银面高约 760 mm 处就不再下降。\n【材料二】海拔越高，大气压越小。海拔 3000 m 左右的大气压约为 7×10⁴ Pa，在那里水的沸点降到 90 ℃ 左右。\n【材料三】高压锅密封性好，加热时锅内气压可升到 2×10⁵ Pa 左右，水的沸点随之升高到 120 ℃ 左右，食物熟得更快。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）依据材料一说明：为什么管内的水银柱下降到约 760 mm 高时就不再下降？如果把玻璃管略微倾斜，水银柱的竖直高度会怎样变化？（4 分）","【设问】（2）已知水银的密度为 13.6×10³ kg/m³，g 取 10 N/kg。计算 760 mm 高的水银柱产生的压强。（4 分）","【设问】（3）依据材料二、三说明：高原上为什么用普通锅煮不熟饭？高压锅又是怎么解决这个问题的？（4 分）"]}],"questions":[{"id":"phy-mech-6-q1","type":"choice","stem":"下列做法中，为了增大压强的是","answer":"A","explain":"刀刃磨薄是在压力不变的情况下减小受力面积，从而增大压强，A 正确。B 是通过增大受力面积来减小压强，避免勒肩。C、D 都是通过增大受力面积来减小压强，防止坦克和铁轨陷入地面。判断时应先明确目的：要「切得进、扎得深」就增大压强，要「压得浅、不陷下去」就减小压强。","options":["把刀刃磨得很薄","书包背带做得较宽","坦克的轮子上装履带","铁轨铺在枕木上"],"difficulty":1,"tags":["增大与减小压强"]},{"id":"phy-mech-6-q2","type":"choice","stem":"关于压力，下列说法正确的是","answer":"B","explain":"把物体按在竖直墙面上时，压力沿水平方向，与重力毫无关系；把物体放在斜面上时，压力小于重力。只有在水平面上且竖直方向没有其它力时，压力大小才等于重力，B 正确。A 说得太绝对。C 错：压力的方向总是垂直于接触面，斜面上就不是竖直向下。D 错：压力作用在接触面上，而重力的作用点才是重心。","options":["压力的大小总是等于物体受到的重力","只有物体放在水平面上且竖直方向没有其它力时，压力的大小才等于重力","压力的方向总是竖直向下","压力的作用点在物体的重心上"],"difficulty":2,"tags":["压力","压力与重力"]},{"id":"phy-mech-6-q3","type":"choice","stem":"下图是某液体内部压强 p 随深度 h 变化的图像，由图可知","answer":"C","explain":"图线是一条过原点的倾斜直线，说明压强与深度成正比，即深度增大到几倍，压强也增大到几倍，C 正确。A 与图线明显矛盾：深度为 0 时压强为 0，深度增大压强随之增大。B 把关系说反了。D 错：由 p=ρ gh 可知压强只由液体密度和深度决定，与液体的多少、容器的形状都无关。","options":["液体压强与深度无关","深度越大，液体压强越小","同种液体中，压强与深度成正比","液体压强只由液体的多少决定"],"difficulty":2,"tags":["p-h 图像","液体压强"],"figure":{"id":"fig-mech-pressure-q3","title":"液体压强与深度的关系","caption":"图线是过原点的倾斜直线","view":"square","alt":"以深度为横轴、压强为纵轴的图像上，有一条从原点出发的倾斜直线，说明压强随深度成正比增大","prims":[{"t":"axis","x":22,"y":84,"w":66,"h":64,"xLabel":"h/m","yLabel":"p/Pa","origin":true,"xTicks":[{"at":0.5,"label":"2"},{"at":1,"label":"4"}],"yTicks":[{"at":0.5,"label":"2×10⁴"},{"at":1,"label":"4×10⁴"}]},{"t":"curve","points":[[22,84],[88,20]],"tone":"accent"},{"t":"text","x":50,"y":10,"text":"同一种液体，密度不变","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-6-q4","type":"choice","stem":"火车站的站台上标有安全线，乘客必须站在安全线以外候车，这是因为列车驶过时","answer":"D","explain":"列车高速驶过时，带动周围空气一起快速流动，站台边缘附近的空气流速变大。由流体压强与流速的关系可知，流速越大的位置压强越小，于是人身体外侧（远离列车一侧）受到的压强较大，会被压向列车，非常危险，所以必须站在安全线以外，D 正确。A、B、C 都把「流速」与「压强」的对应关系搞错了。","options":["列车周围的空气流速大，压强大","列车周围的空气流速小，压强小","列车周围的空气流速小，压强大","列车周围的空气流速大，压强小"],"difficulty":2,"tags":["流体压强与流速"]},{"id":"phy-mech-6-q5","type":"fill","stem":"一名质量是 60 kg 的人站立在水平地面上，双脚与地面的总接触面积是 0.05 m²，他对地面的压强是＿＿Pa。（g 取 10 N/kg）","answer":"12000|12000.0","explain":"人站在水平地面上，压力大小等于重力：F=G=mg=600\\ N；压强 p=(F)/(S)=600\\ N0.05\\ m²=1.2× 10⁴\\ Pa，也就是 12000 Pa。若答 12 Pa，是漏了单位换算（把 0.05 m² 当成 50）；若答 1.2×10⁴ 的数字 1.2，是没有做完除法。","difficulty":2,"tags":["固体压强计算"]},{"id":"phy-mech-6-q6","type":"fill","stem":"某水池中水深 5 m，池底受到水产生的压强是＿＿Pa。（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg）","answer":"50000|50000.0","explain":"由 p=ρ gh=1.0× 10³\\ kg/m³× 10\\ N/kg× 5\\ m=5× 10⁴\\ Pa，即 50000 Pa。这里 h 是水深 5 m，从自由液面竖直向下量到池底。若答 5000 Pa，是把 h 取成了 0.5 m 之类；若答 5×10⁴ 却写成 5，是算到一半就停手了。","difficulty":2,"tags":["液体压强计算"]},{"id":"phy-mech-6-q7","type":"short","stem":"一名中学生的质量是 60 kg，双脚站立时与地面的总接触面积是 300 cm²。求他双脚站立时对地面的压强；如果他抬起一只脚站立，对地面的压强又是多少？（g 取 10 N/kg）","answer":"压力大小等于重力：$F=G=mg=60\\ \\mathrm{kg}\\times 10\\ \\mathrm{N/kg}=600\\ \\mathrm{N}$。双脚站立时 $S_1=300\\ \\mathrm{cm^2}=3\\times 10^{-2}\\ \\mathrm{m^2}$，$p_1=\\frac{F}{S_1}=\\frac{600\\ \\mathrm{N}}{3\\times 10^{-2}\\ \\mathrm{m^2}}=2\\times 10^4\\ \\mathrm{Pa}$。抬起一只脚后压力不变仍为 600 N，受力面积减半 $S_2=150\\ \\mathrm{cm^2}=1.5\\times 10^{-2}\\ \\mathrm{m^2}$，$p_2=\\frac{F}{S_2}=\\frac{600\\ \\mathrm{N}}{1.5\\times 10^{-2}\\ \\mathrm{m^2}}=4\\times 10^4\\ \\mathrm{Pa}$。","explain":"这道题有两个必考点：单位换算与「哪只脚」。面积单位 cm² 化成 m² 要乘 10⁻⁴，300 cm² = 0.03 m²，这一步错一位数，结果就差 100 倍。另一个是判断受力面积：双脚站立时两只脚都着地，抬起一只脚后只有一只脚着地，压力没变而面积减半，压强正好加倍。","difficulty":2,"tags":["解答与计算","固体压强"],"rubric":["用 F = G = mg 求出压力 600 N","把 300 cm² 正确换算成 3×10⁻² m²","算出双脚站立时的压强 2×10⁴ Pa","说明抬脚后压力不变、受力面积减半，算出 4×10⁴ Pa"],"steps":["先求压力：F=G=mg=600\\ N，并说明人站在水平地面上所以压力等于重力。","单位换算：300\\ cm²=3× 10^(-2)\\ m²。","双脚站立：p₁=(F)/(S₁)=6003× 10^(-2)\\ Pa=2× 10⁴\\ Pa。","抬起一只脚：压力不变、受力面积减半，p₂=6001.5× 10^(-2)\\ Pa=4× 10⁴\\ Pa。","作答：双脚站立约 2×10⁴ Pa，单脚站立约 4×10⁴ Pa。"]},{"id":"phy-mech-6-q8","type":"short","stem":"某小组用压强计探究「液体内部压强的特点」，器材有压强计、烧杯、水、盐水、刻度尺。请写出探究压强与深度关系的步骤，并说明怎样判断压强的大小。","answer":"用压强计探究压强与深度的关系：① 把压强计的金属盒放入水中某一深度，观察并记录 U 形管两边液面的高度差；② 保持金属盒的朝向不变，依次把它放到更深的三个位置，分别记录液面高度差；③ 比较不同深度处的液面高度差，得出结论：同种液体中，深度越大，压强越大。压强的大小通过 U 形管两边液面的高度差来判断——高度差越大，说明橡皮膜受到的压强越大，这是「转换法」。若要探究压强与液体密度的关系，应把金属盒分别放在水和盐水的同一深度处，控制深度相同、只改变液体密度。","explain":"压强计把看不见的压强转换成看得见的液面高度差，这是典型的转换法。答题时要写清三件事：改变什么（深度）、保持什么不变（液体种类、朝向）、看什么（高度差）。如果只改变深度却同时换了液体，就无法判断是哪个因素在起作用。","difficulty":2,"tags":["实验探究","液体压强"],"rubric":["器材与操作：压强计的金属盒放入液体中，改变深度","用 U 形管两边液面的高度差判断压强大小（转换法）","控制其它变量：同一液体、金属盒朝向不变","得出结论：同种液体中深度越大压强越大","补充说明探究液体密度时要在同一深度比较"]},{"id":"phy-mech-6-q9","type":"short","stem":"一个装有水的烧杯静止放在水平桌面上，请在下图中画出烧杯对桌面的压力的示意图。","answer":"压力的作用点在烧杯与桌面的接触面上，方向垂直于桌面（竖直向下），画一条从接触面出发、竖直向下的带箭头线段，标上 F 或 F压。","explain":"这道作图题专治一个高频错误：把压力画在物体的重心上。压力是烧杯对桌面施加的力，作用对象是桌面，所以作用点必须落在接触面上；而重力作用在烧杯的重心上。只有当物体放在水平面上时，压力的大小才恰好等于重力，方向也恰好相同，但两者的作用点、受力物体都不同。","difficulty":3,"tags":["作图题","压力示意图"],"rubric":["作用点画在烧杯与桌面的接触面上（不是烧杯的重心）","箭头方向竖直向下、垂直于桌面","标注字母（F 或 F压）","图线从接触面出发，不与重力的示意图混同"],"figure":{"id":"fig-mech-pressure-q9-blank","title":"放在水平桌面上的烧杯","caption":"注意压力的作用点在哪里","view":"wide","alt":"一个装有水的烧杯静止放在水平桌面上，需要画出烧杯对桌面的压力","prims":[{"t":"line","x1":8,"y1":40,"x2":94,"y2":40,"width":0.8},{"t":"hatch","x":8,"y":40,"w":86,"h":4.5,"gap":2.2},{"t":"beaker","x":38,"y":12,"w":24,"h":28,"fill":0.7}]},"answerFigure":{"id":"fig-mech-pressure-q9-ans","title":"压力的示意图（标准作图）","caption":"作用点在接触面上，方向垂直于桌面","view":"wide","alt":"烧杯放在水平桌面上，从烧杯底部与桌面的接触处画出一条竖直向下的箭头表示烧杯对桌面的压力","prims":[{"t":"line","x1":8,"y1":40,"x2":94,"y2":40,"width":0.8},{"t":"hatch","x":8,"y":40,"w":86,"h":4.5,"gap":2.2},{"t":"beaker","x":38,"y":12,"w":24,"h":28,"fill":0.7},{"t":"arrow","x1":50,"y1":40,"x2":50,"y2":54,"tone":"danger","label":"F压","labelDx":7},{"t":"text","x":50,"y":60,"text":"压力的作用点在接触面上，方向垂直于桌面","size":3.6,"tone":"ok"}]}},{"id":"phy-mech-6-m1-q1","type":"short","stem":"（1）依据材料一说明：为什么管内的水银柱下降到约 760 mm 高时就不再下降？如果把玻璃管略微倾斜，水银柱的竖直高度会怎样变化？（4 分）","answer":"管内水银柱不再下降，是因为大气压向上压在水银槽的液面上，托住了管内的水银柱，此时大气压与水银柱产生的压强大小相等、互相平衡。把玻璃管倾斜时，管内水银柱的长度会变长，但水银柱的竖直高度不变，因为托住水银柱的始终是同样大小的大气压。","explain":"","tags":["大气压","托里拆利实验"],"rubric":["答出大气压与水银柱产生的压强相平衡","答出「不再下降」是因为两个压强大小相等","答出倾斜后水银柱长度变长、竖直高度不变","说明竖直高度不变的原因是大气压没有改变"]},{"id":"phy-mech-6-m1-q2","type":"short","stem":"（2）已知水银的密度为 13.6×10³ kg/m³，g 取 10 N/kg。计算 760 mm 高的水银柱产生的压强。（4 分）","answer":"$h=760\\ \\mathrm{mm}=0.76\\ \\mathrm{m}$，$p=\\rho gh=13.6\\times 10^3\\ \\mathrm{kg/m^3}\\times 10\\ \\mathrm{N/kg}\\times 0.76\\ \\mathrm{m}\\approx 1.03\\times 10^5\\ \\mathrm{Pa}$，约为 1 个标准大气压。","explain":"","tags":["液体压强计算","大气压"],"rubric":["把 760 mm 换成 0.76 m（单位统一）","正确使用 p = ρgh 并代入水银的密度","算出约 1.0×10⁵ Pa（1.03×10⁵ Pa 也对）","指出这个数值就是大气压的大小"]},{"id":"phy-mech-6-m1-q3","type":"short","stem":"（3）依据材料二、三说明：高原上为什么用普通锅煮不熟饭？高压锅又是怎么解决这个问题的？（4 分）","answer":"液体的沸点随气压的减小而降低。高原上大气压只有约 7×10⁴ Pa，比平原低得多，水的沸点降到 90 ℃ 左右，温度不够高，饭就不容易煮熟。高压锅密封性好，锅内水蒸气不能外逸，气压升高到约 2×10⁵ Pa，水的沸点随之升高到 120 ℃ 左右，温度足够高，食物就熟得快。","explain":"","tags":["说理","大气压与沸点"],"rubric":["答出液体的沸点随气压减小而降低（或随气压增大而升高）","答出高原气压低导致水的沸点降低（约 90 ℃）","说明高压锅内气压升高使水的沸点升高","结论明确：温度足够高才能把食物煮熟"]}]},{"id":"phy-mech-7","title":"浮力","subtitle":"人教版八下 · 第 10 章 浮力 · 8b","grade":"8b","tags":["人教版八下 · 第 10 章 浮力"],"blocks":[{"type":"note","title":"教材位置","text":"人教版八下 · 第 10 章 浮力 · 8b"},{"type":"note","title":"问题切入","text":"同样是铁，铁钉丢进水里会沉，几万吨的钢铁巨轮却能浮在海面上，为什么？浮力到底有多大，又该怎么把它算出来？"},{"type":"note","title":"一句话抓住关键","text":"浸在液体（或气体）中的物体受到竖直向上的浮力，浮力的大小等于它排开的液体所受的重力：$F_{浮}=\\rho_{液}gV_{排}$（阿基米德原理）。物体的浮沉由浮力与重力的大小关系决定；漂浮和悬浮都满足 $F_{浮}=G$，区别在于漂浮时 $V_{排}<V_{物}$。"},{"type":"h","text":"先看现象：三种状态同时出现"},{"type":"p","text":"把木块、空心球、铁块分别放进水里，会看到三种结果：木块漂浮在水面，球悬浮在水中任意深度，铁块沉到水底。它们都受到了水向上的托力——浮力，但托力与自身重力的大小关系不同，于是表现出的状态也不同。"},{"type":"figure","figure":{"id":"fig-mech-buoyancy-1","title":"漂浮、悬浮与下沉","caption":"同一种液体里，三种物体表现出三种状态","view":"wide","alt":"一个水槽中，木块漂浮在水面，一个球悬浮在水中，铁块沉在水底，分别标注漂浮、悬浮、下沉","prims":[{"t":"beaker","x":24,"y":12,"w":52,"h":34,"fill":0.85},{"t":"line","x1":24,"y1":17.1,"x2":76,"y2":17.1,"width":0.6,"tone":"accent"},{"t":"rect","x":32,"y":13,"w":12,"h":6,"rx":1,"fill":true,"tone":"muted"},{"t":"circle","cx":60,"cy":28,"r":3.5,"fill":true,"tone":"main"},{"t":"rect","x":46,"y":40,"w":11,"h":5.5,"fill":true,"tone":"danger"},{"t":"text","x":38,"y":8,"text":"漂浮","size":3.2,"tone":"muted"},{"t":"text","x":66,"y":28,"text":"悬浮","anchor":"start","size":3.2,"tone":"main"},{"t":"text","x":60,"y":42,"text":"下沉","anchor":"start","size":3.2,"tone":"danger"},{"t":"text","x":50,"y":56,"text":"漂浮时 F浮 = G；下沉说明 F浮 < G","size":3.6,"tone":"ok"}]}},{"type":"note","title":"","text":"浮力是液体对物体向上和向下的压力差，方向总是竖直向上。"},{"type":"h","text":"抓住哪个量：把浮力「称」出来"},{"type":"p","text":"浮力看不见，但可以用弹簧测力计称出来：先测出物体在空气中的重力 G，再把物体浸在液体中读出测力计的示数 F拉。物体静止时受三个力——向下的重力、向上的浮力和向上的拉力，由平衡关系得到 F_(浮)=G-F_(拉)，这叫称重法。例如石块在空气中重 4.0 N，浸没在水中时示数是 2.5 N，浮力就是 1.5 N。"},{"type":"figure","figure":{"id":"fig-mech-buoyancy-2","title":"称重法测浮力","caption":"弹簧测力计示数减小的部分，就是浮力的大小","view":"wide","alt":"弹簧测力计下挂着石块浸没在水中，石块上画出向上的浮力箭头和向下的重力箭头，挂钩上还有向上的拉力","prims":[{"t":"rect","x":38,"y":4,"w":24,"h":18,"tone":"main"},{"t":"spring","x1":50,"y1":7,"x2":50,"y2":14,"coils":4},{"t":"line","x1":42,"y1":16,"x2":58,"y2":16,"width":0.7,"tone":"danger"},{"t":"line","x1":50,"y1":22,"x2":50,"y2":34,"width":0.5},{"t":"beaker","x":30,"y":26,"w":44,"h":28,"fill":0.8},{"t":"rect","x":42,"y":34,"w":16,"h":12,"fill":true,"tone":"main","label":"石块"},{"t":"arrow","x1":46,"y1":44,"x2":46,"y2":30,"tone":"ok","label":"F浮","labelDx":-9},{"t":"arrow","x1":54,"y1":40,"x2":54,"y2":53,"tone":"accent","label":"G","labelDx":5},{"t":"text","x":50,"y":59,"text":"F浮 = G − F拉 = 4.0 N − 2.5 N = 1.5 N","size":3.6,"tone":"ok"}]}},{"type":"h","text":"建立关系：浮力等于排开液体所受的重力"},{"type":"p","text":"把物体浸在装满水的溢水杯里，用小桶接住溢出的水，会发现一个惊人的结果：物体受到的浮力，恰好等于它排开的那些水所受的重力。这就是阿基米德原理 F_(浮)=G_(排)=ρ_(液)gV_(排)。它有两个关键点：一是浮力只与液体密度和排开液体的体积有关，与物体的密度、形状、深度都无关；二是完全浸没后 V_(排)=V_(物)，再往下沉，V_(排) 不再变化，浮力也就不再变化。"},{"type":"figure","figure":{"id":"fig-mech-buoyancy-3","title":"阿基米德原理实验","caption":"物体受到的浮力等于它排开的液体所受的重力","view":"wide","alt":"一个装满水的溢水杯，物体浸在水中，溢出的水流入旁边的小桶，标注出浮力等于排开的水重","prims":[{"t":"line","x1":10,"y1":54,"x2":94,"y2":54,"width":0.8},{"t":"beaker","x":18,"y":18,"w":34,"h":26,"fill":0.85},{"t":"line","x1":52,"y1":20,"x2":64,"y2":20,"width":0.5},{"t":"line","x1":64,"y1":20,"x2":64,"y2":30,"width":0.5},{"t":"rect","x":28,"y":4,"w":12,"h":14,"tone":"main"},{"t":"line","x1":34,"y1":18,"x2":34,"y2":26,"width":0.5},{"t":"rect","x":28,"y":26,"w":12,"h":10,"fill":true,"tone":"main"},{"t":"rect","x":56,"y":34,"w":18,"h":16,"fill":true,"tone":"accent"},{"t":"text","x":65,"y":44,"text":"排开的水","size":3,"tone":"accent"},{"t":"text","x":78,"y":12,"text":"空的小桶接住溢出的水","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":61,"text":"F浮 = G排 = ρ液 g V排","size":3.8,"tone":"ok"}]}},{"type":"note","title":"","text":"完全浸没后继续下沉，V排 不变，浮力不变——「越深浮力越大」是错的。"},{"type":"h","text":"换个角度：浮沉由谁决定"},{"type":"p","text":"把物体浸没在液体中放手，比较浮力与重力就能判断它的去向：浮力大于重力，物体上浮，最后漂在水面上；浮力等于重力，物体悬浮在液体中任意深度；浮力小于重力，物体下沉到底。对实心物体，还可以用密度直接判断：ρ_(物)<ρ_(液) 上浮并漂浮，ρ_(物)=ρ_(液) 悬浮，ρ_(物)>ρ_(液) 下沉。"},{"type":"figure","figure":{"id":"fig-mech-buoyancy-4","title":"三种状态的受力对比","caption":"箭头长度表示力的大小：上浮时浮力大，下沉时重力大","view":"wide","alt":"三个球在水中，左边球受到的浮力大于重力所以上浮，中间球浮力等于重力所以悬浮，右边球浮力小于重力所以下沉","prims":[{"t":"line","x1":6,"y1":20,"x2":94,"y2":20,"dashed":true,"width":0.5,"tone":"accent"},{"t":"circle","cx":20,"cy":32,"r":6,"fill":true,"tone":"main"},{"t":"arrow","x1":20,"y1":32,"x2":20,"y2":12,"tone":"ok","label":"F浮","labelDx":10},{"t":"arrow","x1":20,"y1":32,"x2":20,"y2":42,"tone":"accent","label":"G","labelDx":-10},{"t":"circle","cx":50,"cy":32,"r":6,"fill":true,"tone":"main"},{"t":"arrow","x1":50,"y1":32,"x2":50,"y2":26,"tone":"ok","label":"F浮","labelDx":-10},{"t":"arrow","x1":50,"y1":32,"x2":50,"y2":38,"tone":"accent","label":"G","labelDx":10},{"t":"circle","cx":80,"cy":32,"r":6,"fill":true,"tone":"main"},{"t":"arrow","x1":80,"y1":32,"x2":80,"y2":24,"tone":"ok","label":"F浮","labelDx":10},{"t":"arrow","x1":80,"y1":32,"x2":80,"y2":46,"tone":"accent","label":"G","labelDx":-10},{"t":"text","x":20,"y":55,"text":"上浮：F浮 > G","size":3.4,"tone":"ok"},{"t":"text","x":50,"y":55,"text":"悬浮：F浮 = G","size":3.4,"tone":"main"},{"t":"text","x":80,"y":55,"text":"下沉：F浮 < G","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":61,"text":"虚线是液面：漂浮与悬浮都满足 F浮 = G","size":3.4,"tone":"muted"}]}},{"type":"h","text":"换个情境：把浮力用起来"},{"type":"p","text":"轮船把钢铁做成空心，排开水的体积大大增加，浮力随之增大到足以托住整个船身，所以能漂浮。潜水艇浸没后 V_(排) 不变、浮力不变，它靠向水舱中充水或排水来改变自身重力，从而实现下潜和上浮。热气球、孔明灯靠加热空气使气球内气体密度变小、重力变小而升空；密度计则靠漂浮时 F_(浮)=G、浸入体积随液体密度变化来测量液体密度。"},{"type":"figure","figure":{"id":"fig-mech-buoyancy-5","title":"潜水艇靠改变自身重力实现浮沉","caption":"浸没后浮力不变，改变重力就能上浮或下潜","view":"wide","alt":"水中的潜水艇剖面，艇身内有水舱，画出向水舱注水下潜和排出水上浮的两个箭头","prims":[{"t":"rect","x":10,"y":12,"w":80,"h":32,"tone":"accent"},{"t":"rect","x":32,"y":22,"w":36,"h":12,"rx":6,"fill":true,"tone":"main"},{"t":"rect","x":42,"y":25,"w":7,"h":6,"tone":"danger"},{"t":"rect","x":52,"y":25,"w":7,"h":6,"tone":"danger"},{"t":"arrow","x1":70,"y1":40,"x2":70,"y2":30,"tone":"danger","label":"注水下沉","labelDx":12},{"t":"arrow","x1":26,"y1":30,"x2":26,"y2":40,"tone":"ok","label":"排水上浮","labelDx":-12},{"t":"text","x":50,"y":52,"text":"浸没后 V排 不变 → 浮力不变，只能靠改变重力","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":58,"text":"轮船靠「空心」增大 V排；潜水艇靠水舱改变自身重力","size":3.4,"tone":"muted"}]}},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["阿基米德原理","F_(浮) = G_(排) = ρ_(液) g V_(排)","F浮：牛顿（N）；ρ液：千克每立方米（kg/m³）；V排：立方米（m³） · 适用于浸在液体或气体中的一切物体。V排 是物体排开液体的体积，不是物体的总体积：只有完全浸没时 V_(排)=V_(物)，部分浸入时 V_(排)<V_(物)。浮力只与 ρ液 和 V排 有关，与物体自身的密度、形状、浸没后的深度都无关。"],["称重法测浮力","F_(浮) = G - F_(示)","F浮、G、F示 都是力，单位牛顿（N） · 只适用于能用弹簧测力计悬挂、且能浸入液体中的物体：G 是物体在空气中的重力，F示 是浸在液体中时测力计的示数。漂浮的物体用不到这个方法，因为它没有挂在测力计上。"],["浮沉条件","F_(浮) > G \\ 上浮 F_(浮) = G \\ 悬浮或漂浮 F_(浮) < G \\ 下沉","力：牛顿（N） · 用于判断物体在液体中的去向。要注意：「上浮」是过程，物体最终会漂在液面上，此时浮力减小到与重力相等；而「悬浮」是物体可以停留在液体中任意深度。"],["漂浮时排开体积与密度的关系","V_(排)V_(物) = ρ_(物)ρ_(液)","体积：m³；密度：kg/m³（两边单位一致即可） · 只适用于漂浮（部分浸入）的实心物体：由 F_(浮)=G 即 ρ_(液)gV_(排)=ρ_(物)gV_(物) 推出。可用来求物体密度（如冰山露出十分之一，说明冰山密度约为海水的 0.9 倍），或反过来求液体密度。"]]},{"type":"h","text":"应用 · 应用一：称重法求浮力，再求体积和密度"},{"type":"note","title":"情境","text":"一个石块在空气中用弹簧测力计测得重力为 4.0 N，把它浸没在水中时弹簧测力计的示数为 2.5 N。求石块受到的浮力、石块的体积和石块的密度（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg）。"},{"type":"note","title":"模型与思路","text":"先用称重法求浮力 F_(浮)=G-F_(拉)；石块完全浸没，所以 V_(石)=V_(排)，由阿基米德原理变形得 V_(排)=F_(浮)ρ_(水)g；再由 m=(G)/(g) 求质量，用 ρ=(m)/(V) 求密度。"},{"type":"list","title":"解答步骤","items":["浮力：F_(浮)=G-F_(拉)=4.0\\ N-2.5\\ N=1.5\\ N","石块浸没，V_(石)=V_(排)=F_(浮)ρ_(水)g=1.5\\ N1.0× 10³\\ kg/m³× 10\\ N/kg=1.5× 10^(-4)\\ m³=150\\ cm³","质量：m=(G)/(g)=4.0\\ N10\\ N/kg=0.4\\ kg","密度：ρ=(m)/(V)=0.4\\ kg1.5× 10^(-4)\\ m³≈ 2.7× 10³\\ kg/m³"]},{"type":"figure","figure":{"id":"fig-mech-buoyancy-6","title":"空气中与水中两次读数","caption":"F浮 = G − F拉 = 4.0 N − 2.5 N = 1.5 N","view":"wide","alt":"左边弹簧测力计下挂着石块在空气中，示数 4.0 牛；右边同一石块浸没在水中，示数降到 2.5 牛","prims":[{"t":"rect","x":18,"y":8,"w":20,"h":16,"tone":"main"},{"t":"line","x1":28,"y1":24,"x2":28,"y2":30,"width":0.5},{"t":"rect","x":22,"y":30,"w":12,"h":10,"fill":true,"tone":"main"},{"t":"text","x":28,"y":50,"text":"空气中：4.0 N","size":3.6,"tone":"main"},{"t":"rect","x":58,"y":8,"w":20,"h":16,"tone":"main"},{"t":"line","x1":68,"y1":24,"x2":68,"y2":34,"width":0.5},{"t":"beaker","x":56,"y":26,"w":30,"h":26,"fill":0.8},{"t":"rect","x":62,"y":34,"w":12,"h":10,"fill":true,"tone":"main"},{"t":"text","x":71,"y":59,"text":"水中：2.5 N","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"石块受到的浮力是 1.5 N，体积是 150 cm³，密度约为 2.7×10³ kg/m³（与铝的密度相符）。"},{"type":"h","text":"应用 · 应用二：密度计为什么能测液体密度"},{"type":"note","title":"情境","text":"同一支密度计分别放在水和盐水中，它在盐水中露出的部分更多。为什么？轮船从河里开到海里，船身会上浮一些还是下沉一些？"},{"type":"note","title":"模型与思路","text":"密度计漂浮时 F_(浮)=G，重力不变，所以浮力也不变。由 F_(浮)=ρ_(液)gV_(排) 可知，液体密度越大，需要的 V_(排) 越小，密度计浸入得越浅。轮船同理：从河里开到海里，水的密度变大，排开水的体积变小，船身会上浮一些。"},{"type":"list","title":"解答步骤","items":["密度计漂浮，浮力与重力平衡：F_(浮)=G，所以无论放在什么液体中浮力都一样大","由 F_(浮)=ρ_(液)gV_(排) 得 V_(排)=F_(浮)ρ_(液)g：浮力不变时，ρ_(液) 越大，V_(排) 越小","盐水的密度大于水，所以密度计在盐水中浸入的体积更小、露出部分更多","轮船从河到海：海水密度更大，V_(排) 变小，船身相对水面会上浮一些（但浮力始终等于船重，大小不变）"]},{"type":"figure","figure":{"id":"fig-mech-buoyancy-7","title":"密度计在水和盐水中","caption":"液体密度越大，密度计浸入越浅","view":"wide","alt":"两支相同的密度计分别漂浮在水和盐水中，盐水中的密度计露出液面的部分更多","prims":[{"t":"beaker","x":12,"y":20,"w":26,"h":26,"fill":0.8},{"t":"line","x1":12,"y1":25.2,"x2":38,"y2":25.2,"width":0.5,"tone":"accent"},{"t":"rect","x":22,"y":12,"w":6,"h":22,"rx":3,"fill":true,"tone":"main"},{"t":"circle","cx":25,"cy":36,"r":4,"fill":true,"tone":"main"},{"t":"beaker","x":60,"y":20,"w":26,"h":26,"fill":0.8},{"t":"line","x1":60,"y1":25.2,"x2":86,"y2":25.2,"width":0.5,"tone":"accent"},{"t":"rect","x":70,"y":16,"w":6,"h":18,"rx":3,"fill":true,"tone":"main"},{"t":"circle","cx":73,"cy":36,"r":4,"fill":true,"tone":"main"},{"t":"text","x":25,"y":53,"text":"水中","size":3.4,"tone":"muted"},{"t":"text","x":73,"y":53,"text":"盐水中","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"ρ液 越大 → V排 越小 → 露出越多","size":3.6,"tone":"ok"}]}},{"type":"note","title":"结论","text":"液体密度越大，漂浮物体排开液体的体积越小。密度计刻度「上小下大」正是这个道理，轮船从河里开到海里也会上浮一些。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["认为「物体浸入液体越深，受到的浮力越大」，或认为「浮力与物体的密度有关」。","由 $F_{浮}=\\rho_{液}gV_{排}$ 可知，浮力只由液体密度和排开液体的体积决定。物体完全浸没后继续下沉，$V_{排}$ 不变，浮力也不变。","深度增加时，液体向上的压强和向下的压强都同时增大，两者之差（即浮力）不变。把浮力与压强混为一谈，就会得出「越深浮力越大」的错误结论。"],["把 $V_{排}$ 当成物体的总体积，无论物体是否完全浸没都直接代入。","部分浸入时 $V_{排}$ 只是物体浸在液体中的那部分体积，小于总体积；只有完全浸没时两者才相等。","漂浮的木块有一半体积在水面上，V_(排) 只有总体积的一半。若代入总体积，算出的浮力会偏大，与「漂浮时 F浮 = G」矛盾。"],["认为「上浮的物体受到的浮力大于漂浮时受到的浮力」，或认为「浮力大的物体一定上浮」。","物体漂浮后浮力等于自身重力，比上浮过程中的浮力小；判断浮沉要比浮力和重力的大小，不能只看浮力。","上浮时 F_(浮)>G，物体露出液面后 V_(排) 减小、浮力减小，直到 F_(浮)=G 才停在液面上。两块不同的物体受到的浮力大小不能直接比较浮沉。"],["认为「阿基米德原理只适用于漂浮的物体」，或认为「下沉的物体不受浮力」。","凡是浸在液体或气体中的物体都受到浮力，阿基米德原理对漂浮、悬浮、下沉的物体都适用。","铁块在水中下沉，是因为它的重力大于浮力，而不是不受浮力——用弹簧测力计称一称就会发现示数变小了，减小的部分正是浮力。"]]},{"type":"table","title":"漂浮与悬浮（两种状态都满足 F浮 = G，区别在排开体积）","head":["比较项","漂浮","悬浮"],"rows":[["浮力与重力","F浮 = G","F浮 = G"],["排开体积与物体体积","V排 < V物（部分浸入）","V排 = V物（完全浸没）"],["物体与液体密度","ρ物 < ρ液","ρ物 = ρ液（实心物体）"],["能停留的位置","只能停在液面上","可以停在液体中任意深度"],["典型例子","木块、轮船、密度计","悬浮的潜水艇、盐水中的鸡蛋"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["称重法测浮力并进一步求密度","给弹簧测力计在空气中和液体中的两次示数，要求依次求浮力、排开液体体积、物体体积与密度；也常给物体密度反过来求示数，是「解答与计算」的高频题型。"],["探究浮力的大小与排开液体所受重力的关系","用溢水杯与小桶做实验，考查操作（装满水、物体完全浸没、待水不再滴落再测）、比较 F浮 与 G排，以及多次测量不同物体的目的。"],["浮沉条件的判断与应用","给出物体与液体的密度或受力情况，判断上浮、悬浮还是下沉；或结合轮船、潜水艇、热气球、密度计说明「改变重力」与「改变排开体积」两条不同的技术路线。"],["浮力与压强的综合图像","以「弹簧测力计示数随浸入深度变化」或「容器底受到的压强随液面变化」的图像命题，考查「浸没前变化、浸没后不变」这一图线拐点的物理含义。"]]},{"type":"quote","text":"【材料一】某小组探究浮力的大小与排开液体所受重力的关系：用弹簧测力计测出石块的重力是 4.0 N；把石块缓慢浸没在装满水的溢水杯中，读出测力计的示数为 2.5 N；同时用空小桶收集从溢水杯溢出的水，测得小桶中水的重力为 1.5 N。\n【材料二】一艘轮船的排水量（满载时排开水的质量）是 5000 t，它在内河和海洋中都能安全航行。\n【材料三】潜水艇两侧有水舱，通过向水舱中充水或把水舱中的水排出，可以实现在水中的下潜与上浮。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）依据材料一求石块受到的浮力，并与排开的水所受的重力比较，写出实验结论。（4 分）","【设问】（2）依据材料二求轮船满载时受到的浮力，以及排开水的体积。（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg）（6 分）","【设问】（3）依据材料三说明：潜水艇浸没后受到的浮力变不变？它是靠什么实现下潜和上浮的？这与轮船增大浮力的办法有什么不同？（4 分）"]}],"questions":[{"id":"phy-mech-7-q1","type":"choice","stem":"关于浮力，下列说法正确的是","answer":"A","explain":"A 就是阿基米德原理的内容，正确。B 错：由 F_(浮)=ρ_(液)gV_(排) 可知，物体完全浸没后继续下沉，V_(排) 不变，浮力也不变。C 错：浮力取决于排开液体的体积，一个体积很大但漂浮在水面上的物体（如巨轮的一部分）排开的水未必多；体积大不等于 V排 大。D 错：浮力与液体密度成正比，同一物体浸没在水和盐水中受到的浮力不同，盐水中的更大。","options":["浸在液体中的物体受到的浮力，等于它排开的液体所受的重力","物体浸入液体越深，受到的浮力越大","物体的体积越大，受到的浮力一定越大","浮力的大小与液体的密度无关"],"difficulty":2,"tags":["阿基米德原理"]},{"id":"phy-mech-7-q2","type":"choice","stem":"用弹簧测力计悬挂一个物体，让它缓慢浸入水中，下图是测力计示数 F 随物体浸入深度 h 变化的图像。由图可知","answer":"B","explain":"图线先下降后变平：下降是因为浸入越深、排开水的体积越大、浮力越大，测力计示数 F=G-F_(浮) 越小；变平说明物体已经完全浸没，V_(排) 不再增大，浮力不再变化，B 正确。A 说「越深浮力越大」不成立——浸没后就不变了。C 错：示数从 4.0 N 降到 2.5 N，最大浮力是 4.0 N − 2.5 N = 1.5 N。D 错：图像起点的 4.0 N 才是物体的重力（此时浮力为零）。","options":["物体浸入水中越深，受到的浮力越大","物体完全浸没后继续下沉，受到的浮力保持不变","物体受到的最大浮力是 3.0 N","物体的重力是 2.5 N"],"difficulty":3,"tags":["图像分析","浮力"],"figure":{"id":"fig-mech-buoyancy-q2","title":"测力计示数随浸入深度的变化","caption":"先减小，完全浸没后保持不变","view":"square","alt":"以浸入深度为横轴、测力计示数为纵轴的图像，图线先下降，然后变成一条水平线","prims":[{"t":"axis","x":22,"y":84,"w":66,"h":64,"xLabel":"h/cm","yLabel":"F/N","origin":true,"xTicks":[{"at":0.5,"label":"5"},{"at":1,"label":"10"}],"yTicks":[{"at":0.63,"label":"2.5"},{"at":1,"label":"4.0"}]},{"t":"curve","points":[[22,20],[55,44],[88,44]],"tone":"accent"},{"t":"text","x":62,"y":34,"text":"浸没后不再变化","size":3.4,"tone":"muted"}]}},{"id":"phy-mech-7-q3","type":"choice","stem":"钢铁的密度远大于水，但用钢铁制成的轮船却能漂浮在水面上，这是因为","answer":"C","explain":"把钢铁做成空心的船体，船排开水的体积远大于同样质量的实心铁块，由 F_(浮)=ρ_(水)gV_(排) 可知浮力大大增加，足以托住整艘船，C 正确。A 错：轮船漂浮时浮力等于重力，若浮力大于重力它会继续上浮直到部分船体露出水面。B 错：做成船形并没有改变材料本身的密度，改变的是整艘船的平均密度。D 错：漂浮时浮力与重力是一对平衡力，大小相等，关系密切。","options":["轮船受到的浮力大于它受到的重力","钢铁做成轮船后，材料的密度变小了","轮船做成空心后排开水的体积增大，受到的浮力增大","水对轮船的浮力与轮船受到的重力没有关系"],"difficulty":2,"tags":["浮沉条件","应用"]},{"id":"phy-mech-7-q4","type":"choice","stem":"潜水艇要下潜时，应该","answer":"D","explain":"潜水艇完全浸没在水中，排开水的体积等于艇身体积，浮力基本不变，所以只能通过改变自身重力来控制浮沉。向水舱中充水使重力增大，当重力大于浮力时潜水艇下潜，D 正确。A、B 都是使重力减小的做法，会让潜水艇上浮。C 错：浸没后 V_(排) 不变，靠改变浮力做不到——那正是轮船与热气球的办法，不是潜水艇的办法。","options":["排出水舱中的水","减小自身受到的重力","增大自身受到的浮力","向水舱中充水，增大自身重力"],"difficulty":2,"tags":["浮沉条件","潜水艇"]},{"id":"phy-mech-7-q5","type":"fill","stem":"一个物体在空气中用弹簧测力计测得重力为 6 N，把它浸没在水中时测力计的示数为 4 N，它受到的浮力是＿＿N。","answer":"2|2.0","explain":"用称重法：F_(浮)=G-F_(示)=6\\ N-4\\ N=2\\ N。物体浸在水中时受三个力——向下的重力、向上的浮力和向上的拉力（测力计示数），由平衡关系得浮力等于重力减示数。若答 10 N 是把两个数相加了；若答 4 N，是误以为示数就是浮力。","difficulty":1,"tags":["称重法","浮力计算"]},{"id":"phy-mech-7-q6","type":"fill","stem":"一个物体浸没在水中时受到的浮力是 2 N，它排开水的体积是＿＿cm³。（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg）","answer":"200|200.0","explain":"由 F_(浮)=ρ_(水)gV_(排) 得 V_(排)=F_(浮)ρ_(水)g=2\\ N1.0× 10³\\ kg/m³× 10\\ N/kg=2× 10^(-4)\\ m³=200\\ cm³。单位换算是关键：1 m³ = 10⁶ cm³，2×10⁻⁴ m³ 就是 200 cm³，答 2×10⁻⁴ 是把单位看漏了。","difficulty":2,"tags":["阿基米德原理","单位换算"]},{"id":"phy-mech-7-q7","type":"short","stem":"一个石块在空气中用弹簧测力计测得重力是 4.0 N，把它浸没在水中时弹簧测力计的示数是 2.5 N。求石块受到的浮力、石块的体积和石块的密度。（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg）","answer":"浮力 $F_{浮}=G-F_{示}=4.0\\ \\mathrm{N}-2.5\\ \\mathrm{N}=1.5\\ \\mathrm{N}$。石块完全浸没，所以 $V_{石}=V_{排}=\\frac{F_{浮}}{\\rho_{水}g}=\\frac{1.5\\ \\mathrm{N}}{1.0\\times 10^3\\ \\mathrm{kg/m^3}\\times 10\\ \\mathrm{N/kg}}=1.5\\times 10^{-4}\\ \\mathrm{m^3}=150\\ \\mathrm{cm^3}$。质量 $m=\\frac{G}{g}=\\frac{4.0\\ \\mathrm{N}}{10\\ \\mathrm{N/kg}}=0.4\\ \\mathrm{kg}$，密度 $\\rho=\\frac{m}{V}=\\frac{0.4\\ \\mathrm{kg}}{1.5\\times 10^{-4}\\ \\mathrm{m^3}}\\approx 2.7\\times 10^3\\ \\mathrm{kg/m^3}$。","explain":"这类题把「称重法」与「阿基米德原理」串在一起，是浮力计算的标准套路：先用称重法求浮力，再用阿基米德原理求排开液体的体积，浸没时它就等于物体的体积，最后配上重力求质量与密度。要注意每一步的单位：浮力用 N，体积化成 m³ 或 cm³ 要前后一致，密度算出来是 kg/m³ 还是 g/cm³ 要写清楚。","difficulty":3,"tags":["解答与计算","浮力与密度综合"],"rubric":["用称重法算出浮力 1.5 N","说明完全浸没时 V石 = V排","由阿基米德原理算出体积 1.5×10⁻⁴ m³（或 150 cm³）","由 G = mg 算出质量 0.4 kg","算出密度约 2.7×10³ kg/m³ 并作答"],"steps":["用称重法求浮力：F_(浮)=G-F_(示)=1.5\\ N。","说明石块完全浸没，因此 V_(石)=V_(排)。","由阿基米德原理变形求体积：V_(排)=F_(浮)ρ_(水)g=1.5× 10^(-4)\\ m³=150\\ cm³。","由重力求质量：m=(G)/(g)=0.4\\ kg。","由密度公式求密度：ρ=(m)/(V)≈ 2.7× 10³\\ kg/m³，并作答。"]},{"id":"phy-mech-7-q8","type":"short","stem":"某小组用弹簧测力计、溢水杯、小桶、石块和水探究「浮力的大小与排开液体所受重力的关系」。请写出实验步骤，并说明怎样比较才能得出结论。","answer":"步骤：① 用弹簧测力计测出石块在空气中的重力 G；② 把溢水杯装满水，使水面恰好与溢水口相平，把空小桶放在溢水口下方；③ 把石块缓慢浸没在溢水杯中，待水不再滴落后读出弹簧测力计的示数 F示，同时用小桶收集溢出的水；④ 用弹簧测力计测出小桶和水的总重力，减去空桶的重力，得到排开的水所受的重力 G排；⑤ 比较 F浮 = G − F示 与 G排 的大小，若两者相等，则说明浮力等于排开液体所受的重力。为得到普遍结论，还应换用不同的物体或不同的液体重复实验。","explain":"这个实验的成败全在「水有没有收集全」：溢水杯必须先装满水、水面与溢水口齐平，石块要缓慢放入以免水溅出，读数要等水不再滴落。计算排开水的重力时不要忘记减去空桶的重力，否则 G排 会偏大。实验结论不能由一组数据得出，换用不同的物体、不同的液体重复做几次才算完整。","difficulty":2,"tags":["实验探究","阿基米德原理"],"rubric":["器材与操作：溢水杯装满水、水面与溢水口相平（否则排开的水测不准）","用称重法求出石块受到的浮力 F浮 = G − F示","用小桶收集溢出的水，测出桶与水的总重再减去空桶重，得到 G排","比较 F浮 与 G排，得出阿基米德原理","说明要换用不同物体或液体多次实验，使结论具有普遍性"]},{"id":"phy-mech-7-q9","type":"short","stem":"一块木块漂浮在水面上，请在下图中画出木块所受力的示意图。","answer":"木块受两个力：重力 G，从重心竖直向下；浮力 F浮，从重心竖直向上。木块漂浮，所以这两个力大小相等、方向相反、作用在同一条直线上，是一对平衡力。","explain":"漂浮的木块只受两个力：重力与浮力。木块静止，说明这是两个平衡力，所以两条箭头必须画得一样长、方向相反、在同一条竖直线上。最常见的错误是把浮力画得比重力长（那是上浮的过程，不是漂浮的状态），或者把浮力画在水面接触处而不是重心处。要注意浮力是液体对物体向上的托力，作用在物体上而不是在水面上。","difficulty":2,"tags":["作图题","浮力示意图"],"rubric":["重力 G：作用点在重心，方向竖直向下","浮力 F浮：作用点在重心，方向竖直向上","两个箭头长度相等（体现漂浮时 F浮 = G）","标出字母，不画出多余的力（如水对木块的压力）"],"figure":{"id":"fig-mech-buoyancy-q9-blank","title":"漂浮在水面上的木块","caption":"木块静止，说明它受到的力互相平衡","view":"wide","alt":"一个水槽中有一块木块漂浮在水面上，水面下方是水，需要画出木块受到的力","prims":[{"t":"beaker","x":26,"y":14,"w":48,"h":32,"fill":0.8},{"t":"line","x1":26,"y1":20.4,"x2":74,"y2":20.4,"width":0.6,"tone":"accent"},{"t":"rect","x":38,"y":15,"w":24,"h":11,"rx":1,"fill":true,"tone":"main"}]},"answerFigure":{"id":"fig-mech-buoyancy-q9-ans","title":"漂浮木块的受力示意图（标准作图）","caption":"重力与浮力大小相等、方向相反，是一对平衡力","view":"wide","alt":"漂浮在水面上的木块重心处画出两个箭头：重力竖直向下、浮力竖直向上，两个箭头长度相等","prims":[{"t":"beaker","x":26,"y":14,"w":48,"h":32,"fill":0.8},{"t":"line","x1":26,"y1":20.4,"x2":74,"y2":20.4,"width":0.6,"tone":"accent"},{"t":"rect","x":38,"y":15,"w":24,"h":11,"rx":1,"fill":true,"tone":"main"},{"t":"circle","cx":50,"cy":21,"r":1.5,"fill":true,"tone":"danger"},{"t":"arrow","x1":50,"y1":21,"x2":50,"y2":36,"tone":"accent","label":"G","labelDx":6},{"t":"arrow","x1":50,"y1":21,"x2":50,"y2":6,"tone":"ok","label":"F浮","labelDx":9},{"t":"text","x":50,"y":55,"text":"漂浮：F浮 = G，且 V排 < V物","size":3.6,"tone":"ok"}]}},{"id":"phy-mech-7-m1-q1","type":"short","stem":"（1）依据材料一求石块受到的浮力，并与排开的水所受的重力比较，写出实验结论。（4 分）","answer":"石块受到的浮力 $F_{浮}=G-F_{示}=4.0\\ \\mathrm{N}-2.5\\ \\mathrm{N}=1.5\\ \\mathrm{N}$。排开的水所受的重力 $G_{排}=1.5\\ \\mathrm{N}$。两者大小相等，即 $F_{浮}=G_{排}$，说明浸在液体中的物体受到的浮力等于它排开的液体所受的重力（阿基米德原理）。","explain":"","tags":["实验探究","阿基米德原理"],"rubric":["用称重法写出 F浮 = G − F示 并算得 1.5 N","写出排开水的重力 1.5 N","比较得出两者相等（F浮 = G排）","写出结论：浮力等于排开液体所受的重力"]},{"id":"phy-mech-7-m1-q2","type":"short","stem":"（2）依据材料二求轮船满载时受到的浮力，以及排开水的体积。（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg）（6 分）","answer":"轮船漂浮，浮力等于排开水的重力，也等于满载时的总重力：$F_{浮}=G_{排}=m_{排}g=5000\\times 10^3\\ \\mathrm{kg}\\times 10\\ \\mathrm{N/kg}=5\\times 10^7\\ \\mathrm{N}$。由 $F_{浮}=\\rho_{水}gV_{排}$ 得 $V_{排}=\\frac{F_{浮}}{\\rho_{水}g}=\\frac{5\\times 10^7\\ \\mathrm{N}}{1.0\\times 10^3\\ \\mathrm{kg/m^3}\\times 10\\ \\mathrm{N/kg}}=5000\\ \\mathrm{m^3}$。","explain":"","tags":["浮力计算","排水量"],"rubric":["把 5000 t 换算成 5×10⁶ kg（单位统一）","用 F浮 = G排 = m排 g 算得 5×10⁷ N","由阿基米德原理变形写出 V排 = F浮 /(ρ水 g)","算得排开水的体积 5000 m³ 并带单位"]},{"id":"phy-mech-7-m1-q3","type":"short","stem":"（3）依据材料三说明：潜水艇浸没后受到的浮力变不变？它是靠什么实现下潜和上浮的？这与轮船增大浮力的办法有什么不同？（4 分）","answer":"潜水艇完全浸没在水中，排开水的体积等于它自身的体积，下潜时深度变化不影响 $V_{排}$，由 $F_{浮}=\\rho_{水}gV_{排}$ 可知它受到的浮力保持不变。潜水艇靠向水舱中充水使自身重力变大，重力大于浮力时下潜；把水舱中的水排出使自身重力变小，重力小于浮力时上浮。轮船则是把钢铁做成空心，大大增大了排开水的体积，从而增大浮力来托住船身，它改变的是浮力而不是重力。","explain":"","tags":["说理","浮沉条件","应用"],"rubric":["答出浸没后 V排 不变、浮力不变","答出潜水艇靠改变自身重力实现下潜与上浮","说明充水使重力大于浮力而下潜（排水则上浮）","说明轮船靠增大排开水的体积来增大浮力（两条路线不同）"]}]}];
